  // If no platform specified, prompt interactively
  if (!platform) {
    platform = await promptPlatform();
  } else {
    log('\n' + BOLD + '  SAM - Smart Agent Manager' + RESET);
    log('  Autonomous TDD Agent System', CYAN);
  }

  install(platform, targetDir);
}

