                                                    style={{ backgroundColor: aiPrimaryInfo.color }}
                                                    onClick={(e) => { e.stopPropagation(); handleSelect(aiReasoning.aiRecommendedDomain); }}
                                                >
                                                    Select
                                                </button>
                                            </div>
                                        </div>

                                        {/* Secondary suggestion */}
