                {/* Footer */}
                <div className="p-4 border-t border-[var(--border)] bg-[var(--background)]">
                    <button
                        onClick={onClose}
                        className="w-full py-2.5 rounded-lg font-medium hover:bg-[var(--card)] transition-colors"
                    >
                        Cancel
                    </button>
