            </motion.div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface DiscoveredKPI {
    id: string;
    kpiName: string;
    confidence: number;
    matchType: string;
    explanation: string;
    matchedColumns: string[];
    formulaExpression: string;
    category: string;
    isComputable: boolean;
}

interface KPIDiscoveryResult {
    domain: string;
    totalKPIsAnalyzed: number;
    computableKPIs: DiscoveredKPI[];
    partialKPIs: DiscoveredKPI[];
}

interface KPIDiscoveryPanelProps {
    projectId: string;
    onClose?: () => void;
}

const CATEGORY_ICONS: Record<string, string> = {
    revenue: '💰',
    volume: '📊',
    conversion: '🎯',
    customer: '👥',
    retention: '🔄',
    engagement: '🔥',
    growth: '📈',
    profitability: '💎',
    operations: '⚙️',
    efficiency: '⚡',
    quality: '✅',
    performance: '🏆',
    cost: '💵',
    risk: '⚠️',
    liquidity: '💧',
    marketing: '📣',
    product: '📦',
    capacity: '🏗️',
};

export default function KPIDiscoveryPanel({ projectId, onClose }: KPIDiscoveryPanelProps) {
    const [discovery, setDiscovery] = useState<KPIDiscoveryResult | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [activeTab, setActiveTab] = useState<'computable' | 'partial'>('computable');
    const [expandedKPI, setExpandedKPI] = useState<string | null>(null);

    const runDiscovery = async () => {
        setLoading(true);
        setError(null);
        try {
            const res = await fetch(`/api/projects/${projectId}/kpis`, { method: 'POST' });
            const data = await res.json();
            if (!res.ok) {
                setError(data.error || 'Discovery failed');
                return;
            }
            setDiscovery(data.discovery);
        } catch (err) {
            setError('Failed to run KPI discovery');
        } finally {
            setLoading(false);
        }
    };

    const fetchExisting = async () => {
        try {
            const res = await fetch(`/api/projects/${projectId}/kpis`);
            const data = await res.json();
            if (data.discovery) {
                setDiscovery(data.discovery);
            }
        } catch (err) {
            console.error('Failed to fetch KPIs');
        }
    };

    useEffect(() => {
        fetchExisting();
    }, [projectId]);

    const getConfidenceColor = (confidence: number) => {
        if (confidence >= 80) return '#22c55e';
        if (confidence >= 60) return '#eab308';
        return '#ef4444';
    };

    const currentKPIs = activeTab === 'computable'
        ? discovery?.computableKPIs || []
        : discovery?.partialKPIs || [];

    return (
        <div className="bg-[var(--surface)] rounded-2xl border border-[var(--border)] overflow-hidden">
            {/* Header */}
            <div className="p-4 border-b border-[var(--border)] bg-gradient-to-r from-purple-500/10 to-cyan-500/10">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <span className="text-2xl">📊</span>
                        <div>
                            <h3 className="font-bold text-lg">KPI Discovery</h3>
                            <p className="text-sm text-[var(--muted)]">
                                {discovery ? `${discovery.domain} • ${discovery.totalKPIsAnalyzed} analyzed` : 'Discover measurable KPIs'}
                            </p>
                        </div>
                    </div>
                    <button
                        onClick={runDiscovery}
                        disabled={loading}
                        className="px-4 py-2 bg-gradient-to-r from-purple-500 to-cyan-500 text-white rounded-lg font-medium disabled:opacity-50"
                    >
                        {loading ? '🔍 Analyzing...' : '✨ Discover KPIs'}
                    </button>
                </div>
            </div>

            {/* Error */}
            {error && (
                <div className="p-4 bg-red-50 text-red-600 text-sm">
                    ❌ {error}
                </div>
            )}

            {/* Loading */}
            {loading && (
                <div className="p-8 text-center">
                    <div className="animate-pulse">
                        <div className="text-4xl mb-3">🔍</div>
                        <p className="text-[var(--muted)]">Analyzing your data for KPIs...</p>
                    </div>
                </div>
            )}

            {/* Results */}
            {discovery && !loading && (
                <>
                    {/* Tabs */}
                    <div className="flex border-b border-[var(--border)]">
                        <button
                            onClick={() => setActiveTab('computable')}
                            className={`flex-1 px-4 py-3 text-sm font-medium ${activeTab === 'computable' ? 'text-green-600 border-b-2 border-green-500 bg-green-50/50' : 'text-[var(--muted)]'}`}
                        >
                            ✅ Computable ({discovery.computableKPIs.length})
                        </button>
                        <button
                            onClick={() => setActiveTab('partial')}
                            className={`flex-1 px-4 py-3 text-sm font-medium ${activeTab === 'partial' ? 'text-amber-600 border-b-2 border-amber-500 bg-amber-50/50' : 'text-[var(--muted)]'}`}
                        >
                            ⚠️ Partial Match ({discovery.partialKPIs.length})
                        </button>
                    </div>

                    {/* KPI Grid */}
                    <div className="p-4 max-h-[400px] overflow-y-auto">
                        {currentKPIs.length === 0 ? (
                            <p className="text-center text-[var(--muted)] py-8">No KPIs in this category</p>
                        ) : (
                            <div className="grid gap-3">
                                <AnimatePresence mode="wait">
                                    {currentKPIs.map((kpi) => (
                                        <motion.div
                                            key={kpi.id}
                                            initial={{ opacity: 0, y: 10 }}
                                            animate={{ opacity: 1, y: 0 }}
                                            className="p-3 rounded-xl border border-[var(--border)] hover:shadow-md transition-all cursor-pointer"
                                            onClick={() => setExpandedKPI(expandedKPI === kpi.id ? null : kpi.id)}
                                        >
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-2">
                                                    <span className="text-xl">{CATEGORY_ICONS[kpi.category] || '📊'}</span>
                                                    <span className="font-medium">{kpi.kpiName}</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <span
                                                        className="text-xs px-2 py-0.5 rounded-full font-medium"
                                                        style={{ backgroundColor: `${getConfidenceColor(kpi.confidence)}20`, color: getConfidenceColor(kpi.confidence) }}
                                                    >
                                                        {kpi.confidence}%
                                                    </span>
                                                    <span className="text-xs text-[var(--muted)]">{expandedKPI === kpi.id ? '▲' : '▼'}</span>
                                                </div>
                                            </div>

                                            {/* Expanded details */}
                                            {expandedKPI === kpi.id && (
                                                <motion.div
                                                    initial={{ opacity: 0, height: 0 }}
                                                    animate={{ opacity: 1, height: 'auto' }}
                                                    className="mt-3 pt-3 border-t border-[var(--border)] space-y-2"
                                                >
                                                    <div className="text-sm text-[var(--muted)]">{kpi.explanation}</div>
                                                    <div className="text-xs">
                                                        <span className="font-medium">Formula:</span> <code className="bg-[var(--background)] px-1.5 py-0.5 rounded">{kpi.formulaExpression}</code>
                                                    </div>
                                                    <div className="flex flex-wrap gap-1">
                                                        {kpi.matchedColumns.map((col, i) => (
                                                            <span key={i} className="text-xs px-2 py-0.5 bg-purple-100 text-purple-700 rounded-full">{col}</span>
                                                        ))}
                                                    </div>
                                                </motion.div>
                                            )}
                                        </motion.div>
                                    ))}
                                </AnimatePresence>
                            </div>
                        )}
                    </div>
                </>
            )}

            {/* Empty state */}
            {!discovery && !loading && !error && (
                <div className="p-8 text-center">
                    <div className="text-4xl mb-3">📊</div>
                    <p className="text-[var(--muted)] mb-4">Click "Discover KPIs" to analyze your data</p>
                </div>
            )}
        </div>
    );
}

'use client';

// Module 6 — Ask AI Chat Panel
// Unified chat interface for all Module 6 intelligence interactions.
//
// Rendering rules:
//   6A command → "Card created: ..." or error
//   6B event   → Insight Card (title, narrative, confidence badge)
//   6C corr    → Correlation block (r, confidence, lag, narrative)
//   6E synth   → Composite insight (narrative, conflicts, supporting packets count)
//   suppressed → Neutral message (no red, no technical details)
//   error      → Clean error with retry
//
// Security:
//   - No raw JSON rendered
//   - All AI narrative escaped (no dangerouslySetInnerHTML)
//   - No model metadata shown
//   - Input length capped to 500 chars

import { useState, useRef, useEffect, useCallback } from 'react';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ChatMessage {
    id: string;
    role: 'user' | 'assistant';
    content: ChatContent;
    timestamp: Date;
}

type ChatContentBase = { conversationalPreamble?: string };
type ChatContent = ChatContentBase & (
    | { type: 'text'; text: string }
    | { type: 'insight'; kpiName: string; narrative: string; confidence: string; unit?: string }
    | { type: 'correlation'; kpiA: string; kpiB: string; rValue?: number; confidence: string; lag?: number; narrative?: string }
    | { type: 'synthesis'; narrative: string; conflictCount: number; packetCount: number; reasoningTier: string }
    | { type: 'command'; action: string; detail: string; requiresRefresh?: boolean }
    | { type: 'suppressed'; message: string }
    | { type: 'error'; message: string; recoverable: boolean }
    | {
        type: 'kpi_value';
        kpiName: string;
        value: string;
        unit: string;
        period: string;
        delta?: number | null;
        deltaPercent?: number | null;
        deltaDirection?: 'up' | 'down' | 'flat' | null;
    }
    | {
        type: 'trend_analysis';
        kpiName: string;
        trendDirection: 'up' | 'down' | 'flat';
        deltaPercent: number;
        volatilityIndex: number;
        summarySentence: string;
        dataset: any[];
    }
    | {
        type: 'comparison';
        kpiAName: string;
        kpiBName: string;
        valueA: number;
        valueB: number;
        unitA: string;
        unitB: string;
        ratio: number;
        summarySentence: string;
    }
    | {
        type: 'clarification';
        message: string;
        options: Array<{ id: string; name: string }>;
    }
    | {
        type: 'directive';
        directive: string;
        message: string;
    }
);

interface AskAIPanelProps {
    projectId: string;
    onCommandSuccess?: () => void;  // Called when 6A creates a card → trigger dashboard refresh
    onOpenGoalEngine?: (query: string) => void;  // Called when 7A requires goal engine to open
    strategyContext?: import('@/lib/module-8/types').StrategyCanvasResult; // M6→M8 State Injection
    onMessagesChange?: (msgs: { role: string; text: string }[]) => void; // Added for Report Generation
    isOpen: boolean;
    onClose: () => void;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function genId() {
    return `msg-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
}

function parseResponse(data: any): ChatContent {
    const { route, status, directive } = data;

    if (directive === 'OPEN_GOAL_ENGINE') {
        return {
            type: 'directive',
            directive: data.directive,
            message: data.message || "I've routed this to the Goal Strategy Engine.",
        };
    }

    if (status === 'suppressed') {
        return {
            type: 'suppressed',
            message: data.message || 'This insight could not be validated against the available statistical evidence.',
        };
    }

    if (status === 'causation_violation') {
        return {
            type: 'suppressed',
            message: 'The response contained language that could not be validated and was suppressed.',
        };
    }

    if (status === 'clarification_required') {
        return {
            type: 'clarification',
            message: data.message || 'I found multiple matches. Which would you like to explore?',
            options: data.options || []
        };
    }

    if (status === 'rejected' || status === 'error') {
        const isTimeout = (data.message || '').toLowerCase().includes('timed out') ||
            (data.message || '').toLowerCase().includes('timeout');

        // Natural Tone Rewrite for generic failures
        let displayMsg = data.message || 'I encountered an issue processing that query. Please try again.';
        if (status === 'rejected' && data.route === 'UNSUPPORTED_SCOPE') {
            displayMsg = "This type of query is outside my current structured reasoning capabilities. I'm focused on governed financial metrics and their relationships.";
        }

        return {
            type: 'error',
            message: displayMsg,
            recoverable: isTimeout || status === 'rejected',
        };
    }

    if (status === 'timeout') {
        return { type: 'error', message: 'AI response timed out. Please try again.', recoverable: true };
    }

    // New: KPI Scalar Read
    if (route === 'KPI_VALUE_QUERY' && status === 'success') {
        return {
            type: 'kpi_value',
            kpiName: data.kpiName,
            value: data.value,
            unit: data.unit || '',
            period: data.period || 'Total',
            delta: data.delta,
            deltaPercent: data.deltaPercent,
            deltaDirection: data.deltaDirection,
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // New: Trend Analysis
    if (route === 'TREND_ANALYSIS' && status === 'success') {
        return {
            type: 'trend_analysis',
            kpiName: data.kpiName,
            trendDirection: data.trendDirection || 'flat',
            deltaPercent: data.deltaPercent || 0,
            volatilityIndex: data.volatilityIndex || 0,
            summarySentence: data.summarySentence || 'Trend analysis complete.',
            dataset: data.dataset || [],
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // New: Comparison
    if (route === 'COMPARISON_ANALYSIS' && status === 'success') {
        return {
            type: 'comparison',
            kpiAName: data.kpiAName,
            kpiBName: data.kpiBName,
            valueA: data.valueA || 0,
            valueB: data.valueB || 0,
            unitA: data.unitA || '',
            unitB: data.unitB || '',
            ratio: data.ratio || 0,
            summarySentence: data.summarySentence || 'Comparison complete.',
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // 6A — Command
    if (route === '6A' && status === 'success') {
        const action = data.executedAction?.action || 'COMMAND';
        return {
            type: 'command',
            action,
            detail: data.message || `Command executed successfully.`,
            requiresRefresh: action === 'CREATE_CARD',
        };
    }

    // 6B — Event narration
    if (route === '6B' && status === 'success') {
        const ev = data;
        return {
            type: 'insight',
            kpiName: ev.kpiName || 'KPI',
            narrative: ev.explanation || ev.message || '',
            confidence: ev.confidence_level || ev.confidence || 'moderate',
            unit: ev.unit,
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // 6C — Correlation
    if (route === '6C') {
        if (status !== 'success') {
            return {
                type: 'error',
                message: data.message || 'The available data does not support a statistically valid conclusion.',
                recoverable: false,
            };
        }
        const ev = data.evidence || data;
        return {
            type: 'correlation',
            kpiA: ev.kpi_a_name || 'KPI A',
            kpiB: ev.kpi_b_name || 'KPI B',
            rValue: ev.statistically_significant ? ev.pearson_r : undefined,
            confidence: ev.confidence_level || 'moderate',
            lag: ev.lag_applied !== 0 ? ev.lag_applied : undefined,
            narrative: data.explanation,
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // 6E — Synthesis / Contextual Explanation
    if ((route === '6E' || route === 'CONTEXTUAL_EXPLANATION') && status === 'success') {
        return {
            type: 'synthesis',
            narrative: data.narrative || '',
            conflictCount: data.conflictSummary?.length ?? 0,
            packetCount: data.supportingPacketIds?.length ?? 0,
            reasoningTier: data.reasoningTier || (route === 'CONTEXTUAL_EXPLANATION' ? 'CONTEXTUAL_SYNTHESIS' : 'MULTI_PACKET_SYNTHESIS'),
            conversationalPreamble: data.conversationalPreamble
        };
    }

    // Fallback text
    return {
        type: 'text',
        text: data.message || data.explanation || data.narrative || 'Response received.',
    };
}

const CONFIDENCE_COLORS: Record<string, string> = {
    high: 'bg-emerald-100 text-emerald-700',
    moderate: 'bg-amber-100 text-amber-700',
    low: 'bg-slate-100 text-slate-600',
    insufficient: 'bg-slate-100 text-slate-500',
};

// ─── Message Bubble Components ────────────────────────────────────────────────

function InsightCard({ c }: { c: Extract<ChatContent, { type: 'insight' }> }) {
    const confClass = CONFIDENCE_COLORS[c.confidence] ?? CONFIDENCE_COLORS.moderate;
    return (
        <div className="ask-ai-insight-card">
            <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-semibold text-slate-500 uppercase tracking-wider">
                    {c.kpiName}{c.unit ? ` (${c.unit})` : ''}
                </span>
                <span className={`text-[10px] px-2 py-0.5 rounded-full font-medium ${confClass}`}>
                    {c.confidence} confidence
                </span>
            </div>
            <p className="text-sm leading-relaxed text-slate-800">{c.narrative}</p>
        </div>
    );
}

function CorrelationCard({ c }: { c: Extract<ChatContent, { type: 'correlation' }> }) {
    const confClass = CONFIDENCE_COLORS[c.confidence] ?? CONFIDENCE_COLORS.moderate;
    const reportable = c.rValue !== undefined;
    return (
        <div className="ask-ai-insight-card">
            <div className="flex items-center gap-2 mb-2">
                <span className="text-xs font-semibold text-slate-700">{c.kpiA}</span>
                <span className="text-slate-400">↔</span>
                <span className="text-xs font-semibold text-slate-700">{c.kpiB}</span>
                <span className={`ml-auto text-[10px] px-2 py-0.5 rounded-full font-medium ${confClass}`}>
                    {c.confidence}
                </span>
            </div>
            {reportable ? (
                <div className="flex gap-4 text-xs text-slate-600 mb-2">
                    <span>r = <strong>{c.rValue!.toFixed(3)}</strong></span>
                    {c.lag ? <span>Lag: <strong>{c.lag > 0 ? `+${c.lag}` : c.lag} period(s)</strong></span> : null}
                </div>
            ) : (
                <p className="text-xs text-slate-500 mb-2">The available data does not support a statistically valid conclusion.</p>
            )}
            {c.narrative && <p className="text-sm leading-relaxed text-slate-800">{c.narrative}</p>}
        </div>
    );
}

function SynthesisCard({ c }: { c: Extract<ChatContent, { type: 'synthesis' }> }) {
    const tierLabel: Record<string, string> = {
        SINGLE_PACKET_SUMMARY: 'Summary',
        MULTI_PACKET_SYNTHESIS: 'Multi-Signal Analysis',
        CORRELATION_CLUSTER_ANALYSIS: 'Correlation Cluster',
        STRATEGIC_FINANCIAL_OVERVIEW: 'Strategic Overview',
        RISK_SIGNAL_SYNTHESIS: 'Risk Signals',
    };
    return (
        <div className="ask-ai-insight-card synthesis">
            <div className="flex items-center gap-2 mb-2">
                <span className="text-[10px] bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full font-medium">
                    {tierLabel[c.reasoningTier] ?? 'Financial Overview'}
                </span>
                <span className="text-[10px] text-slate-400">
                    {c.packetCount} signal{c.packetCount !== 1 ? 's' : ''}
                </span>
            </div>
            <p className="text-sm leading-relaxed text-slate-800">{c.narrative}</p>
            {c.conflictCount > 0 && (
                <div className="mt-2 text-[11px] text-amber-700 bg-amber-50 rounded px-2 py-1">
                    ⚠ {c.conflictCount} signal conflict{c.conflictCount !== 1 ? 's' : ''} detected in the evidence
                </div>
            )}
        </div>
    );
}

function CommandCard({ c }: { c: Extract<ChatContent, { type: 'command' }> }) {
    return (
        <div className="ask-ai-command-card">
            <span className="material-symbols-outlined text-sm text-indigo-500">check_circle</span>
            <span className="text-sm text-slate-700">{c.detail}</span>
        </div>
    );
}

function SuppressedCard({ c }: { c: Extract<ChatContent, { type: 'suppressed' }> }) {
    return (
        <div className="ask-ai-suppressed-card">
            <span className="text-sm text-slate-500">{c.message}</span>
        </div>
    );
}

function ErrorCard({ c, onRetry }: { c: Extract<ChatContent, { type: 'error' }>; onRetry?: () => void }) {
    return (
        <div className="ask-ai-error-card">
            <span className="text-sm text-slate-600">{c.message}</span>
            {c.recoverable && onRetry && (
                <button onClick={onRetry} className="ask-ai-retry-btn">Retry</button>
            )}
        </div>
    );
}

function ScalarKpiCard({ c }: { c: Extract<ChatContent, { type: 'kpi_value' }> }) {
    const renderDelta = () => {
        if (!c.deltaDirection || typeof c.deltaPercent !== 'number') return null;

        const isPositive = c.deltaDirection === 'up';

        let colorClass = 'text-slate-500';
        let arrow = '−';

        if (isPositive) {
            colorClass = 'text-green-600';
            arrow = '↑';
        } else if (c.deltaDirection === 'down') {
            colorClass = 'text-rose-600';
            arrow = '↓';
        }

        return (
            <div className={`text-sm font-medium flex items-center gap-1 ${colorClass} mt-1`}>
                <span>{arrow}</span>
                <span>{Math.abs(c.deltaPercent).toFixed(1)}%</span>
                <span className="text-xs text-slate-400 font-normal ml-1">compared to previous period</span>
            </div>
        );
    };

    return (
        <div className="ask-ai-insight-card p-4 rounded-xl border border-slate-100 bg-white shadow-sm w-full max-w-sm">
            <div className="flex flex-col gap-1">
                <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-widest">
                    {c.kpiName}
                </span>
                <span className="text-3xl font-bold text-slate-900 tracking-tight">
                    {c.unit && c.unit !== 'number' ? `${c.unit} ` : ''}
                    {Number(c.value).toLocaleString(undefined, { maximumFractionDigits: 2 })}
                </span>
                {renderDelta()}
                <span className="text-[10px] text-slate-400 mt-2 block border-t border-slate-50 pt-2">
                    Period: {c.period}
                </span>
            </div>
        </div>
    );
}

function TrendCard({ c }: { c: Extract<ChatContent, { type: 'trend_analysis' }> }) {
    const isPositive = c.trendDirection === 'up';
    const isNegative = c.trendDirection === 'down';

    let colorClass = 'text-slate-500';
    let bgClass = 'bg-slate-50 text-slate-500 border-slate-200';
    let icon = 'trending_flat';

    if (isPositive) {
        colorClass = 'text-green-600';
        bgClass = 'bg-green-50 text-green-700 border-green-200';
        icon = 'trending_up';
    } else if (isNegative) {
        colorClass = 'text-rose-600';
        bgClass = 'bg-rose-50 text-rose-700 border-rose-200';
        icon = 'trending_down';
    }

    return (
        <div className="ask-ai-insight-card p-4 rounded-xl border border-slate-100 bg-white shadow-sm w-full max-w-lg">
            <div className="flex items-center gap-2 mb-3">
                <span className={`px-2 py-0.5 rounded-full text-[10px] font-semibold border ${bgClass} uppercase tracking-wider flex items-center gap-1`}>
                    <span className="material-symbols-outlined text-[14px]">{icon}</span>
                    {Math.abs(c.deltaPercent).toFixed(1)}% {c.trendDirection}
                </span>
                <span className="text-[10px] font-semibold text-slate-400 uppercase tracking-widest pl-2 border-l border-slate-200">
                    {c.kpiName} Trend
                </span>
            </div>

            <p className="text-sm leading-relaxed text-slate-800 font-medium mb-3">
                {c.summarySentence}
            </p>

            {/* Sparkline visualization logic here eventually */}
            {c.dataset.length > 0 && (
                <div className="h-12 w-full flex items-end justify-between gap-1 opacity-60">
                    {c.dataset.map((pt, i) => (
                        <div
                            key={i}
                            className={`w-full rounded-sm ${isNegative ? 'bg-rose-200' : isPositive ? 'bg-green-200' : 'bg-slate-200'}`}
                            style={{
                                height: `${Math.max(10, (pt.value / Math.max(...c.dataset.map(d => d.value))) * 100)}%`,
                                minHeight: '4px'
                            }}
                        />
                    ))}
                </div>
            )}
        </div>
    );
}

function ComparisonCard({ c }: { c: Extract<ChatContent, { type: 'comparison' }> }) {
    return (
        <div className="ask-ai-insight-card p-4 rounded-xl border border-indigo-100 bg-white shadow-sm w-full max-w-lg">
            <div className="flex items-center gap-2 mb-4">
                <span className="px-2 py-0.5 rounded-full text-[10px] font-semibold border bg-indigo-50 text-indigo-700 border-indigo-200 uppercase tracking-wider">
                    Comparison
                </span>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-4">
                <div className="p-3 bg-slate-50 rounded-lg border border-slate-100 flex flex-col items-center text-center">
                    <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-widest mb-1">{c.kpiAName}</span>
                    <span className="text-xl font-bold text-slate-900">
                        {c.unitA === 'currency' ? '$' : c.unitA === 'percentage' ? '' : ''}
                        {c.valueA.toLocaleString(undefined, { maximumFractionDigits: 1 })}
                        {c.unitA === 'percentage' ? '%' : ''}
                    </span>
                </div>
                <div className="p-3 bg-slate-50 rounded-lg border border-slate-100 flex flex-col items-center text-center">
                    <span className="text-[10px] font-semibold text-slate-500 uppercase tracking-widest mb-1">{c.kpiBName}</span>
                    <span className="text-xl font-bold text-slate-900">
                        {c.unitB === 'currency' ? '$' : c.unitB === 'percentage' ? '' : ''}
                        {c.valueB.toLocaleString(undefined, { maximumFractionDigits: 1 })}
                        {c.unitB === 'percentage' ? '%' : ''}
                    </span>
                </div>
            </div>

            <p className="text-sm leading-relaxed text-slate-800 font-medium">
                {c.summarySentence}
            </p>
        </div>
    );
}

function ClarificationCard({ c, onSelect }: { c: Extract<ChatContent, { type: 'clarification' }>; onSelect: (name: string) => void }) {
    return (
        <div className="ask-ai-insight-card p-4 rounded-xl border border-amber-100 bg-amber-50 shadow-sm w-full max-w-sm">
            <p className="text-sm font-medium text-amber-900 mb-3">{c.message}</p>
            <div className="flex flex-wrap gap-2">
                {c.options.map(opt => (
                    <button
                        key={opt.id}
                        onClick={() => onSelect(opt.name)}
                        className="px-3 py-1.5 bg-white border border-amber-200 rounded-lg text-xs font-semibold text-amber-700 hover:bg-amber-100 transition-colors"
                    >
                        {opt.name}
                    </button>
                ))}
            </div>
        </div>
    );
}

function DirectiveCard({ c }: { c: Extract<ChatContent, { type: 'directive' }> }) {
    return (
        <div className="ask-ai-insight-card p-4 rounded-xl border border-indigo-100 bg-white shadow-sm w-full max-w-sm">
            <div className="flex items-center gap-2 mb-2">
                <span className="material-symbols-outlined text-indigo-600 text-lg">route</span>
                <h3 className="text-sm font-bold text-slate-800">Routing Request</h3>
            </div>
            <p className="text-sm text-slate-600">
                {c.message}
            </p>
        </div>
    );
}

function MessageBubble({ msg, onRetry, onClarify }: { msg: ChatMessage; onRetry?: () => void; onClarify?: (name: string) => void }) {
    const isUser = msg.role === 'user';
    const c = msg.content;

    if (isUser && c.type === 'text') {
        return (
            <div className="flex justify-end mb-3">
                <div className="ask-ai-user-bubble">{c.text}</div>
            </div>
        );
    }

    return (
        <div className="flex justify-start mb-3">
            <div className="ask-ai-assistant-wrapper">
                <div className="ask-ai-avatar">
                    <span className="material-symbols-outlined text-sm text-indigo-600">psychology</span>
                </div>
                <div className="flex-1">
                    {c.conversationalPreamble && <p className="text-sm text-slate-800 leading-relaxed mb-3">{c.conversationalPreamble}</p>}
                    {c.type === 'text' && !c.conversationalPreamble && <p className="text-sm text-slate-700 leading-relaxed">{c.text}</p>}
                    {c.type === 'insight' && <InsightCard c={c} />}
                    {c.type === 'correlation' && <CorrelationCard c={c} />}
                    {c.type === 'synthesis' && <SynthesisCard c={c} />}
                    {c.type === 'command' && <CommandCard c={c} />}
                    {c.type === 'suppressed' && <SuppressedCard c={c} />}
                    {c.type === 'error' && <ErrorCard c={c} onRetry={onRetry} />}
                    {c.type === 'kpi_value' && <ScalarKpiCard c={c} />}
                    {c.type === 'trend_analysis' && <TrendCard c={c} />}
                    {c.type === 'comparison' && <ComparisonCard c={c} />}
                    {c.type === 'clarification' && <ClarificationCard c={c} onSelect={onClarify || (() => { })} />}
                    {c.type === 'directive' && <DirectiveCard c={c} />}
                    <span className="text-[10px] text-slate-400 mt-1 block">
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                </div>
            </div>
        </div>
    );
}

// ─── Panel ────────────────────────────────────────────────────────────────────

export function AskAIPanel({ projectId, onCommandSuccess, onOpenGoalEngine, strategyContext, onMessagesChange, isOpen, onClose }: AskAIPanelProps) {
    const [messages, setMessages] = useState<ChatMessage[]>([
        {
            id: genId(),
            role: 'assistant',
            timestamp: new Date(),
            content: {
                type: 'text',
                text: "Hi! I can explain KPI trends, show correlations, create dashboard cards, or give you a financial overview. What would you like to explore?",
            },
        },
    ]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [lastUserMessage, setLastUserMessage] = useState('');
    const [suggestions, setSuggestions] = useState<string[]>([]);
    const bottomRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLInputElement>(null);

    // Scroll to bottom on new messages
    useEffect(() => {
        bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages, isLoading]);

    // Lift message state up for global reporting
    useEffect(() => {
        if (onMessagesChange) {
            onMessagesChange(messages.map(m => ({ 
                role: m.role, 
                text: 'text' in m.content && typeof m.content.text === 'string'
                         ? m.content.text 
                         : 'narrative' in m.content && typeof m.content.narrative === 'string'
                             ? m.content.narrative
                             : `[${m.content.type.toUpperCase()} Response]`
            })));
        }
    }, [messages, onMessagesChange]);

    // Focus input when panel opens
    useEffect(() => {
        if (isOpen) setTimeout(() => inputRef.current?.focus(), 100);
    }, [isOpen]);

    const sendMessage = useCallback(async (messageText: string) => {
        if (!messageText.trim() || isLoading) return;

        const userMsg: ChatMessage = {
            id: genId(),
            role: 'user',
            timestamp: new Date(),
            content: { type: 'text', text: messageText.trim() },
        };
        setMessages(prev => [...prev, userMsg]);
        setLastUserMessage(messageText.trim());
        setInput('');
        setSuggestions([]); // Clear suggestions when user sends new message
        setIsLoading(true);

        // 3-second client-side timeout sentinel
        const clientTimeout = setTimeout(() => {
            setMessages(prev => [...prev, {
                id: genId(),
                role: 'assistant',
                timestamp: new Date(),
                content: { type: 'error', message: 'AI response timed out. Please try again.', recoverable: true },
            }]);
            setIsLoading(false);
        }, 3000);

        try {
            const res = await fetch(`/api/projects/${projectId}/ask-ai`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    message: messageText.trim(),
                    sessionId: projectId,
                    // State Injection Pipeline: forward live strategy context to the AI
                    ...(strategyContext ? { strategyContext } : {}),
                }),
            });

            clearTimeout(clientTimeout);

            const data = await res.json();
            const content = parseResponse(data);

            setMessages(prev => [...prev, {
                id: genId(),
                role: 'assistant',
                timestamp: new Date(),
                content,
            }]);

            // Add suggestions if present
            if (data.suggestions && Array.isArray(data.suggestions)) {
                setSuggestions(data.suggestions);
            }

            // Trigger dashboard refresh on successful 6A command
            if (content.type === 'command' && content.requiresRefresh) {
                onCommandSuccess?.();
            }

            // Trigger goal engine on 7A directive
            if (content.type === 'directive' && content.directive === 'OPEN_GOAL_ENGINE') {
                if (onOpenGoalEngine) {
                    setTimeout(() => onOpenGoalEngine(messageText.trim()), 800); // slight delay for better UX
                }
            }
        } catch {
            clearTimeout(clientTimeout);
            setMessages(prev => [...prev, {
                id: genId(),
                role: 'assistant',
                timestamp: new Date(),
                content: { type: 'error', message: 'Failed to reach the analytics engine. Please try again.', recoverable: true },
            }]);
        } finally {
            setIsLoading(false);
        }
    }, [projectId, isLoading, onCommandSuccess]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (input.trim()) sendMessage(input);
    };

    const handleRetry = () => sendMessage(lastUserMessage);

    if (!isOpen) return null;

    return (
        <>
            {/* Backdrop */}
            <div className="ask-ai-backdrop" onClick={onClose} aria-label="Close Ask AI panel" />

            {/* Panel */}
            <div className="ask-ai-panel" role="dialog" aria-label="Ask AI" aria-modal="true">
                {/* Header */}
                <div className="ask-ai-header">
                    <div className="flex items-center gap-2">
                        <div className="w-7 h-7 rounded-full bg-indigo-100 flex items-center justify-center">
                            <span className="material-symbols-outlined text-sm text-indigo-600">psychology</span>
                        </div>
                        <div>
                            <h2 className="text-sm font-semibold text-slate-800">Vistara Intelligence</h2>
                            <p className="text-[10px] text-slate-400">Evidence-governed analytics</p>
                        </div>
                    </div>
                    <div className="flex items-center gap-2">
                        <button
                            onClick={() => setMessages([{
                                id: genId(), role: 'assistant', timestamp: new Date(),
                                content: { type: 'text', text: "Chat cleared. What would you like to explore?" },
                            }])}
                            className="ask-ai-clear-btn"
                            title="Clear chat"
                        >
                            <span className="material-symbols-outlined text-sm">delete_sweep</span>
                        </button>
                        <button onClick={onClose} className="ask-ai-close-btn" title="Close">
                            <span className="material-symbols-outlined text-sm">close</span>
                        </button>
                    </div>
                </div>

                {/* Messages */}
                <div className="ask-ai-messages">
                    {messages.map(msg => (
                        <MessageBubble
                            key={msg.id}
                            msg={msg}
                            onRetry={handleRetry}
                            onClarify={(name) => sendMessage(name)}
                        />
                    ))}
                    {isLoading && (
                        <div className="flex justify-start mb-3">
                            <div className="ask-ai-assistant-wrapper">
                                <div className="ask-ai-avatar">
                                    <span className="material-symbols-outlined text-sm text-indigo-600">psychology</span>
                                </div>
                                <div className="ask-ai-typing-indicator">
                                    <span /><span /><span />
                                </div>
                            </div>
                        </div>
                    )}
                    <div ref={bottomRef} />
                </div>

                {/* Suggestions Footer */}
                {!isLoading && suggestions.length > 0 && (
                    <div className="px-4 py-2 flex flex-wrap gap-2 border-t border-slate-50 bg-slate-50/30">
                        {suggestions.map((s, i) => (
                            <button
                                key={i}
                                onClick={() => sendMessage(s)}
                                className="px-3 py-1.5 bg-white border border-slate-200 rounded-full text-xs font-medium text-slate-600 hover:border-indigo-300 hover:text-indigo-600 transition-all flex items-center gap-1.5"
                            >
                                <span className="material-symbols-outlined text-[14px]">auto_awesome</span>
                                {s}
                            </button>
                        ))}
                    </div>
                )}

                {/* Input */}
                <form onSubmit={handleSubmit} className="ask-ai-input-area">
                    <input
                        ref={inputRef}
                        type="text"
                        value={input}
                        onChange={e => {
                            // Cap at 500 chars (security)
                            if (e.target.value.length <= 500) setInput(e.target.value);
                        }}
                        placeholder="Ask about KPIs, correlations, or request a chart…"
                        disabled={isLoading}
                        className="ask-ai-input"
                        maxLength={500}
                        aria-label="Message input"
                    />
                    <button
                        type="submit"
                        disabled={isLoading || !input.trim()}
                        className="ask-ai-send-btn"
                        aria-label="Send message"
                    >
                        <span className="material-symbols-outlined text-sm">send</span>
                    </button>
                </form>

                {/* Input char count hint */}
                {input.length > 400 && (
                    <p className="text-[10px] text-amber-500 px-4 pb-2">{500 - input.length} characters remaining</p>
                )}
            </div>
        </>
    );
}

'use client';

// Module 5 — Dashboard Shell (Premium Glassmorphism Redesign)
// 2×2 KPI grid, AI Insights section, Active Streams, FilterBar, drill-down breadcrumb

import { useState, useCallback } from 'react';
import { Sidebar } from './Sidebar';
import { Header } from './Header';
import { KPIMetricCard } from './KPIMetricCard';
import { ChartGrid } from './ChartGrid';
import { SkeletonLoader } from './SkeletonLoader';
import { InsightPanel } from './InsightPanel';
import { SmartAlertBanner } from './SmartAlertBanner';
import { FilterBar, type DashboardFilters } from './FilterBar';
import { AIFilter } from './AIFilter';
import { AskAIPanel } from './AskAIPanel';
import { GoalStrategyPanel } from './GoalStrategyPanel';
import { ForecastPanel } from './ForecastPanel';
import type { KPICardData, KPIExplanationData, DashboardSection, InsightFeedItem, SmartAlert } from './types';
import { getAvailableRanges, type DateRange, type Granularity } from './ChartContainer';
import type { StrategyCanvasResult } from '@/lib/module-8/types';
import { DashboardErrorBoundary } from './DashboardErrorBoundary';

interface DrillState {
    kpiId: string;
    kpiName: string;
    dimensionLabel: string;
    value: number;
}

interface DashboardShellProps {
    projectId: string;
    projectName: string;
    domainIcon: string;
    domainName: string;
    domainColor: string;
    sections: DashboardSection[];
    kpis: KPICardData[];
    explanations: Record<string, KPIExplanationData>;
    isLoading: boolean;
    isRefreshing: boolean;
    onRefresh: () => void;
    onFilterChange?: (filters: DashboardFilters) => void;
    // Module 5C additions
    insightFeed?: InsightFeedItem[];
    smartAlerts?: SmartAlert[];
    strongestUp?: InsightFeedItem | null;
    strongestDown?: InsightFeedItem | null;
    anomalyCount?: number;
    trendingUp?: number;
    trendingDown?: number;
}

export function DashboardShell({
    projectId, projectName, domainIcon, domainName, domainColor,
    sections, kpis, explanations, isLoading, isRefreshing, onRefresh,
    onFilterChange,
    insightFeed = [], smartAlerts = [],
    strongestUp = null, strongestDown = null,
    anomalyCount = 0, trendingUp = 0, trendingDown = 0,
}: DashboardShellProps) {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [activeSection, setActiveSection] = useState<string | undefined>();
    const [insightPanelOpen, setInsightPanelOpen] = useState(false);
    const [askAiOpen, setAskAiOpen] = useState(false);
    const [goalPanelOpen, setGoalPanelOpen] = useState(false);
    const [forecastPanelOpen, setForecastPanelOpen] = useState(false);
    const [goalQuery, setGoalQuery] = useState('');
    // Active StrategyCanvasResult shared between GoalStrategyPanel and AskAIPanel
    // (implements the State Injection Pipeline from MODULE_6_7_8_INTEGRATION_PLAN.md)
    const [activeStrategyContext, setActiveStrategyContext] = useState<StrategyCanvasResult | null>(null);
    const [askAiMessages, setAskAiMessages] = useState<{ role: string; text: string }[]>([]);
    const [drillStack, setDrillStack] = useState<DrillState[]>([]);
    const [filters, setFilters] = useState<DashboardFilters>({
        granularity: 'monthly',
        dateRange: '90d',
    });

    // Bulk selection & filtering state
    const [selectedKpis, setSelectedKpis] = useState<Set<string>>(new Set());
    const [externalFilters, setExternalFilters] = useState<Record<string, { range: DateRange; gran: Granularity; ts: number }>>({});

    // UI state for bottom bar
    const [bottomDateRange, setBottomDateRange] = useState<DateRange>('90d');
    const [bottomGranularity, setBottomGranularity] = useState<Granularity>('monthly');

    const handleExportPDF = () => {
        window.print();
    };

    const toggleKpiSelection = useCallback((kpiId: string) => {
        setSelectedKpis(prev => {
            const next = new Set(prev);
            if (next.has(kpiId)) next.delete(kpiId);
            else next.add(kpiId);
            return next;
        });
    }, []);

    const clearSelection = useCallback(() => setSelectedKpis(new Set()), []);
    const selectAll = useCallback(() => setSelectedKpis(new Set(kpis.map(k => k.kpiId))), [kpis]);

    const applyFilterToSelected = useCallback(() => {
        const ts = Date.now();
        setExternalFilters(prev => {
            const next = { ...prev };
            selectedKpis.forEach(id => {
                next[id] = { range: bottomDateRange, gran: bottomGranularity, ts };
            });
            return next;
        });
        clearSelection(); // Optional: clears selection after applying
    }, [selectedKpis, bottomDateRange, bottomGranularity, clearSelection]);

    const kpiMap = new Map(kpis.map(k => [k.kpiId, k]));

    // Get top 4 KPIs for the main grid
    const topKpis = kpis.slice(0, 4);

    // ── Filter Change ──────────────────────────────────────────────
    const handleFilterChange = useCallback((f: DashboardFilters) => {
        setFilters(f);
        onFilterChange?.(f);
    }, [onFilterChange]);

    // ── Drill-down ─────────────────────────────────────────────────
    const handleDrillDown = useCallback((kpiId: string, label: string, value: number) => {
        const kpi = kpiMap.get(kpiId);
        if (!kpi) return;
        setDrillStack(prev => [...prev, { kpiId, kpiName: kpi.kpiName, dimensionLabel: label, value }]);
    }, [kpiMap]);

    const handleDrillUp = (index: number) => {
        setDrillStack(prev => prev.slice(0, index));
    };

    const clearDrill = () => setDrillStack([]);

    // Build AI insight summary for welcome subtitle
    const aiSummary = strongestUp
        ? `AI has detected a ${Math.abs(strongestUp.deltaPercent || 0).toFixed(1)}% surge in ${strongestUp.kpiName.replace(/_/g, ' ')} today.`
        : anomalyCount > 0
            ? `${anomalyCount} anomalies detected across your KPIs.`
            : `All ${kpis.length} KPIs are performing within expected range.`;

    return (
        <div className="dashboard-layout dashboard-root">
            {/* Slim Sidebar */}
            <Sidebar
                projectId={projectId}
                projectName={projectName}
                domainIcon={domainIcon}
                domainName={domainName}
                domainColor={domainColor}
                sections={sections.map(s => ({ id: s.id, title: s.title, icon: s.icon }))}
                activeSection={activeSection}
                isOpen={sidebarOpen}
                onToggle={() => setSidebarOpen(!sidebarOpen)}
            />

            {/* Main Content */}
            <main className="dashboard-main">
                {/* Frosted Glass Header */}
                <Header
                    title="Data Intelligence"
                    subtitle={domainName}
                    kpiCount={kpis.length}
                    onRefresh={onRefresh}
                    onToggleSidebar={() => setSidebarOpen(!sidebarOpen)}
                    isRefreshing={isRefreshing}
                >
                    {/* Insight Panel Toggle */}
                    <button
                        onClick={() => setInsightPanelOpen(!insightPanelOpen)}
                        className="relative flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-slate-100 hover:bg-slate-200 text-slate-700 transition-colors"
                        title="Open Insights Panel"
                    >
                        <span className="material-symbols-outlined text-base">psychology</span>
                        Insights
                        {anomalyCount > 0 && (
                            <span className="bg-red-500 text-white text-[9px] font-bold w-4 h-4 rounded-full flex items-center justify-center">
                                {anomalyCount}
                            </span>
                        )}
                    </button>

                    {/* Goal Strategy Engine Toggle */}
                    <button
                        onClick={() => setGoalPanelOpen(true)}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-violet-100 hover:bg-violet-200 text-violet-700 transition-colors"
                        title="Goal Strategy Engine"
                    >
                        <span className="material-symbols-outlined text-base">target</span>
                        Strategy
                    </button>
                </Header>

                <div className="p-8 space-y-8">
                    {/* ── Welcome Section ────────────────────────────── */}
                    <div className="flex justify-between items-end">
                        <div>
                            <h1 className="welcome-title">Executive Overview</h1>
                            <p className="welcome-subtitle">
                                <span className="material-symbols-outlined text-emerald-500 text-sm font-bold">verified</span>
                                {aiSummary}
                            </p>
                        </div>
                        <div className="flex gap-2">
                            {/* Filter Bar */}
                            {!isLoading && (
                                <>
                                    <button className="px-4 py-2 rounded-lg bg-white border border-slate-200 text-sm font-medium hover:bg-slate-50 transition-all flex items-center gap-2">
                                        <span className="material-symbols-outlined text-lg text-slate-500">calendar_today</span>
                                        {filters.dateRange === '30d' ? 'Last 30 Days' :
                                            filters.dateRange === '90d' ? 'Last 90 Days' :
                                                filters.dateRange === '7d' ? 'Last 7 Days' : 'All Time'}
                                    </button>
                                    <AIFilter onFilterGenerated={handleFilterChange} />
                                    <button 
                                        onClick={handleExportPDF}
                                        className="px-4 py-2 rounded-lg bg-white border border-slate-200 text-sm font-medium hover:bg-slate-50 transition-all flex items-center gap-2"
                                    >
                                        <span className="material-symbols-outlined text-lg text-slate-500">ios_share</span>
                                        Export PDF
                                    </button>
                                </>
                            )}
                        </div>
                    </div>

                    {/* ── Filter Bar (Advanced) ──────────────────────── */}
                    {!isLoading && (
                        <FilterBar
                            filters={filters}
                            onChange={handleFilterChange}
                            loading={isRefreshing}
                        />
                    )}

                    {/* ── Drill-down Breadcrumb ──────────────────────── */}
                    {drillStack.length > 0 && (
                        <div className="drilldown-bar">
                            <span className="drilldown-crumb" onClick={clearDrill} title="Back to overview">
                                Overview
                            </span>
                            {drillStack.map((crumb, i) => (
                                <span key={i} style={{ display: 'contents' }}>
                                    <span className="drilldown-sep">›</span>
                                    {i < drillStack.length - 1 ? (
                                        <span className="drilldown-crumb" onClick={() => handleDrillUp(i + 1)}>
                                            {crumb.kpiName}: {crumb.dimensionLabel}
                                        </span>
                                    ) : (
                                        <span className="drilldown-current">
                                            {crumb.kpiName}: {crumb.dimensionLabel}
                                        </span>
                                    )}
                                </span>
                            ))}
                            <button className="drilldown-reset-btn" onClick={clearDrill}>
                                ✕ Clear
                            </button>
                        </div>
                    )}

                    {isLoading ? (
                        <SkeletonLoader />
                    ) : (
                        <>
                            {/* Smart Alert Banner */}
                            <SmartAlertBanner
                                alerts={smartAlerts}
                                onViewAll={() => setInsightPanelOpen(true)}
                            />

                            {/* ── 2×2 KPI Card Grid ──────────────────── */}
                            <div id="dashboard-grid-container" className="dashboard-grid">
                                {topKpis.map((kpi) => (
                                    <KPIMetricCard
                                        key={kpi.kpiId}
                                        data={kpi}
                                        explanation={explanations[kpi.kpiId]}
                                    />
                                ))}
                            </div>

                            {/* ── AI Generated Insights Section ──────── */}
                            {(insightFeed.length > 0 || anomalyCount > 0 || strongestUp || strongestDown) && (
                                <div className="ai-insights-section mt-8">
                                    <div className="flex items-center gap-4 mb-6">
                                        <div className="w-12 h-12 rounded-full flex items-center justify-center"
                                            style={{ background: 'rgba(19, 91, 236, 0.1)' }}>
                                            <span className="material-symbols-outlined" style={{ color: '#135bec' }}>psychology</span>
                                        </div>
                                        <div>
                                            <h2 className="text-xl font-bold" style={{ color: 'var(--color-text-primary)' }}>
                                                Vistara AI Insights
                                            </h2>
                                            <p className="text-sm" style={{ color: 'var(--color-text-secondary)' }}>
                                                Deep learning analysis based on your historical data.
                                            </p>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                        {/* Anomaly Card */}
                                        {anomalyCount > 0 && (
                                            <div className="ai-insight-card">
                                                <span className="ai-insight-label anomaly">Anomaly Detected</span>
                                                <p className="mt-2 text-sm leading-relaxed" style={{ color: 'var(--color-text-primary)' }}>
                                                    {insightFeed.find(f => f.type === 'anomaly')?.description
                                                        || `${anomalyCount} anomal${anomalyCount === 1 ? 'y' : 'ies'} detected across your KPIs. Investigate unusual patterns.`}
                                                </p>
                                            </div>
                                        )}

                                        {/* Growth Card */}
                                        {strongestUp && (
                                            <div className="ai-insight-card">
                                                <span className="ai-insight-label growth">Growth Opportunity</span>
                                                <p className="mt-2 text-sm leading-relaxed" style={{ color: 'var(--color-text-primary)' }}>
                                                    <span className="font-bold">{strongestUp.kpiName.replace(/_/g, ' ')}</span> surged
                                                    by {Math.abs(strongestUp.deltaPercent || 0).toFixed(1)}%. {strongestUp.description || 'Analyze contributing factors to sustain growth.'}
                                                </p>
                                            </div>
                                        )}

                                        {/* Warning Card */}
                                        {strongestDown && (
                                            <div className="ai-insight-card">
                                                <span className="ai-insight-label warning">Churn Warning</span>
                                                <p className="mt-2 text-sm leading-relaxed" style={{ color: 'var(--color-text-primary)' }}>
                                                    <span className="font-bold">{strongestDown.kpiName.replace(/_/g, ' ')}</span> dropped
                                                    by {Math.abs(strongestDown.deltaPercent || 0).toFixed(1)}%. {strongestDown.description || 'AI suggests proactive investigation.'}
                                                </p>
                                            </div>
                                        )}

                                        {/* Fallback cards when no specific insights */}
                                        {anomalyCount === 0 && !strongestUp && !strongestDown && insightFeed.length > 0 && (
                                            insightFeed.slice(0, 3).map((item) => (
                                                <div key={item.id} className="ai-insight-card">
                                                    <span className={`ai-insight-label ${item.type === 'anomaly' ? 'anomaly' :
                                                        item.type === 'movement' ? 'growth' : 'warning'
                                                        }`}>
                                                        {item.title}
                                                    </span>
                                                    <p className="mt-2 text-sm leading-relaxed" style={{ color: 'var(--color-text-primary)' }}>
                                                        {item.description}
                                                    </p>
                                                </div>
                                            ))
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* ── Chart Sections per Domain ──────────── */}
                            {sections.map((section) => {
                                const sectionKpis = section.kpiIds
                                    .map(id => kpiMap.get(id))
                                    .filter((k): k is KPICardData => k !== undefined);

                                if (sectionKpis.length === 0) return null;

                                return (
                                    <div key={section.id} id={`section-${section.id}`} className="mt-8">
                                        <div className="flex items-center gap-2 mb-4">
                                            <span className="text-lg">{section.icon}</span>
                                            <div>
                                                <h2 className="section-title">{section.title}</h2>
                                                <p className="text-xs" style={{ color: 'var(--color-text-secondary)' }}>
                                                    {section.description}
                                                </p>
                                            </div>
                                        </div>
                                        <ChartGrid
                                            kpis={sectionKpis}
                                            projectId={projectId}
                                            selectedKpis={selectedKpis}
                                            onToggleSelection={toggleKpiSelection}
                                            externalFilters={externalFilters}
                                            onDrillDown={handleDrillDown}
                                        />
                                    </div>
                                );
                            })}

                            {/* ── Active Streams Table ────────────────── */}
                            <div className="pb-12 mt-8">
                                <h3 className="section-title mb-4">Active Streams</h3>
                                <table className="streams-table">
                                    <thead>
                                        <tr>
                                            <th>Data Source</th>
                                            <th>Status</th>
                                            <th>Frequency</th>
                                            <th>Last Sync</th>
                                            <th>Reliability</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        <tr>
                                            <td>
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 rounded-lg bg-orange-100 flex items-center justify-center text-orange-600">
                                                        <span className="material-symbols-outlined text-sm">api</span>
                                                    </div>
                                                    <span className="font-semibold">PostgreSQL Warehouse</span>
                                                </div>
                                            </td>
                                            <td>
                                                <span className="stream-status-badge">
                                                    <span className="stream-status-dot" /> Live
                                                </span>
                                            </td>
                                            <td className="text-slate-500">Real-time</td>
                                            <td className="text-slate-500">Just now</td>
                                            <td>
                                                <div className="stream-reliability-bar">
                                                    <div className="stream-reliability-fill" style={{ width: '98%' }} />
                                                </div>
                                            </td>
                                        </tr>
                                        <tr>
                                            <td>
                                                <div className="flex items-center gap-3">
                                                    <div className="w-8 h-8 rounded-lg bg-blue-100 flex items-center justify-center text-blue-600">
                                                        <span className="material-symbols-outlined text-sm">cloud</span>
                                                    </div>
                                                    <span className="font-semibold">Ollama AI Engine</span>
                                                </div>
                                            </td>
                                            <td>
                                                <span className="stream-status-badge">
                                                    <span className="stream-status-dot" /> Healthy
                                                </span>
                                            </td>
                                            <td className="text-slate-500">On demand</td>
                                            <td className="text-slate-500">2 mins ago</td>
                                            <td>
                                                <div className="stream-reliability-bar">
                                                    <div className="stream-reliability-fill" style={{ width: '92%' }} />
                                                </div>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </>
                    )}
                </div>
            </main>

            {/* ── Bottom Floating Filter Bar for Selected Cards ──────────── */}
            {selectedKpis.size > 0 && (
                <div className="bottom-filter-bar-wrapper">
                    <div className="bottom-filter-bar">
                        <div className="bottom-filter-bar-header">
                            <div className="flex items-center gap-3">
                                <span className="bottom-filter-selection-count">
                                    {selectedKpis.size} chart{selectedKpis.size > 1 ? 's' : ''} selected
                                </span>
                                <button className="bottom-filter-clear-btn" onClick={clearSelection}>Clear</button>
                                <button className="bottom-filter-clear-btn" onClick={selectAll}>Select All</button>
                            </div>
                        </div>

                        <div className="bottom-filter-bar-controls">
                            <div className="flex items-center gap-2 border-r border-slate-200/50 pr-4">
                                <span className="text-xs font-semibold text-slate-500 uppercase tracking-widest">Range</span>
                                <div className="flex gap-1">
                                    {(['7d', '30d', '90d', '1y', 'all'] as DateRange[]).map(d => {
                                        // Compute available ranges for the entire selection.
                                        // If any chart has data for this range, we allow it.
                                        const selectedData = Array.from(selectedKpis).map(id => kpis.find(k => k.kpiId === id)).filter(Boolean) as KPICardData[];
                                        const availableRanges = getAvailableRanges(selectedData);
                                        const isAvailable = availableRanges.includes(d);

                                        return (
                                            <button
                                                key={d}
                                                className={`bottom-filter-preset-btn ${bottomDateRange === d ? 'active' : ''} ${!isAvailable ? 'opacity-40 cursor-not-allowed' : ''}`}
                                                onClick={() => isAvailable && setBottomDateRange(d)}
                                                disabled={!isAvailable}
                                            >
                                                {d === '7d' ? '7D' : d === '30d' ? '30D' : d === '90d' ? '90D' : d === '1y' ? '1Y' : 'All'}
                                            </button>
                                        );
                                    })}
                                </div>
                            </div>

                            <div className="flex items-center gap-2 pl-2">
                                <span className="text-xs font-semibold text-slate-500 uppercase tracking-widest">Group</span>
                                <div className="flex gap-1">
                                    {(['daily', 'weekly', 'monthly', 'quarterly'] as Granularity[]).map(g => (
                                        <button
                                            key={g}
                                            className={`bottom-filter-preset-btn ${bottomGranularity === g ? 'active' : ''}`}
                                            onClick={() => setBottomGranularity(g)}
                                        >
                                            {g === 'daily' ? 'D' : g === 'weekly' ? 'W' : g === 'monthly' ? 'M' : 'Q'}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <button className="bottom-filter-apply-btn" onClick={applyFilterToSelected}>
                                Apply Filter
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Ask AI FAB */}
            <div className="fixed bottom-8 right-8 flex flex-col gap-3 items-end z-40">
                <button
                    className={`ask-ai-fab${forecastPanelOpen ? ' open' : ''}`}
                    onClick={() => setForecastPanelOpen(true)}
                    aria-label="Forecasting"
                    title="Forecasting Engine"
                    style={{ background: 'linear-gradient(135deg, #10b981 0%, #047857 100%)', position: 'static' }}
                >
                    <span className="material-symbols-outlined text-base">monitoring</span>
                    Forecast
                </button>

                <button
                    className={`ask-ai-fab${goalPanelOpen ? ' open' : ''}`}
                    onClick={() => setGoalPanelOpen(true)}
                    aria-label="Target Goals"
                    title="Goal Strategy Engine"
                    style={{ background: 'linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%)', position: 'static' }}
                >
                    <span className="material-symbols-outlined text-base">target</span>
                    Strategy
                </button>

                <button
                    className={`ask-ai-fab${askAiOpen ? ' open' : ''}`}
                    onClick={() => setAskAiOpen(true)}
                    aria-label="Ask AI"
                    title="Ask AI"
                    style={{ position: 'static' }}
                >
                    <span className="material-symbols-outlined text-base">auto_awesome</span>
                    Ask AI
                </button>
            </div>

            {/* Forecast Panel */}
            <DashboardErrorBoundary label="Forecast Panel">
                <ForecastPanel
                    projectId={projectId}
                    isOpen={forecastPanelOpen}
                    onClose={() => setForecastPanelOpen(false)}
                    activeKPIs={kpis.map(k => ({ name: k.kpiName, category: k.category || 'Metric' }))}
                />
            </DashboardErrorBoundary>

            {/* Goal Strategy Panel — single instance, wired to state injection */}
            <DashboardErrorBoundary label="Goal Strategy Engine">
                <GoalStrategyPanel
                    projectId={projectId}
                    isOpen={goalPanelOpen}
                    onClose={() => setGoalPanelOpen(false)}
                    initialQuery={goalQuery}
                    onSimulationComplete={(ctx) => setActiveStrategyContext(ctx)}
                    domainName={domainName}
                    activeKPIs={kpis.map(k => ({ name: k.kpiName, category: k.category || 'Metric' }))}
                    askAiMessages={askAiMessages}
                />
            </DashboardErrorBoundary>

            {/* Ask AI Panel — receives live strategy context for state injection */}
            <DashboardErrorBoundary label="Ask AI Panel">
                <AskAIPanel
                    projectId={projectId}
                    isOpen={askAiOpen}
                    onClose={() => setAskAiOpen(false)}
                    onCommandSuccess={onRefresh}
                    strategyContext={activeStrategyContext ?? undefined}
                    onMessagesChange={setAskAiMessages}
                    onOpenGoalEngine={(query) => {
                        setGoalQuery(query);
                        setAskAiOpen(false);
                        setGoalPanelOpen(true);
                    }}
                />
            </DashboardErrorBoundary>

            {/* Insight Panel (right sidebar overlay) */}
            <InsightPanel
                feed={insightFeed}
                alerts={smartAlerts}
                strongestUp={strongestUp}
                strongestDown={strongestDown}
                anomalyCount={anomalyCount}
                trendingUp={trendingUp}
                trendingDown={trendingDown}
                isOpen={insightPanelOpen}
                onClose={() => setInsightPanelOpen(false)}
            />
        </div>
    );
}

'use client';

// Module 5 — Filter Bar Component
// Granularity presets, date range quick-picks, active filter pills

import { useState } from 'react';

export interface DashboardFilters {
    granularity: 'daily' | 'weekly' | 'monthly' | 'quarterly';
    dateRange: '7d' | '30d' | '90d' | '1y' | 'all';
}

interface FilterBarProps {
    filters: DashboardFilters;
    onChange: (filters: DashboardFilters) => void;
    loading?: boolean;
}

const GRANULARITIES: { value: DashboardFilters['granularity']; label: string }[] = [
    { value: 'daily', label: 'Daily' },
    { value: 'weekly', label: 'Weekly' },
    { value: 'monthly', label: 'Monthly' },
    { value: 'quarterly', label: 'Quarterly' },
];

const DATE_PRESETS: { value: DashboardFilters['dateRange']; label: string }[] = [
    { value: '7d', label: '7 Days' },
    { value: '30d', label: '30 Days' },
    { value: '90d', label: '90 Days' },
    { value: '1y', label: '1 Year' },
    { value: 'all', label: 'All Time' },
];

export function FilterBar({ filters, onChange, loading }: FilterBarProps) {
    const setGranularity = (g: DashboardFilters['granularity']) =>
        onChange({ ...filters, granularity: g });

    const setDateRange = (d: DashboardFilters['dateRange']) =>
        onChange({ ...filters, dateRange: d });

    return (
        <div className="filter-bar" role="toolbar" aria-label="Dashboard filters">
            {/* ── Granularity ──────────────────────────────────── */}
            <span className="filter-label">Group by</span>
            <div className="filter-group">
                {GRANULARITIES.map(g => (
                    <button
                        key={g.value}
                        className={`filter-preset-btn ${filters.granularity === g.value ? 'active' : ''}`}
                        onClick={() => setGranularity(g.value)}
                        disabled={loading}
                        aria-pressed={filters.granularity === g.value}
                    >
                        {g.label}
                    </button>
                ))}
            </div>

            <div className="filter-divider" />

            {/* ── Date Range ───────────────────────────────────── */}
            <span className="filter-label">Range</span>
            <div className="filter-group">
                {DATE_PRESETS.map(d => (
                    <button
                        key={d.value}
                        className={`filter-preset-btn ${filters.dateRange === d.value ? 'active' : ''}`}
                        onClick={() => setDateRange(d.value)}
                        disabled={loading}
                        aria-pressed={filters.dateRange === d.value}
                    >
                        {d.label}
                    </button>
                ))}
            </div>

            {/* ── Loading indicator ────────────────────────────── */}
            {loading && (
                <span style={{
                    marginLeft: 'auto', fontSize: '11px', color: '#94A3B8',
                    display: 'flex', alignItems: 'center', gap: '5px',
                }}>
                    <LoadingSpinner />
                    Refreshing…
                </span>
            )}
        </div>
    );
}

function LoadingSpinner() {
    return (
        <svg
            width="12" height="12" viewBox="0 0 24 24"
            fill="none" stroke="currentColor" strokeWidth="2"
            style={{ animation: 'spin 0.8s linear infinite' }}
        >
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
            <path d="M12 2v4M12 18v4M4.93 4.93l2.83 2.83M16.24 16.24l2.83 2.83M2 12h4M18 12h4M4.93 19.07l2.83-2.83M16.24 7.76l2.83-2.83" />
        </svg>
    );
}

'use client';

// Module 7 — Goal Strategy Panel (Full Implementation)
// Premium intelligence panel for the Goal Strategy Engine.
// Features: goal input, 5-stage pipeline progress, strategy canvas with
// decomposition, ranked actions with collapsible scenario tabs, and location breakdown.

import { useState, useRef, useEffect, useCallback } from 'react';
import StrategyCanvas from '@/components/module-8/StrategyCanvas';
import AIChatPanel from '@/components/module-8/AIChatPanel';
import { StrategyCanvasResult } from '@/lib/module-8/types';
import { resolveForecastHistory, type DashboardKpiExecutionItem } from '@/lib/module-8/kpi-history-resolver';
import { Target, X, FileText } from 'lucide-react';
import html2canvas from 'html2canvas';

// ─── Types ────────────────────────────────────────────────────────────────────

interface ParsedGoal {
    targetMetric: string;
    targetValue: string;
    timeframe: string;
    changeDirection: string;
}

interface DecomposedFactor {
    metric: string;
    requiredChange: string;
    description: string;
    weight: number;
}

interface DecomposedGoal {
    primaryMetric: string;
    targetValue: string;
    formula: string;
    factors: DecomposedFactor[];
}

interface BudgetScenario {
    level: 'LEAN' | 'BALANCED' | 'PREMIUM';
    label: string;
    estimatedCost: string;
    executionPlan: string[];
    timeline: string;
    expectedKpiLift: string;
    monitoringMetrics: string[];
}

interface ActionWithScenarios {
    id: string;
    actionName: string;
    description: string;
    confidenceScore: number;
    tier: 'high' | 'medium' | 'low';
    scenarios: BudgetScenario[];
}

interface LocationPlan {
    locationName: string;
    adjustedGoal: string;
    performanceTier: 'HIGH' | 'MEDIUM' | 'LOW';
    tierReason: string;
}

interface StrategyCanvas {
    goal: ParsedGoal;
    decomposed: DecomposedGoal;
    scenarios: ActionWithScenarios[];
    locationSplits: LocationPlan[];
    generatedAt: string;
    pipelineMs: number;
}

interface PastGoal {
    id: string;
    rawQuery: string;
    targetValue: string;
    timeframe: string;
    status: string;
    createdAt: string;
    generatedPlan: StrategyCanvas;
}

export interface GoalStrategyPanelProps {
    projectId: string;
    isOpen: boolean;
    onClose: () => void;
}

// ─── Constants ────────────────────────────────────────────────────────────────

const PIPELINE_STAGES = [
    { key: 'PARSING', label: 'Parsing Goal', icon: 'edit_note' },
    { key: 'MAPPING', label: 'Mapping KPIs', icon: 'hub' },
    { key: 'DECOMPOSING', label: 'Decomposing Factors', icon: 'account_tree' },
    { key: 'GENERATING', label: 'Generating Strategies', icon: 'auto_awesome' },
    { key: 'BUILDING_SCENARIOS', label: 'Building Scenarios', icon: 'layers' },
];

const SCENARIO_ORDER: BudgetScenario['level'][] = ['LEAN', 'BALANCED', 'PREMIUM'];

const EXAMPLE_GOALS = [
    'Increase revenue by 20% this quarter',
    'Reduce churn by 10% next month',
    'Grow MRR by $50k in 90 days',
    'Improve conversion rate by 15%',
];

const TIER_BADGE: Record<string, { cls: string; label: string }> = {
    HIGH: { cls: 'goal-loc-tier--high', label: '↑ High' },
    MEDIUM: { cls: 'goal-loc-tier--medium', label: '→ Avg' },
    LOW: { cls: 'goal-loc-tier--low', label: '↓ Low' },
};

const TIER_COLORS: Record<string, string> = {
