// ─── Action Card ──────────────────────────────────────────────────────────────

function ActionCard({ action, index, onSimulateAction }: { action: ActionWithScenarios; index: number; onSimulateAction: (action: ActionWithScenarios) => void }) {
    const [expanded, setExpanded] = useState(index === 0);
