    domainColor: string;
    sections: Array<{ id: string; title: string; icon: string }>;
    activeSection?: string;
    isOpen: boolean;
    onToggle: () => void;
}

// Map section icons to Material Symbols (fallback to emoji)
const MATERIAL_ICONS: Record<string, string> = {
    '📊': 'grid_view',
    '💰': 'payments',
    '👥': 'group',
    '📈': 'trending_up',
    '🎯': 'target',
    '🔧': 'build',
