    '🏦': 'account_balance',
    '🛒': 'shopping_cart',
    '📦': 'inventory_2',
    '🏥': 'local_hospital',
    '🎓': 'school',
};

function getMaterialIcon(emoji: string): string {
    return MATERIAL_ICONS[emoji] || 'analytics';
}

