"use client";

import React, { useState, useEffect, useRef } from 'react';
import { Send, Bot, User, Sparkles, Target, Zap, AlertCircle } from 'lucide-react';
import { motion } from 'framer-motion';
import { StrategyCanvasResult } from '@/lib/module-8/types';

interface AIChatPanelProps {
  simulationContext: StrategyCanvasResult | null;
  onMessagesChange?: (messages: { role: string, text: string }[]) => void;
}

export default function AIChatPanel({ simulationContext, onMessagesChange }: AIChatPanelProps) {
  const [messages, setMessages] = useState([
    { 
      role: 'ai', 
      text: "I am the Vistara AI Strategist. I have live access to your Strategy Canvas. Whenever you adjust the sliders, I analyze the new Monte Carlo probabilities. How can I help you optimize this goal?" 
    }
  ]);

  // Update parent whenever messages change
  useEffect(() => {
    if (onMessagesChange) {
      onMessagesChange(messages);
    }
  }, [messages, onMessagesChange]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  // Monitor context changes to proactively advise
  useEffect(() => {
    if (!simulationContext) return;
    
    const prob = simulationContext.probabilityOfSuccess;
    
    // Proactive trigger if probability drops
    if (prob < 0.20 && messages.length > 1 && !messages[messages.length-1].text.includes("dropped below")) {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          role: 'ai',
          text: `⚠️ I noticed your probability of success just dropped to ${(prob*100).toFixed(1)}%. The current uplift isn't strong enough. You either need to increase the budget/uplift, or pull the launch date forward.`
        }]);
      }, 1000);
    } 
    // Proactive trigger if probability surges
    else if (prob > 0.85 && messages.length > 1 && !messages[messages.length-1].text.includes("looks highly achievable")) {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          role: 'ai',
          text: `🎯 Great adjustment! At ${(prob*100).toFixed(1)}%, this strategy looks highly achievable. The pessimistic scenario even keeps you close to the target.`
        }]);
      }, 1000);
    }
  }, [simulationContext]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userText = input;
    setMessages(prev => [...prev, { role: 'user', text: userText }]);
    setInput('');
    setIsTyping(true);
    setError(null);

    try {
      const res = await fetch('/api/v1/module-8/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: userText,
          context: simulationContext
        })
      });

      if (!res.ok) {
        throw new Error(await res.text() || 'Failed to communicate with AI');
      }

      const data = await res.json();
      setMessages(prev => [...prev, { role: 'ai', text: data.reply }]);
    } catch (err: any) {
      console.error(err);
      setError("The AI Engine is currently offline or unreachable. Please check your Ollama connection.");
      setMessages(prev => [...prev, { 
        role: 'ai', 
        text: "I'm having trouble connecting to my cognitive backend right now. Ensure the Ollama service is running." 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
      {/* Header */}
      <div className="bg-slate-900 p-4 text-white flex flex-col">
        <div className="flex items-center gap-2 mb-2">
          <Bot className="w-5 h-5 text-indigo-400" />
          <h3 className="font-bold">AI Strategy Governance</h3>
        </div>
        
        {/* Live Context Pill */}
        {simulationContext ? (
          <div className="flex items-center gap-2 text-xs bg-slate-800 py-1 px-2 rounded-md self-start border border-slate-700">
            <Zap className="w-3 h-3 text-amber-400" />
            <span className="text-slate-300">Live Context:</span>
            <span className={`font-bold ${simulationContext.probabilityOfSuccess > 0.6 ? 'text-green-400' : 'text-red-400'}`}>
              {(simulationContext.probabilityOfSuccess * 100).toFixed(1)}% Prob
            </span>
          </div>
        ) : (
          <div className="text-xs text-slate-400 animate-pulse">Connecting to Simulator...</div>
        )}
      </div>

      {/* Error Banner */}
      {error && (
        <div className="bg-red-50 p-2 text-red-600 text-xs font-medium flex items-center gap-2 border-b border-red-100">
          <AlertCircle className="w-4 h-4 shrink-0" />
          {error}
        </div>
      )}

      {/* Chat History */}
      <div className="flex-1 p-4 overflow-y-auto flex flex-col gap-4 bg-slate-50 min-h-[400px]">
        {messages.map((msg, i) => (
          <motion.div 
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            key={i} 
            className={`flex gap-3 max-w-[90%] ${msg.role === 'user' ? 'ml-auto flex-row-reverse' : ''}`}
          >
            <div className={`flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center ${msg.role === 'user' ? 'bg-slate-900 text-white' : 'bg-indigo-100 text-indigo-600'}`}>
              {msg.role === 'user' ? <User className="w-4 h-4" /> : <Sparkles className="w-4 h-4" />}
            </div>
            <div className={`p-3 rounded-2xl text-sm shadow-sm leading-relaxed whitespace-pre-wrap ${msg.role === 'user' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-800 rounded-tl-none'}`}>
              {msg.text}
            </div>
          </motion.div>
        ))}
        {isTyping && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex gap-3 max-w-[90%]">
             <div className="flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center bg-indigo-100 text-indigo-600">
              <Sparkles className="w-4 h-4" />
            </div>
            <div className="p-4 rounded-2xl bg-white border border-slate-200 rounded-tl-none shadow-sm flex gap-1 items-center">
              <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
              <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
              <div className="w-2 h-2 bg-slate-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </motion.div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="p-3 bg-white border-t border-slate-200">
        <form onSubmit={handleSend} className="relative">
          <input 
            type="text" 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask AI about this strategy..." 
            className="w-full pl-4 pr-12 py-3 bg-slate-100 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all text-sm shadow-inner disabled:bg-slate-200 disabled:cursor-not-allowed"
            disabled={isTyping}
          />
          <button 
            type="submit" 
            disabled={!input.trim() || isTyping}
            className="absolute right-2 top-2 p-1.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send className="w-4 h-4" />
          </button>
        </form>
      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from 'react';
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend,
  ResponsiveContainer, AreaChart, Area, ComposedChart, ReferenceLine
} from 'recharts';
import { Activity, AlertTriangle, TrendingUp, CheckCircle, Settings, SlidersHorizontal } from 'lucide-react';
import { ForecastRequest, StrategyCanvasResult } from '@/lib/module-8/types';
import { motion } from 'framer-motion';

interface StrategyCanvasProps {
  onSimulationComplete?: (data: StrategyCanvasResult) => void;
  initialContext?: {
    goalValue: number;
    actionName: string;
    kpiHistory: { date: string, value: number }[];
    uplift: number;
  };
}

export default function StrategyCanvas({ onSimulationComplete, initialContext }: StrategyCanvasProps) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<StrategyCanvasResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [goalValue, setGoalValue] = useState(initialContext?.goalValue ?? 75000);
  const [horizonDays, setHorizonDays] = useState(180);
  const [actionName, setActionName] = useState(initialContext?.actionName ?? "Email Campaign");
  const [uplift, setUplift] = useState(initialContext?.uplift ?? 15); // Percentage
  const [rampDays, setRampDays] = useState(30);
  const [startDay, setStartDay] = useState(14);

  // Reactive history that updates when props change
  const [history, setHistory] = useState<{ date: string, value: number }[]>([]);

  useEffect(() => {
    if (initialContext?.kpiHistory && initialContext.kpiHistory.length > 0) {
      // Filter out non-date entries like 'Total' or empty strings
      const clean = initialContext.kpiHistory.filter(h => h.date && h.date.match(/^\d{4}-\d{2}-\d{2}/));
      setHistory(clean);
    }
  }, [initialContext?.kpiHistory]);

  const runSimulation = useCallback(async () => {
    if (history.length === 0) return;
    setLoading(true);
    setError(null);
    try {
      const payload: ForecastRequest = {
        kpiHistory: history,
        goalValue,
        horizonDays,
        confidenceLevel: 0.95,
        actions: [
          {
            id: '1',
            name: actionName,
            expectedUplift: uplift / 100,
            rampDays,
            startDayOffset: startDay
          }
        ],
        domain: 'RETAIL'
      };

      const res = await fetch('/api/v1/forecast/validate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(errorText || 'Forecast API failed');
      }

      const result: StrategyCanvasResult = await res.json();
      setData(result);
      if (onSimulationComplete) {
        onSimulationComplete(result);
      }
    } catch (err: any) {
      console.error("[StrategyCanvas] Simulation error:", err);
      setError(err.message || 'Failed to run simulation');
    } finally {
      setLoading(false);
    }
  }, [history, goalValue, horizonDays, actionName, uplift, rampDays, startDay, onSimulationComplete]);

  // Auto-run simulation on mount and when sliders change (debounced)
  useEffect(() => {
    const timer = setTimeout(() => {
      runSimulation();
    }, 500); // 500ms debounce

    return () => clearTimeout(timer);
  }, [runSimulation]);

  // Format data for Recharts
  const chartData = React.useMemo(() => {
    if (!data) return [];
    return data.scenarios.baseline.map((base, i) => {
      const opt = data.scenarios.optimistic[i];
      const cons = data.scenarios.conservative[i];
      return {
        day: base.day,
        date: base.date,
        Baseline: base.yhat,
        ConfidenceLower: base.yhatLower,
        ConfidenceUpper: base.yhatUpper,
        Optimistic: opt.yhat,
        Conservative: cons.yhat
      };
    });
  }, [data]);

  return (
    <div className="flex flex-col lg:flex-row h-full">
      
      {/* LEFT PANEL: Sliders & Controls */}
      <div className="w-full lg:w-80 bg-slate-50 border-r border-slate-200 p-6 flex flex-col gap-6 overflow-y-auto">
        <div className="flex items-center gap-2">
          <SlidersHorizontal className="w-5 h-5 text-indigo-600" />
          <h2 className="text-lg font-bold text-slate-800">Strategy Levers</h2>
        </div>

        <div className="space-y-5">
          <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Target KPI</label>
            <div className="flex items-center">
              <span className="text-slate-400 font-medium mr-2">$</span>
              <input 
                type="number" 
                value={goalValue} 
                onChange={(e) => setGoalValue(Number(e.target.value))}
                className="w-full text-lg font-bold text-slate-900 focus:outline-none bg-transparent"
              />
            </div>
          </div>

          <div className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm">
            <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-1">Primary Action</label>
            <input 
              type="text" 
              value={actionName} 
              onChange={(e) => setActionName(e.target.value)}
              className="w-full font-medium text-slate-900 focus:outline-none bg-transparent"
            />
          </div>

          <div className="bg-white p-4 rounded-lg border border-slate-200 shadow-sm space-y-4">
            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-semibold text-slate-700">Expected Uplift</label>
                <span className="text-sm px-2 py-0.5 bg-indigo-100 text-indigo-700 rounded font-bold">+{uplift}%</span>
              </div>
              <input 
                type="range" 
                min="0" max="50" step="1"
                value={uplift} 
                onChange={(e) => setUplift(Number(e.target.value))}
                className="w-full accent-indigo-600"
              />
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-semibold text-slate-700">Ramp-up (Days)</label>
                <span className="text-sm text-slate-600 font-medium">{rampDays}d</span>
              </div>
              <input 
                type="range" 
                min="1" max="90" step="1"
                value={rampDays} 
                onChange={(e) => setRampDays(Number(e.target.value))}
                className="w-full accent-indigo-600"
              />
            </div>

            <div>
              <div className="flex justify-between items-center mb-2">
                <label className="text-sm font-semibold text-slate-700">Launch Delay</label>
                <span className="text-sm text-slate-600 font-medium">Day {startDay}</span>
              </div>
              <input 
                type="range" 
                min="0" max="90" step="1"
                value={startDay} 
                onChange={(e) => setStartDay(Number(e.target.value))}
                className="w-full accent-indigo-600"
              />
            </div>
          </div>
          
          {loading && (
            <div className="flex items-center justify-center gap-2 text-sm text-indigo-600 font-medium animate-pulse">
              <Activity className="w-4 h-4" /> Recalculating Matrix...
            </div>
          )}

          {error && (
            <div className="p-3 bg-red-50 text-red-700 rounded border border-red-200 text-sm">
              {error}
            </div>
          )}
        </div>
      </div>

      {/* RIGHT PANEL: Canvas & Results */}
      <div className="flex-1 p-6 flex flex-col gap-6 bg-white overflow-hidden">
        
        {/* Top Metric Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 shrink-0">
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-white shadow-sm flex items-center justify-center shrink-0">
              <TrendingUp className={`w-6 h-6 ${(data?.probabilityOfSuccess ?? 0) > 0.6 ? 'text-green-500' : 'text-amber-500'}`} />
            </div>
            <div>
              <p className="text-xs font-bold text-slate-500 uppercase">Probability of Success</p>
              <div className="text-2xl font-black text-slate-900">
                {data ? (data.probabilityOfSuccess * 100).toFixed(1) : '--'}%
              </div>
            </div>
          </div>

          <div className="bg-slate-50 p-4 rounded-xl border border-slate-100 flex items-center gap-4">
            <div className="w-12 h-12 rounded-full bg-white shadow-sm flex items-center justify-center shrink-0">
              <CheckCircle className="w-6 h-6 text-blue-500" />
            </div>
            <div>
