// Ollama-Augmented Domain Reasoning Engine (Module 3C)
// Invokes AI ONLY when rule-based detection is weak/ambiguous
// Never blindly overrides - acts as semantic validator and recommender

import { randomUUID } from 'crypto';
import db from '@/lib/prisma';
import type { DomainType } from '@/lib/prisma';
import {
    checkOllamaHealth,
    generateCompletion,
    performSemanticReasoning as callSemanticReasoning,
    type SemanticReasoningContext,
    type SemanticReasoningResult,
} from '@/lib/ai/ollama-client';

// Confidence thresholds
const AUTO_ASSIGN_THRESHOLD = 60;  // Above this: auto-assign domain
const AI_INVOKE_THRESHOLD = 60;    // Below this: invoke AI for help
const COMBINED_AUTO_THRESHOLD = 70; // Combined confidence needed for auto-assign

// AI Domain Reasoning Record (for audit and explainability)
export interface AIDomainReasoning {
    id: string;
    projectId: string;
    // Rule-based detection results
    ruleBasedDomain: DomainType | null;
    ruleBasedConfidence: number;
    matchedColumns: string[];
    unmatchedColumns: string[];
    // AI semantic analysis
    aiRecommendedDomain: DomainType | null;
    aiSemanticConfidence: number;
    aiAlternativeDomain: DomainType | null;
    aiAlternativeConfidence: number;
    aiReasoning: string;
    aiSemanticSignals: string[];
    aiColumnInsights: string;
    // Combined results
    combinedConfidence: number;
    finalDomain: DomainType | null;
    wasAutoAssigned: boolean;
    // Metadata
    ollamaModel: string;
    processingTimeMs: number;
    createdAt: Date;
}

// Gather context for semantic reasoning
async function gatherSemanticContext(
    projectId: string,
    ruleDetection: any
): Promise<SemanticReasoningContext> {
    const project = await db.project.findUnique({ where: { id: projectId } });
    const sources = await db.source.findMany({ where: { projectId } });

    // Extract sample values from unmatched columns
    const sampleValues: Record<string, string[]> = {};
    const unmatchedColumns = ruleDetection?.unmatchedColumns || [];

    for (const source of sources) {
        const sourceData = source.data as unknown as Record<string, any>[];
        if (sourceData && sourceData.length > 0) {
            for (const col of unmatchedColumns.slice(0, 15)) {
                if (!sampleValues[col]) {
                    const samples = sourceData
                        .slice(0, 5)
                        .map((row: Record<string, any>) => String(row[col] || ''))
                        .filter((v: string) => v && v !== 'null' && v !== 'undefined' && v.length < 50);
                    if (samples.length > 0) {
                        sampleValues[col] = samples;
                    }
                }
            }
        }
    }

    // Build matched columns info
    const matchedColumns = (ruleDetection?.matchedColumns || []).map((col: string) => ({
        column: col,
        domain: ruleDetection?.detectedDomain || 'UNKNOWN',
        keyword: col,
    }));

    const totalRows = sources.reduce((sum, s) => sum + (s.rowCount || 0), 0);

    // Get second domain (for comparison)
    const scores = Object.entries(ruleDetection?.scoringBreakdown || {})
        .sort(([, a], [, b]) => (b as number) - (a as number));
    const secondDomain = scores.length > 1 ? scores[1][0] : null;

    return {
        projectName: project?.name || 'Unknown Project',
        matchedColumns,
        unmatchedColumns,
        sampleValues,
        ruleBasedScores: ruleDetection?.scoringBreakdown || {},
        topDomain: ruleDetection?.detectedDomain || null,
        secondDomain,
        ambiguityScore: totalRows > 0 ? 50 : 0,
    };
}

// Calculate combined confidence using weighted fusion
function calculateCombinedConfidence(
    ruleConfidence: number,
    aiConfidence: number,
    domainsMatch: boolean
): number {
    if (domainsMatch) {
        // Domains agree - boost confidence significantly
        // Weighted: 55% rule-based + 45% AI (slight rule preference)
        const base = (ruleConfidence * 0.55) + (aiConfidence * 0.45);
        // Bonus for agreement
        const agreementBonus = Math.min(15, (ruleConfidence + aiConfidence) / 10);
        return Math.min(100, Math.round(base + agreementBonus));
    } else {
        // Domains disagree - use weighted average, no bonus
        // Rule-based gets more weight since it's deterministic
        return Math.round((ruleConfidence * 0.6) + (aiConfidence * 0.4));
    }
}

// Main: Trigger domain reasoning with AI assistance
export async function triggerDomainReasoning(
    projectId: string
): Promise<AIDomainReasoning | null> {
    console.log('[AI-Domain] Starting semantic reasoning for project:', projectId);
    const startTime = Date.now();

    // Get existing rule-based detection
    const ruleDetection = await db.domainDetection.findUnique({ where: { projectId } });

    if (!ruleDetection) {
        console.log('[AI-Domain] No rule-based detection found');
        return null;
    }

    const ruleConfidence = ruleDetection.confidence || 0;
    console.log('[AI-Domain] Rule-based confidence:', ruleConfidence);

    // Check if AI assistance is needed
    if (ruleConfidence >= AI_INVOKE_THRESHOLD) {
        console.log('[AI-Domain] Rule-based confidence is strong, AI not needed');
        return null;
    }

    // Check Ollama availability
    const ollamaAvailable = await checkOllamaHealth();
    if (!ollamaAvailable) {
        console.warn('[AI-Domain] Ollama not available');
        return null;
    }

    try {
        // Gather semantic context
        const context = await gatherSemanticContext(projectId, ruleDetection);

        if (context.unmatchedColumns.length === 0 && context.matchedColumns.length === 0) {
            console.log('[AI-Domain] No columns to analyze');
            return null;
        }

        console.log('[AI-Domain] Analyzing', context.unmatchedColumns.length, 'unmatched columns');

        // Call Ollama semantic reasoning
        const suggestion = await callSemanticReasoning(context);

        const processingTime = Date.now() - startTime;
        console.log('[AI-Domain] Semantic analysis complete in', processingTime, 'ms');
        console.log('[AI-Domain] AI recommends:', suggestion.domain, 'at', Math.round(suggestion.confidence * 100), '%');

        // Calculate combined confidence  
        const aiConfidence = Math.round(suggestion.confidence * 100);
        const domainsMatch = suggestion.domain === ruleDetection.detectedDomain;
        const combinedConfidence = calculateCombinedConfidence(
            ruleConfidence,
            aiConfidence,
            domainsMatch
        );

        // Determine final domain and auto-assignment
        let finalDomain: DomainType | null;
        let wasAutoAssigned: boolean;

        if (combinedConfidence >= COMBINED_AUTO_THRESHOLD) {
            // Combined confidence is high enough - auto-assign
            finalDomain = domainsMatch
                ? ruleDetection.detectedDomain
                : (aiConfidence > ruleConfidence
                    ? suggestion.domain as DomainType
                    : ruleDetection.detectedDomain);
            wasAutoAssigned = true;
            console.log('[AI-Domain] Auto-assigning domain:', finalDomain, 'at', combinedConfidence, '%');
        } else {
            // Still ambiguous - require user selection
            finalDomain = null;
            wasAutoAssigned = false;
            console.log('[AI-Domain] Combined confidence', combinedConfidence, '% still below threshold, needs user input');
        }

        // Create reasoning record
        const reasoning: AIDomainReasoning = {
            id: randomUUID(),
            projectId,
            // Rule-based
            ruleBasedDomain: ruleDetection.detectedDomain,
            ruleBasedConfidence: ruleConfidence,
            matchedColumns: ruleDetection.matchedColumns || [],
            unmatchedColumns: context.unmatchedColumns,
            // AI
            aiRecommendedDomain: suggestion.domain as DomainType | null,
            aiSemanticConfidence: aiConfidence,
            aiAlternativeDomain: null,
            aiAlternativeConfidence: 0,
            aiReasoning: suggestion.reasoning,
            aiSemanticSignals: suggestion.keySignals,
            aiColumnInsights: '',
            // Combined
            combinedConfidence,
            finalDomain,
            wasAutoAssigned,
            // Meta
            ollamaModel: process.env.OLLAMA_MODEL || 'qwen3:0.6b',
            processingTimeMs: processingTime,
            createdAt: new Date(),
        };

        // Store in database
        await db.aIDomainReasoning.upsert({
            where: { projectId },
            create: reasoning,
            update: reasoning,
        });

        return reasoning;
    } catch (error) {
        console.error('[AI-Domain] Semantic reasoning error:', error);
        return null;
    }
}

// Get existing AI reasoning for a project
export async function getAIDomainReasoning(projectId: string): Promise<AIDomainReasoning | null> {
    return await db.aIDomainReasoning.findUnique({ where: { projectId } });
}

// Check if AI reasoning should be invoked for a detection
export function shouldInvokeAI(ruleConfidence: number): boolean {
    return ruleConfidence < AI_INVOKE_THRESHOLD;
}

// Get enhanced classification combining rule-based and AI
export async function getEnhancedClassification(projectId: string): Promise<{
    domain: DomainType | null;
    confidence: number;
    source: 'rule-based' | 'ai-enhanced' | 'ai-recommended' | 'needs-selection';
    aiReasoning: AIDomainReasoning | null;
    ruleDetection: any;
}> {
    const ruleDetection = await db.domainDetection.findUnique({ where: { projectId } });
    const aiReasoning = await getAIDomainReasoning(projectId);

    // No detection at all
    if (!ruleDetection) {
        return {
            domain: null,
            confidence: 0,
            source: 'needs-selection',
            aiReasoning: null,
            ruleDetection: null,
        };
    }

    // Rule-based is strong enough
    if (ruleDetection.confidence >= AUTO_ASSIGN_THRESHOLD) {
        return {
            domain: ruleDetection.detectedDomain,
            confidence: ruleDetection.confidence,
            source: 'rule-based',
            aiReasoning,
            ruleDetection,
        };
    }

    // AI helped and auto-assigned
    if (aiReasoning?.wasAutoAssigned && aiReasoning.finalDomain) {
        return {
            domain: aiReasoning.finalDomain,
            confidence: aiReasoning.combinedConfidence,
            source: aiReasoning.aiRecommendedDomain === aiReasoning.finalDomain
                ? 'ai-recommended'
                : 'ai-enhanced',
            aiReasoning,
            ruleDetection,
        };
    }

    // Still needs user selection
    return {
        domain: ruleDetection.detectedDomain,
        confidence: aiReasoning?.combinedConfidence || ruleDetection.confidence,
        source: 'needs-selection',
        aiReasoning,
        ruleDetection,
    };
}

import { generateWithFallback, type AgentRole, type AIResponse } from './unified-ai-client';
import { DomainType } from '@/lib/prisma';
import { getDomainModel } from './ollama-client';
import { getDomainKPINames } from '@/lib/kpi/domain-metadata';
import { compressContext, buildCompressedPrompt, buildSemanticSignature } from './context-compressor';

export interface MetaContext {
    query: string;
    domain?: DomainType;
    datasets: Record<string, string[]>; // Map of filename -> columns
    chatHistory?: string;
    metrics?: unknown; // Full KPI result or array — compressor extracts scalars only
}

export interface RoutingDecision {
    agentRole: AgentRole;
    reasoning: string;
    confidence: number;
}

// FIX H2: Rule-based routing pre-filter — deterministic, 0-token, 0-latency.
// ~60% of production queries match here before the LLM is ever called.
// Ambiguous queries (no regex match) fall through to LLM routing.
const ROUTING_RULES: { pattern: RegExp; role: AgentRole }[] = [
    { pattern: /\b(trend|why|declined|increased|compared|root cause|yoy|mom|last quarter|last month|last week)\b/i, role: 'business-analyst' },
    { pattern: /\b(goal|target|plan|improve|action|recommend|next step|achieve|q3|q4|strategy|initiative)\b/i, role: 'strategy-planner' },
    { pattern: /\b(schema|column|etl|pipeline|transform|join|migrate|ingest|format|type mismatch)\b/i, role: 'data-engineer' },
    { pattern: /\b(missing|null|anomaly|outlier|duplicate|inconsistent|invalid|bad data|validate|completeness)\b/i, role: 'quality-auditor' },
    { pattern: /\b(forecast|predict|projection|simulate|monte carlo|probability|confidence interval)\b/i, role: 'statistician' },
    { pattern: /\b(kpi|metric|formula|measure|indicator|define|calculate|design)\b/i, role: 'kpi-designer' },
    { pattern: /\b(report|summarize|write|narrative|explain|describe|overview|executive)\b/i, role: 'narrative-writer' },
    { pattern: /\b(domain|industry|classify|sector|which domain|detect domain)\b/i, role: 'domain-expert' },
];

/**
 * Master Router Agent
 *
 * Scans the overall query, context, and available datasets to determine:
 * 1. Which specialized AI agent persona is best suited for the task.
 * 2. What context needs to be injected into the prompt.
 *
 * ACTION 3: Routing prompt now includes chat history and uses the refined
 * BA (diagnostic) vs SP (prescriptive) distinction for accurate routing.
 *
 * ACTION 5: Uses context-compressor to build token-efficient prompts.
 * FIX H2: Rule-based keyword pre-filter fires first — LLM only called for ambiguous queries.
 */
export class MasterAgent {
    /**
     * Determine the correct specialized agent based on the query and context.
     *
     * FIX H2: Tries ROUTING_RULES first (deterministic, 0-token) before going to LLM.
     * ACTION 3: LLM path injects chat history and explicit BA/SP disambiguation rules.
     */
    static async determineRouting(context: MetaContext): Promise<RoutingDecision> {
        // FIX H2: Rule-based pre-filter — fires before any LLM call.
        // Deterministic, 0 tokens, < 1ms latency.
        for (const rule of ROUTING_RULES) {
            if (rule.pattern.test(context.query)) {
                console.log(`[MasterAgent] Rule-based route: "${rule.role}" matched for query.`);
                return { agentRole: rule.role, reasoning: 'Keyword pre-filter match', confidence: 1.0 };
            }
        }

        // Fall through to LLM routing only for genuinely ambiguous queries.
        // ACTION 5 (Two-Tier): Router only sees Semantic Signatures, NOT full column lists.
        // "orders(12 cols: 8 numeric metrics, 2 date dims, 2 categorical dims)"
        // This limits routing prompt to ~50 tokens per source for the 0.6B local model.
        const routerSignature = buildSemanticSignature(context.datasets);

        const historySection = context.chatHistory
            ? `\nRecent Chat Context (last 3 turns):\n${context.chatHistory.slice(-400)}`
            : '';

        const prompt = `
You are the Master Context Router for VistaraBI.
Your task is to analyze the user query and select the most appropriate AI agent role.

KEY DISAMBIGUATION RULE:
- 'business-analyst'  → Use when the query asks about WHAT HAPPENED (diagnostic). 
  Trigger words: trend, why, declined, increased, compared, root cause, last period, YoY.
- 'strategy-planner'  → Use when the query asks WHAT TO DO NEXT (prescriptive).
  Trigger words: goal, target, plan, improve, action, recommend, next step, achieve, forecast.

Available Roles:
- 'business-analyst': Diagnose historical KPI trends and root causes.
- 'data-engineer': Data quality, schema matching, ETL tasks.
- 'domain-expert': Classify raw data into a business domain.
- 'statistician': Forecasting, probability, advanced analytics.
- 'narrative-writer': Summarize reports or write executive prose.
- 'strategy-planner': Goal setting, action plans, impact simulations.
- 'quality-auditor': Find errors or anomalies in data.
- 'kpi-designer': Create formulas and select metrics.
- 'general': Generic chitchat or unrelated tasks.

Context:
- Query: "${context.query}"
- Domain: ${context.domain || 'Unknown'}
- Data Signature (type summary only): ${routerSignature}${historySection}

Respond ONLY in JSON format (no markdown, no explanation outside JSON):
{
    "agentRole": "selected-role",
    "reasoning": "Why this role is best",
    "confidence": 0.95
}
        `.trim();

        try {
            const response = await generateWithFallback({
                messages: [{ role: 'user', content: prompt }],
                temperature: 0.1,
                agentRole: 'general', // Use general role to make the routing decision
            });

            // Parse JSON response — strip any surrounding markdown if present
            const jsonMatch = response.content.match(/\{[\s\S]*?\}/);
            if (jsonMatch) {
                const parsed = JSON.parse(jsonMatch[0]);
                return {
                    agentRole: parsed.agentRole as AgentRole,
                    reasoning:  parsed.reasoning  || 'Context scan completed.',
                    confidence: parsed.confidence || 0.8,
                };
            }
        } catch (error) {
            console.error('[MasterAgent] Routing failed, defaulting to general:', error);
        }

        return { agentRole: 'general', reasoning: 'Fallback due to routing error', confidence: 0.5 };
    }

    /**
     * Executes the query by first scanning the context, picking an agent,
     * and injecting domain knowledge.
     *
     * ACTION 5: Uses compressContext() + buildCompressedPrompt() to replace
     * the raw JSON.stringify(context.datasets) that previously dumped 200+
     * columns per request. Reduces cloud model input by ~70%.
     */
    static async processRequest(context: MetaContext): Promise<AIResponse> {
        console.log(`[MasterAgent] Scanning context for query: "${context.query}"...`);

        // 1. Scan and Route
        const routing = await this.determineRouting(context);
        console.log(`[MasterAgent] Selected Role: ${routing.agentRole} (Confidence: ${routing.confidence})`);

        // 2. Build compressed prompt (ACTION 5: replaces raw JSON.stringify)
        // buildCompressedPrompt injects:
        // - Domain + standard KPI vocabulary (not raw columns)
        // - Schema digest: "file(N cols: col1, col2, ...+K more)"
        // - Query-relevant columns (keyword match top-5)
        // - Metrics digest: scalar values only (KPI name + value + delta)
        // - Last 500 chars of chat history
        const compressedPrompt = buildCompressedPrompt(context);

        // 3. Resolve Model (Use Domain Model if available, otherwise unified client handles fallback)
        const targetModel = context.domain ? getDomainModel(context.domain) : undefined;

        // 4. Execute with Specialized Agent
        console.log(`[MasterAgent] Executing with specialized agent role: ${routing.agentRole}`);
        const response = await generateWithFallback({
            messages:    [{ role: 'user', content: compressedPrompt }],
            temperature: 0.3,
            agentRole:   routing.agentRole,
            model:       targetModel,
        });

        return response;
    }
}

// Ollama Client for AI Semantic Reasoning
// Uses locally hosted Ollama with qwen3:0.6b model
// Domain-specific models are registered via scripts/register-modelfiles.ps1

import type { DomainType } from '@/lib/prisma';
import { getDomainKPINames } from '@/lib/kpi/domain-metadata';
import { generateWithFallback, type AIMessage } from './unified-ai-client';

const OLLAMA_BASE_URL = process.env.OLLAMA_URL || 'http://localhost:11434';
const DEFAULT_MODEL = process.env.OLLAMA_MODEL || 'qwen3.5:0.8b';

// ─── Domain-to-Model Router ───────────────────────────────────────────────────

/**
 * Returns the registered Ollama model name for a given domain.
 * Falls back to DEFAULT_MODEL if the domain-specific model is not available.
 */
export function getDomainModel(domain: DomainType | string | null | undefined): string {
    const map: Record<string, string> = {
        ECOMMERCE:     'vistara-analytics-ecommerce',
        SAAS:          'vistara-analytics-saas',
        EDTECH:        'vistara-analytics-edtech',
        RETAIL:        'vistara-analytics-retail',
        SERVICES:      'vistara-analytics-services',
        MANUFACTURING: 'vistara-analytics-manufacturing',
        HEALTHCARE:    'vistara-analytics-healthcare',
        FINANCE:       'vistara-analytics-finance',
    };
    // If DISABLE_DOMAIN_MODELS env var is set, always use default (useful in CI)
    if (process.env.DISABLE_DOMAIN_MODELS === 'true') return DEFAULT_MODEL;
    return (domain && map[domain as string]) ? map[domain as string] : DEFAULT_MODEL;
}

export interface OllamaMessage {
    role: 'system' | 'user' | 'assistant';
    content: string;
}

// Check if Ollama is available and model is loaded
export async function checkOllamaHealth(): Promise<boolean> {
    try {
        console.log('[Ollama] Checking health at:', OLLAMA_BASE_URL);
        const response = await fetch(`${OLLAMA_BASE_URL}/api/tags`, {
            method: 'GET',
            signal: AbortSignal.timeout(10000),
        });

        if (!response.ok) {
            console.error('[Ollama] Health check failed:', response.status);
            return false;
        }

        const data = await response.json();
        const models = data.models?.map((m: any) => m.name) || [];
        console.log('[Ollama] Available models:', models);

        // Check if our default model is available
        const hasModel = models.some((m: string) => m.includes('qwen'));
        if (!hasModel) {
            console.warn('[Ollama] qwen model not found. Available:', models);
        }

        return true;
    } catch (error) {
        console.error('[Ollama] Service not available:', error);
        return false;
    }
}

// List available models
export async function listModels(): Promise<string[]> {
    try {
        const response = await fetch(`${OLLAMA_BASE_URL}/api/tags`);
        if (!response.ok) return [];

        const data = await response.json();
        return data.models?.map((m: any) => m.name) || [];
    } catch (error) {
        console.error('[Ollama] Failed to list models:', error);
        return [];
    }
}

export interface OllamaGenerateOptions {
    model?: string;
    messages?: OllamaMessage[];
    prompt?: string; // For simple prompts
    temperature?: number;
}

// Generate completion using unified AI client with automatic fallback
export async function generateCompletion(options: OllamaGenerateOptions): Promise<string> {
    const {
        model = DEFAULT_MODEL,
        messages = [],
        prompt,
        temperature = 0.3,
    } = options;

    try {
        // Convert to unified client format
        const aiMessages: AIMessage[] = prompt
            ? [{ role: 'user', content: prompt }]
            : messages.map(m => ({
                role: m.role as 'system' | 'user' | 'assistant',
                content: m.content,
            }));

        const response = await generateWithFallback({
            messages: aiMessages,
            temperature,
            model,
        });

        return response.content;
    } catch (error: any) {
        console.error('[Ollama-Client] All AI providers failed:', error.message);
        throw new Error(`AI generation failed: ${error.message}`);
    }
}

