// Build semantic reasoning prompt for ambiguous domain detection
export interface SemanticReasoningContext {
    projectName: string;
    matchedColumns: { column: string; domain: string; keyword: string }[];
    unmatchedColumns: string[];
    sampleValues: Record<string, string[]>;
    ruleBasedScores: Record<string, number>;
    topDomain: string | null;
    secondDomain: string | null;
    ambiguityScore: number;
}

export interface SemanticReasoningResult {
    domain: string;
    confidence: number;
    reasoning: string;
    keySignals: string[];
}

// Generate KPI suggestions with a domain-aware, enriched prompt
export async function generateKPISuggestions(
    columns: string[],
    sampleRows: Record<string, unknown>[],
    domain: string,
    model?: string
): Promise<{ name: string; formula: string; category: string; explanation: string }[]> {

    // Route to domain-specific model if available; caller's model overrides when explicitly provided
    const kpiModel = model || getDomainModel(domain as DomainType);

    // Inject domain KPI vocabulary so the local model knows what to look for
    const domainKPINames = getDomainKPINames(domain as DomainType).slice(0, 8);
    const domainVocab = domainKPINames.length > 0
        ? `Known ${domain} KPIs include: ${domainKPINames.join(', ')}.`
        : '';

    // Build a clear prompt that works well with small models
    const columnList = columns.slice(0, 15).join(', ');
    const sampleJson = JSON.stringify(sampleRows.slice(0, 5));

    const prompt = `Task: Generate exactly 3-5 KPIs for a business in the ${domain} domain.

${domainVocab}

Input Columns: ${columnList}
Sample Data: ${sampleJson}

Constraints:
1. Use ONLY the column names provided above in the formula.
2. Formulas must use SQL-like aggregations: SUM(col), AVG(col), COUNT(col).
3. Prefer KPIs that match the known ${domain} vocabulary listed above.
4. Response MUST be a valid JSON array of objects.

Output format:
[
  {
    "name": "KPI Name",
    "formula": "SUM(column_name)",
    "category": "category",
    "explanation": "why this matters"
  }
]

JSON Array:`;

    console.log('[KPI-Generator] Generating KPI suggestions with kpi-designer agent');

    try {
        const response = await generateWithFallback({
            messages: [{ role: 'user', content: prompt }],
            temperature: 0.3,
            model: kpiModel,
            agentRole: 'kpi-designer', // Use specialized KPI designer agent
        });

        console.log('[KPI-Generator] Raw response:', response.content.substring(0, 300));

        // Try to extract JSON from response
        const jsonMatch = response.content.match(/\[[\s\S]*?\]/);
        if (jsonMatch) {
            const parsed = JSON.parse(jsonMatch[0]);
            console.log('[KPI-Generator] Parsed', parsed.length, 'KPIs');
            return parsed;
        }

        console.error('[KPI-Generator] No valid JSON found in response');
        return [];

    } catch (error) {
        console.error('[KPI-Generator] Error:', error);
        return [];
    }
}

// Perform semantic domain reasoning (for Module 3C) with domain expert agent
export async function performSemanticReasoning(
    context: SemanticReasoningContext
): Promise<SemanticReasoningResult> {
    const prompt = buildSemanticPrompt(context);

    // Build a domain-aware system message when we have a strong candidate
    const topDomainHint = context.topDomain
        ? ` The rule-based engine's top candidate is "${context.topDomain}" — validate or override this based on the column signals.`
        : '';

    try {
        const response = await generateWithFallback({
            model: getDomainModel(context.topDomain as DomainType),
            messages: [
                {
                    role: 'system',
                    content: `You are a business domain classification expert for VistaraBI. Analyze data columns and determine the most likely business domain from: ECOMMERCE, SAAS, EDTECH, RETAIL, SERVICES, MANUFACTURING, HEALTHCARE, FINANCE.${topDomainHint} Be concise and return only valid JSON.`
                },
                {
                    role: 'user',
                    content: prompt
                }
            ],
            temperature: 0.2,
            agentRole: 'domain-expert', // Use domain expert for classification
        });

        return parseSemanticResponse(response.content, context);
    } catch (error) {
        console.error('[Domain-Reasoning] Semantic reasoning failed:', error);
        return {
            domain: context.topDomain || 'UNKNOWN',
            confidence: 0.3,
            reasoning: 'AI reasoning failed, using rule-based detection.',
            keySignals: [],
        };
    }
}

function buildSemanticPrompt(context: SemanticReasoningContext): string {
    const matchedInfo = context.matchedColumns
        .slice(0, 10)
        .map(m => `${m.column} → ${m.domain} (${m.keyword})`)
        .join('\n');

    const scoresInfo = Object.entries(context.ruleBasedScores)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 5)
        .map(([domain, score]) => `${domain}: ${score}%`)
        .join(', ');

    return `Analyze this data to determine the business domain.

Columns matched to domains:
${matchedInfo}

Current scores: ${scoresInfo}
Top candidates: ${context.topDomain} vs ${context.secondDomain}

What is the most likely business domain? Respond with JSON:
{"domain": "DOMAIN_NAME", "confidence": 0.85, "reasoning": "brief explanation", "keySignals": ["signal1", "signal2"]}`;
}

function parseSemanticResponse(
    response: string,
    context: SemanticReasoningContext
): SemanticReasoningResult {
    try {
        const jsonMatch = response.match(/\{[\s\S]*?\}/);
        if (jsonMatch) {
            const parsed = JSON.parse(jsonMatch[0]);
            return {
                domain: parsed.domain || context.topDomain || 'UNKNOWN',
                confidence: parsed.confidence || 0.7,
                reasoning: parsed.reasoning || 'AI-assisted classification',
                keySignals: parsed.keySignals || [],
            };
        }
    } catch (e) {
        console.error('[Ollama] Failed to parse semantic response:', e);
    }

    return {
        domain: context.topDomain || 'UNKNOWN',
        confidence: 0.5,
        reasoning: response.substring(0, 200),
        keySignals: [],
    };
}

// Module 5.5 — Drill-Down Orchestrator
// Clones an existing dashboard card, injects a category filter (column=value),
// and persists the new child card to DashboardState.
// Reuses executeKPI() from Module 5B — no new SQL logic.

import { randomUUID } from 'crypto';
import db from '@/lib/prisma';
import { upsertCard } from './state-engine';
import type { DashboardCardState, NormalizedCategoryFilter, DrillDownRequest } from './types';
import type { ChartType } from '@/lib/dashboard/types';

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Generate a new drill-down card from a source card.
 * Steps:
 *   1. Load source card from DashboardState
 *   2. Clone card config
 *   3. Inject { column, value } as category filter override
 *   4. Set isDrillDown=true, parentCardId=sourceCardId
 *   5. Persist to DashboardState at next position
 *   6. Return new DashboardCardState (caller triggers executeKPI)
 *
 * Does NOT execute the KPI — returns the card config only.
 */
export async function orchestrateDrillDown(
    projectId: string,
    request: DrillDownRequest
): Promise<DashboardCardState> {
    const { sourceCardId, selectedColumn, selectedValue, chartType } = request;

    // Load source card
    const sourceCard = await db.dashboardCard.findUnique({
        where: { id: sourceCardId },
    });

    if (!sourceCard) {
        throw new Error(`[DrillDown] Source card "${sourceCardId}" not found`);
    }

    // Find the state for this project
    const state = await db.dashboardState.findUnique({
        where: { projectId },
        include: { cards: { select: { position: true } } },
    });

    if (!state) {
        throw new Error(`[DrillDown] No DashboardState found for project "${projectId}"`);
    }

    // Build the injected filter
    const drillFilter: NormalizedCategoryFilter = {
        type: 'category',
        column: selectedColumn,
        values: [selectedValue],
        label: `${selectedColumn}: ${selectedValue}`,
    };

    // Compute next position (after the last card)
    const maxPosition = state.cards.length > 0
        ? Math.max(...state.cards.map(c => c.position))
        : 0;

    const existingOverrides = (sourceCard.filterOverrides as unknown as NormalizedCategoryFilter[]) || [];

    // Determine chart type for drill-down (prefer 'bar' for categorical breakdown)
    const resolvedChartType: ChartType = chartType ||
        (isCategoricalChartType(sourceCard.chartType) ? sourceCard.chartType as ChartType : 'bar');

    // Create child card via state engine
    const childCard = await upsertCard(state.id, {
        kpiId: sourceCard.kpiId,
        kpiName: `${sourceCard.kpiName} (${selectedColumn}: ${selectedValue})`,
        chartType: resolvedChartType,
        layout: {
            position: maxPosition + 1,
            colSpan: 2,        // Drill-downs take full width by default
            rowSpan: 1,
            cardSize: 'lg',
        },
        groupBy: null,
        filterOverrides: [...existingOverrides, drillFilter],
        comparisonMode: sourceCard.comparisonMode as any,
        isPinned: false,
        isAIGenerated: false,
        isDrillDown: true,
        parentCardId: sourceCardId,
    });

    return childCard;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

const CATEGORICAL_CHART_TYPES = new Set(['bar', 'horizontal_bar', 'pie', 'doughnut', 'treemap']);

function isCategoricalChartType(chartType: string): boolean {
    return CATEGORICAL_CHART_TYPES.has(chartType);
}

// Module 5.5 — Orchestrator (Main Entry Point)
// runDashboardIntelligence() is the single function Module 5.5 exposes to the API.
// Pipeline:
//   hydrateDashboard → normalizeFilters → execute KPIs (parallel) → attach summary → attach anomaly → return

// R7: Concurrency cap — at most this many KPI DB queries run simultaneously
// Prevents connection pool exhaustion when processing large dashboards.
const KPI_CONCURRENCY_LIMIT = 5;

import { hydrateDashboard } from './state-engine';
import { normalizeFilters } from './filter-interpreter';
import { mergeFilters, toExecutionFilters, extractDateRange, extractRankConfig } from './filter-propagation';
import { generateDeterministicSummary } from './kpi-summary-engine';
import { tryDetectAnomalies } from './anomaly-detector';
import { executeKPI } from '@/lib/execution';
import db from '@/lib/prisma';
import type {
    DashboardIntelligenceOptions,
    EnrichedKPIResult,
    EnrichedDashboardResult,
    GuardrailInfo,
    NormalizedFilter,
} from './types';

// ─── Constants ────────────────────────────────────────────────────────────────

const MAX_GROUP_BY_ROWS = 200; // Cardinality guardrail threshold

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Run the full dashboard intelligence pipeline for a project.
 *
 * Steps:
 *   1. Hydrate DashboardState (from DB or seed from DashboardConfig)
 *   2. Parse raw business filter expressions → NormalizedFilter[]
 *   3. For each card: merge global+card filters → executeKPI
 *   4. Attach KPISummary (deterministic)
 *   5. Attach AnomalyReport (Z-score based, optional)
 *   6. Attach GuardrailInfo (cardinality check)
 *   7. Return EnrichedDashboardResult
 */
export async function runDashboardIntelligence(
    projectId: string,
    options: DashboardIntelligenceOptions = {}
): Promise<EnrichedDashboardResult> {
    const startTime = Date.now();

    // ── Step 1: Hydrate state ──
    const state = await hydrateDashboard(projectId);
    if (!state) {
        throw new Error(`[Module5.5] No dashboard state or config found for project "${projectId}". Run Module 5A first.`);
    }

    // ── Step 2: Normalize filters ──
    let globalFilters: NormalizedFilter[] = options.normalizedFilters || state.globalFilters;

    if (options.businessFilters && options.businessFilters.length > 0) {
        const parsed = normalizeFilters(options.businessFilters, {
            fiscalYearConvention: options.fiscalYearConvention || 'april_march',
        });
        // Business filter expressions OVERRIDE stored global filters
        globalFilters = parsed;
    }

    // ── Step 3: Execute per-card (parallel with concurrency cap) ──
    const granularity = options.granularity || state.granularity || 'monthly';

    // Filter to requested card IDs if specified
    const cardsToProcess = options.cardIds
        ? state.cards.filter(c => options.cardIds!.includes(c.id))
        : state.cards;

    // R3: Prefetch unit for all KPIs in this dashboard in a single query
    const kpiIds = [...new Set(cardsToProcess.map(c => c.kpiId))];
    const approvedKPIs = await db.approvedKPI.findMany({
        where: { id: { in: kpiIds } },
        select: { id: true, unit: true },
    });
    const unitLookup = new Map(approvedKPIs.map(k => [k.id, (k as any).unit as string | null]));

    // R7: Build execution tasks, then run with concurrency cap via Promise.allSettled
    type CardTask = {
        card: typeof cardsToProcess[number];
        unit: string;
    };

    async function executeCardKPI(card: typeof cardsToProcess[number]): Promise<EnrichedKPIResult> {
        const effectiveFilters = mergeFilters(globalFilters, card.filterOverrides);
        const executionFilters = toExecutionFilters(effectiveFilters);
        const dateRange = extractDateRange(effectiveFilters);
        const rankConfig = extractRankConfig(effectiveFilters);
        const groupBy = card.groupBy || rankConfig.groupBy || undefined;

        const result = await executeKPI(projectId, card.kpiId, {
            granularity: groupBy ? undefined : granularity,
            filters: executionFilters,
            groupBy,
            dateFrom: dateRange.dateFrom,
            dateTo: dateRange.dateTo,
            dateColumn: dateRange.dateColumn,
            skipCache: options.skipCache,
            skipAIExplanation: true,
        });

        const summary = options.skipSummaryGeneration
            ? null
            : generateDeterministicSummary(result);

        let anomaly = null;
        if (!options.skipAnomalyDetection && result.dataset.length >= 5) {
            anomaly = tryDetectAnomalies(result.dataset);
        }

        const guardrail: GuardrailInfo | null = result.datasetSize > MAX_GROUP_BY_ROWS
            ? {
                triggered: true,
                reason: `High cardinality: ${result.datasetSize} rows exceed limit of ${MAX_GROUP_BY_ROWS}`,
                fallbackChartType: 'table',
                originalCount: result.datasetSize,
            }
            : null;

        // R3: resolve unit from prefetched lookup, fallback to empty string
        const unit = unitLookup.get(card.kpiId) || '';

        return { ...result, summary, anomaly, guardrail, unit };
    }

    // R7: Concurrency-capped parallel execution via batched Promise.allSettled
    const enrichedKPIs: EnrichedKPIResult[] = [];
    const errors: EnrichedDashboardResult['errors'] = [];
    let anomalyCount = 0;
    let cacheHitCount = 0;
    let skippedCount = 0;

    // Process in batches of KPI_CONCURRENCY_LIMIT
    for (let i = 0; i < cardsToProcess.length; i += KPI_CONCURRENCY_LIMIT) {
        const batch = cardsToProcess.slice(i, i + KPI_CONCURRENCY_LIMIT);
        const batchResults = await Promise.allSettled(batch.map(card => executeCardKPI(card)));

        for (let j = 0; j < batchResults.length; j++) {
            const outcome = batchResults[j];
            const card = batch[j];

            if (outcome.status === 'fulfilled') {
                const enriched = outcome.value;
                if (enriched.performance.cacheHit) cacheHitCount++;
                if (enriched.anomaly?.detected) anomalyCount++;
                enrichedKPIs.push(enriched);
            } else {
                // R2: Surface failure, never swallow silently
                const err = outcome.reason;
                const message = err instanceof Error ? err.message : String(err);
                const errorCode = err?.code || 'KPI_EXECUTION_FAILURE';
                console.error(`[Module5.5] KPI "${card.kpiId}" failed (${errorCode}):`, message);
                errors.push({ kpiId: card.kpiId, errorCode, message });
                skippedCount++;
            }
        }
    }

    const totalTimeMs = Date.now() - startTime;

    return {
        projectId,
        domain: state.domain,
        stateVersion: state.version,
        granularity,
        globalFilters,
        kpis: enrichedKPIs,
        computedAt: new Date().toISOString(),
        errors,  // R2
        metadata: {
            totalKPIs: cardsToProcess.length,
            computedKPIs: enrichedKPIs.length,
            skippedKPIs: skippedCount,
            anomalyCount,
            cacheHitCount,
            totalTimeMs,
        },
    };
}

/**
 * Dry-run: evaluate which KPIs would execute and what filters normalize to,
 * without actually hitting the database or executing SQL.
 */
export async function previewDashboardIntelligence(
    projectId: string,
    options: DashboardIntelligenceOptions = {}
): Promise<{ state: Awaited<ReturnType<typeof hydrateDashboard>>; normalizedFilters: NormalizedFilter[] }> {
    const state = await hydrateDashboard(projectId);

    let normalizedFilters: NormalizedFilter[] = options.normalizedFilters || state?.globalFilters || [];
    if (options.businessFilters && options.businessFilters.length > 0) {
        normalizedFilters = normalizeFilters(options.businessFilters, {
            fiscalYearConvention: options.fiscalYearConvention || 'april_march',
        });
    }

    return { state, normalizedFilters };
}

// Module 5.5 — Dashboard State Types
// All interfaces for the stateful dashboard intelligence layer.
// This sits ABOVE the existing execution engine — never imports from sql-compiler.

import type { ChartType, CardSize } from '@/lib/dashboard/types';
import type { TimeGranularity, Filter } from '@/lib/visualization/types';
import type { KPIExecutionResult } from '@/lib/execution/types';

// ─── Normalized Filter ────────────────────────────────────────────────────────
// The canonical filter format used throughout Module 5.5.
// Produced by the filter-interpreter; consumed by the execution engine.

export type FilterOperator = 'eq' | 'neq' | 'gt' | 'gte' | 'lt' | 'lte' | 'in';
export type ComparisonMode = 'prev_period' | 'prev_year' | 'custom' | null;
export type FiscalYearConvention = 'april_march' | 'january_december';

export interface NormalizedDateFilter {
    type: 'date_range';
    column: string;         // Resolved column name in source table
    from: string;           // ISO date string 'YYYY-MM-DD'
    to: string;             // ISO date string 'YYYY-MM-DD'
    label: string;          // Human-readable e.g. "FY2025", "Last 30 days"
}

export interface NormalizedCategoryFilter {
    type: 'category';
    column: string;
    values: string[];
    label: string;
}

export interface NormalizedValueFilter {
    type: 'value';
    column: string;
    operator: FilterOperator;
    value: number | string;
    label: string;
}

export interface NormalizedRankFilter {
    type: 'rank';
    column: string;         // Column to rank by (e.g. 'revenue')
    limit: number;          // e.g. 5 for "Top 5"
    orderDir: 'asc' | 'desc';
    label: string;          // e.g. "Top 5 products"
}

export type NormalizedFilter =
    | NormalizedDateFilter
    | NormalizedCategoryFilter
    | NormalizedValueFilter
    | NormalizedRankFilter;

// ─── Business Filter Expression ───────────────────────────────────────────────
// Raw string from user input: "FY2025", "Last 30 days", "Revenue > 50000", etc.

export type BusinessFilterExpression = string;

// ─── Card Layout ──────────────────────────────────────────────────────────────

export interface CardLayout {
    position: number;       // Ordered index in the dashboard
    colSpan: 1 | 2 | 3 | 4;
    rowSpan: 1 | 2;
    cardSize: CardSize;
}

// ─── Dashboard Card State ─────────────────────────────────────────────────────

export interface DashboardCardState {
    id: string;
    stateId: string;
    kpiId: string;
    kpiName: string;
    chartType: ChartType;
    layout: CardLayout;
    groupBy: string | null;
    filterOverrides: NormalizedFilter[];    // Card-level filter overrides (on top of global)
    comparisonMode: ComparisonMode;
    isPinned: boolean;
    isAIGenerated: boolean;
    isDrillDown: boolean;
    parentCardId: string | null;
    createdAt: string;
    updatedAt: string;
}

// ─── Dashboard State Record ───────────────────────────────────────────────────

export interface DashboardStateRecord {
    id: string;
    projectId: string;
    domain: string;
    version: number;
    globalFilters: NormalizedFilter[];
    granularity: TimeGranularity;
    cards: DashboardCardState[];
    createdAt: string;
    updatedAt: string;
}

// ─── KPI Summary ──────────────────────────────────────────────────────────────

export type TrendLabel = 'significant_increase' | 'notable_increase' | 'stable' |
    'notable_decrease' | 'significant_decrease' | 'no_comparison';
export type ThresholdBand = 'high' | 'medium' | 'low' | 'none';

export interface KPISummary {
    headline: string;           // e.g. "Revenue increased 24% vs. last period"
    detail: string;             // e.g. "Current: ₹1.2M | Previous: ₹970K (high variability)"
    trendLabel: TrendLabel;
    thresholdBand: ThresholdBand;
    generatedAt: string;        // ISO timestamp
}

// ─── Anomaly Report ───────────────────────────────────────────────────────────

export type AnomalySeverity = 'low' | 'medium' | 'high';

export interface AnomalyPoint {
    label: string;              // Data point label (date or category)
    value: number;
    zScore: number;
    severity: AnomalySeverity;
}

export interface AnomalyReport {
    detected: boolean;
    severity: AnomalySeverity;  // Worst point severity
    worstPoint: AnomalyPoint;
    affectedPoints: AnomalyPoint[];
    reasoning: string;          // e.g. "Value 58,221 is 3.1σ above the rolling mean of 12,450"
}

// ─── Anomaly Detection Config ─────────────────────────────────────────────────

export interface AnomalyConfig {
    zLowThreshold: number;      // Default: 2.0
    zHighThreshold: number;     // Default: 3.0
    minDataPoints: number;      // Default: 5 — below this, skip detection
    rollingWindowSize: number;  // Default: 5
}

// ─── Guardrail ────────────────────────────────────────────────────────────────

export interface GuardrailInfo {
    triggered: boolean;
    reason: string;
    fallbackChartType: ChartType;
    originalCount: number;
}

// ─── Enriched KPI Result ── adds Module 5.5 intelligence to execution output ──

export interface EnrichedKPIResult extends KPIExecutionResult {
    summary: KPISummary | null;
    anomaly: AnomalyReport | null;
    guardrail: GuardrailInfo | null;
    // R3: unit propagated from KPI definition → EnrichedKPIResult
    unit: string;
}

// ─── Enriched Dashboard Result ────────────────────────────────────────────────

export interface EnrichedDashboardResult {
    projectId: string;
    domain: string;
    stateVersion: number;
    granularity: TimeGranularity;
    globalFilters: NormalizedFilter[];
    kpis: EnrichedKPIResult[];
    computedAt: string;
    // R2: KPI execution errors surfaced explicitly — never swallowed silently
    errors: Array<{
        kpiId: string;
        errorCode: string;
        message: string;
    }>;
    metadata: {
        totalKPIs: number;
        computedKPIs: number;
        skippedKPIs: number;
        anomalyCount: number;
        cacheHitCount: number;
        totalTimeMs: number;
    };
}

// ─── Intelligence Options ─────────────────────────────────────────────────────

export interface DashboardIntelligenceOptions {
    businessFilters?: BusinessFilterExpression[];   // Raw user strings
    normalizedFilters?: NormalizedFilter[];          // Already-parsed filters (bypass interpreter)
    granularity?: TimeGranularity;
    skipCache?: boolean;
    skipAnomalyDetection?: boolean;
    skipSummaryGeneration?: boolean;
    fiscalYearConvention?: FiscalYearConvention;
    cardIds?: string[];     // If provided, only execute these specific cards
}

// ─── Drill-Down Request ───────────────────────────────────────────────────────

export interface DrillDownRequest {
    sourceCardId: string;
    selectedColumn: string;
    selectedValue: string;
    chartType?: ChartType;
}

// ─── Filter Validation Error ──────────────────────────────────────────────────

export class FilterValidationError extends Error {
    constructor(
        public readonly expression: BusinessFilterExpression,
        public readonly detail: string
    ) {
