        this.name = 'FilterValidationError';
    }
}

// Module 5A — Dashboard Configuration Orchestrator (Rebuilt)
// Generates dashboard configs with chart intelligence and AI explanations

import db from '../prisma';
import type { DomainType } from '../prisma';
import type { DashboardConfigSchema, DashboardMetadata } from './types';
import { buildSections } from './section-builder';
import { buildSidebarConfig } from './sidebar-builder';
import { generateKPIExplanations } from './kpi-explainer';
import { DOMAIN_LIBRARIES } from '../domain/domain-keywords';
import { loadBlueprintWithKPIs, flattenKPI } from '../kpi/blueprint-loader';

/**
 * Generate (or regenerate) a complete dashboard configuration.
 * Orchestrates: KPI fetch → section building → AI explanations → persist
 */
export async function generateDashboardConfig(projectId: string): Promise<DashboardConfigSchema> {
    console.log('[Dashboard] Generating config for:', projectId);

    // 1. Fetch upstream data
    const [project, domainDetection] = await Promise.all([
        db.project.findUnique({ where: { id: projectId }, select: { id: true, name: true } }),
        db.domainDetection.findUnique({ where: { projectId } }),
    ]);

    if (!project) {
        throw new Error(`Project not found: ${projectId}`);
    }

    // 2. Load blueprint via relational loader — returns null if none exists
    const blueprint = await loadBlueprintWithKPIs(projectId);
    const rawKpis = blueprint?.kpis || [];

    // Boundary Enforcement: every KPI must have at least one AggregationRule
    const kpis = rawKpis.filter(kpi => kpi.aggregations && kpi.aggregations.length > 0);

    if (kpis.length === 0) {
        if (rawKpis.length > 0) {
            console.error('[Dashboard] BOUNDARY FAILURE: KPIs exist but none have AggregationRules:', rawKpis.map(k => k.id));
            throw new Error('Blueprint KPIs are missing aggregation rules. Please reset your blueprint.');
        }
        throw new Error('No approved KPIs found. Please finalize your KPI Blueprint first.');
    }

    // 3. Resolve domain info
    const domain = domainDetection?.detectedDomain as DomainType | null;
    const domainInfo = domain ? DOMAIN_LIBRARIES[domain] : null;
    const domainColor = domainInfo?.color || '#6366f1';
    const domainName = domainInfo?.name || 'General';
    const domainIcon = domainInfo?.icon || '📊';

    // 4. Build sections (groups KPIs + infers chart types)
    const sections = buildSections(kpis, domain, domainColor);

    // 5. Build sidebar
    const sidebarConfig = await buildSidebarConfig(projectId, project.name);

    // 6. Generate AI explanations (non-blocking)
    console.log('[Dashboard] Initiating asynchronous AI explanations for', kpis.length, 'KPIs...');

    // Create an empty explanations record so UI doesn't crash
    const kpiExplanations: Record<string, any> = {};

    // We purposefully DO NOT await this to prevent Ollama ECONNREFUSED from blocking the config flow. 
    generateKPIExplanations(
        kpis.map(kpi => ({
            kpiId: kpi.id || (kpi as any).kpiId,
            kpiName: kpi.name || (kpi as any).kpiName,
            formula: kpi.lineage?.formula || (kpi as any).formula || '',
            category: kpi.category || 'general',
            columns: kpi.aggregations?.map(a => a.column) || (kpi as any).matchedColumns || [],
        }))
    ).then(explanations => {
        // Asynchronously update the dashboard config when Ollama eventually responds
        if (process.env.NODE_ENV !== 'test') {
            db.dashboardConfig.findUnique({ where: { projectId } }).then(existingConfig => {
                if (existingConfig && existingConfig.metadata) {
                    const metadata = existingConfig.metadata as any;
                    metadata.kpiExplanations = explanations;
                    db.dashboardConfig.update({
                        where: { projectId },
                        data: { metadata }
                    }).catch(err => console.error('[Dashboard] Failed to async-save AI explanations:', err));
                }
            });
        }
    }).catch(err => {
        console.warn(`[Dashboard] AI Explanations failed or unavailable: ${err.message}. Plotting charts without them.`);
    });

    // 7. Version management
    const existing = await db.dashboardConfig.findUnique({
        where: { projectId },
        select: { version: true },
    });
    const version = (existing?.version || 0) + 1;

    // 8. Build metadata
    const metadata: DashboardMetadata = {
        domain,
        domainName,
        domainIcon,
        domainColor,
        totalKPIs: kpis.length,
        totalSections: sections.length,
        generatedAt: new Date().toISOString(),
        version,
        kpiExplanations,
    };

    // 9. Assemble full config
    const config: DashboardConfigSchema = {
        projectId,
        sections,
        sidebarConfig,
        metadata,
        version,
    };

    // 10. Persist to database
    const dbData = {
        projectId,
        sections: sections as any,
        sidebarConfig: sidebarConfig as any,
        metadata: metadata as any,
        version,
    };

    await db.dashboardConfig.upsert({
        where: { projectId },
        create: dbData,
        update: dbData,
    });

    console.log(`[Dashboard] Config generated: ${sections.length} sections, ${kpis.length} KPIs, v${version}`);
    return config;
}

/**
 * Retrieve an existing dashboard configuration.
 */
export async function getDashboardConfig(projectId: string): Promise<DashboardConfigSchema | null> {
    const record = await db.dashboardConfig.findUnique({
        where: { projectId },
    });

    if (!record) return null;

    return {
        projectId: record.projectId,
        sections: record.sections as any,
        sidebarConfig: record.sidebarConfig as any,
        metadata: record.metadata as any,
        version: record.version,
    };
}

// Module 5A — Section Builder (Rebuilt)
// Groups KPIs into business-centric dashboard sections
// Uses the new chart intelligence engine for chart selection

import type { ApprovedKPIWithRelations } from '../prisma';
import type { DashboardSection, DashboardKPICard, ChartSelection } from './types';
import { selectChart, profileData } from './chart-inferrer';
import { KPI_LIBRARY } from '../kpi/kpi-library';
import type { DomainType } from '../prisma';

// ─── Section Definitions ──────────────────────────────────────────

const SECTION_DEFINITIONS = [
    { sectionId: 'revenue', title: 'Revenue & Sales', description: 'Financial performance metrics', icon: '💰', order: 1, categories: ['revenue', 'sales', 'financial', 'pricing'] },
    { sectionId: 'customers', title: 'Customer Intelligence', description: 'Customer behavior and lifecycle metrics', icon: '👥', order: 2, categories: ['customer', 'user', 'retention', 'engagement', 'churn'] },
    { sectionId: 'operations', title: 'Operational Metrics', description: 'Efficiency and process metrics', icon: '⚙️', order: 3, categories: ['operational', 'efficiency', 'logistics', 'inventory', 'process'] },
    { sectionId: 'growth', title: 'Growth & Conversion', description: 'Growth trajectory and conversion metrics', icon: '📈', order: 4, categories: ['growth', 'conversion', 'acquisition', 'marketing'] },
    { sectionId: 'product', title: 'Product Analytics', description: 'Product performance and usage metrics', icon: '📦', order: 5, categories: ['product', 'catalog', 'feature', 'usage'] },
    { sectionId: 'quality', title: 'Quality & Compliance', description: 'Data quality and compliance metrics', icon: '✅', order: 6, categories: ['quality', 'compliance', 'risk', 'audit'] },
];

const FALLBACK_SECTION = {
    sectionId: 'general',
    title: 'General Metrics',
    description: 'Key business metrics',
    icon: '📊',
    order: 99,
};

/**
 * Build dashboard sections from approved KPIs.
 * Groups KPIs by category, sorts by priority, assigns chart types via profiling engine.
 */
export function buildSections(
    kpis: ApprovedKPIWithRelations[],
    domain: DomainType | null,
    domainColor: string
): DashboardSection[] {
    const priorityMap = buildPriorityMap(domain);

    // Group KPIs into sections by category
    const sectionMap = new Map<string, {
        definition: typeof SECTION_DEFINITIONS[0];
        kpis: ApprovedKPIWithRelations[];
    }>();

    for (const kpi of kpis) {
        const category = (kpi.category || '').toLowerCase();
        const sectionDef = findSectionForCategory(category);

        if (!sectionMap.has(sectionDef.sectionId)) {
            sectionMap.set(sectionDef.sectionId, {
                definition: sectionDef,
                kpis: [],
            });
        }
        sectionMap.get(sectionDef.sectionId)!.kpis.push(kpi);
    }

    // Convert to DashboardSection[], sorted by section order
    const sections: DashboardSection[] = [];

    for (const [sectionId, { definition, kpis: sectionKpis }] of sectionMap) {
        const sortedKpis = sectionKpis.sort((a, b) => {
            const idA = a.id || (a as any).kpiId;
            const idB = b.id || (b as any).kpiId;
            const prioA = priorityMap.get(idA) ?? 50;
            const prioB = priorityMap.get(idB) ?? 50;
            if (prioA !== prioB) return prioA - prioB;
            return ((b as any).confidence || 100) - ((a as any).confidence || 100);
        });

        const cards: DashboardKPICard[] = sortedKpis.map((kpi, index) => {
            // Use lightweight chart selection based on formula analysis
            // Full data profiling happens at render time with actual data
            const formulaStr = kpi.lineage?.formula || (kpi as any).formula || '';
            const categoryStr = kpi.category || 'general';
            const chartSelection = inferChartFromFormula(formulaStr, categoryStr);

            return {
                kpiId: kpi.id || (kpi as any).kpiId,
                kpiName: kpi.name || (kpi as any).kpiName,
                formula: formulaStr,
                category: categoryStr,
                chartSelection,
                cardSize: 'md' as const,
                position: index,
                confidence: (kpi as any).confidence || 100,
                colorAccent: domainColor,
            };
        });

        sections.push({
            id: sectionId,
            title: definition.title,
            description: definition.description,
            icon: definition.icon,
            order: definition.order,
            cards,
            collapsed: false,
        });
    }

    sections.sort((a, b) => a.order - b.order);
    return sections;
}

/**
 * Lightweight chart inference from formula text (no data required).
 * Full data-profiling inference happens at render time.
 */
function inferChartFromFormula(formula: string, category: string): ChartSelection {
    const f = formula.toLowerCase();
    const c = category.toLowerCase();

    // Time-based KPIs
    if (f.includes('date') || f.includes('month') || f.includes('daily') || f.includes('trend')) {
        return {
            chartType: 'line', chartLibrary: 'chartjs',
            fallbackType: 'bar', fallbackLibrary: 'chartjs',
            confidence: 0.75, reason: 'Time-related formula → line chart (will refine with data)',
        };
    }

    // Percentage / ratio KPIs
    if (f.includes('/') || f.includes('rate') || f.includes('ratio') || f.includes('percent')) {
        return {
            chartType: 'doughnut', chartLibrary: 'chartjs',
            fallbackType: 'bar', fallbackLibrary: 'chartjs',
            confidence: 0.70, reason: 'Ratio/percentage formula → doughnut chart',
        };
    }

    // Count/sum aggregations
    if (/^(sum|count|total)/i.test(f) || f.includes('count(') || f.includes('sum(')) {
        return {
            chartType: 'bar', chartLibrary: 'chartjs',
            fallbackType: 'metric_card', fallbackLibrary: 'chartjs',
            confidence: 0.70, reason: 'Aggregation formula → bar chart',
        };
    }

    // Default: metric card
    return {
        chartType: 'metric_card', chartLibrary: 'chartjs',
        fallbackType: 'bar', fallbackLibrary: 'chartjs',
        confidence: 0.60, reason: 'Default selection → metric card',
    };
}

function findSectionForCategory(category: string) {
    for (const def of SECTION_DEFINITIONS) {
        if (def.categories.includes(category)) {
            return def;
        }
    }
    return { ...FALLBACK_SECTION, categories: [] as string[] };
}

function buildPriorityMap(domain: DomainType | null): Map<string, number> {
    const map = new Map<string, number>();

    if (domain && KPI_LIBRARY[domain]) {
        for (const def of KPI_LIBRARY[domain]) {
            map.set(def.id, def.priority);
        }
    }

    for (const defs of Object.values(KPI_LIBRARY)) {
        for (const def of defs) {
            if (!map.has(def.id)) {
                map.set(def.id, def.priority + 100);
            }
        }
    }

    return map;
}

// AI Relationship Validator - Module 4D-A
// Uses Ollama to validate ambiguous relationships

import { generateCompletion, checkOllamaHealth } from '@/lib/ai/ollama-client';
import { AIValidationResult, ConfidenceFactors } from '@/lib/prisma';
import { RelationshipCandidate, calculateConfidence } from './relationship-detector';

// Threshold for triggering AI validation
const AMBIGUITY_THRESHOLD = {
    min: 0.4,  // Below this, reject outright
    max: 0.7,  // Above this, accept without AI
};

// Check if a relationship needs AI validation
export function needsAIValidation(confidence: number): boolean {
    return confidence >= AMBIGUITY_THRESHOLD.min && confidence < AMBIGUITY_THRESHOLD.max;
}

// Validate a relationship using Ollama
export async function validateRelationship(
    candidate: RelationshipCandidate,
    sourceSamples: unknown[],
    targetSamples: unknown[]
): Promise<AIValidationResult> {
    console.log('[AIValidator] Validating relationship:',
        `${candidate.sourceTableName}.${candidate.sourceColumn} → ` +
        `${candidate.targetTableName}.${candidate.targetColumn}`
    );

    // Check if Ollama is available
    const isAvailable = await checkOllamaHealth();
    if (!isAvailable) {
        console.log('[AIValidator] Ollama not available, skipping AI validation');
        return {
            validated: true, // Accept as-is if AI unavailable
            reasoning: 'AI validation skipped - Ollama not available',
        };
    }

    const confidence = calculateConfidence(candidate.confidenceFactors);
    const prompt = buildValidationPrompt(candidate, sourceSamples, targetSamples, confidence);

    try {
        const response = await generateCompletion({
            messages: [
                {
                    role: 'system',
                    content: 'You are a data relationship expert. Analyze if two columns likely represent the same business entity and can be joined. Be concise and respond with JSON only.',
                },
                {
                    role: 'user',
                    content: prompt,
                },
            ],
            temperature: 0.2,
        });

        return parseValidationResponse(response, candidate);
    } catch (error) {
        console.error('[AIValidator] Validation failed:', error);
        return {
            validated: true,
            reasoning: 'AI validation failed, accepting based on rule-based confidence',
        };
    }
}

// Build validation prompt
function buildValidationPrompt(
    candidate: RelationshipCandidate,
    sourceSamples: unknown[],
    targetSamples: unknown[],
    confidence: number
): string {
    const sourceTable = candidate.sourceTableName.replace(/\.[^.]+$/, '');
    const targetTable = candidate.targetTableName.replace(/\.[^.]+$/, '');

    const sourceSampleStr = sourceSamples
        .slice(0, 5)
        .filter(v => v !== null && v !== undefined)
        .map(v => String(v))
        .join(', ');

    const targetSampleStr = targetSamples
        .slice(0, 5)
        .filter(v => v !== null && v !== undefined)
        .map(v => String(v))
        .join(', ');

    const factors = candidate.confidenceFactors;

    return `Analyze if these two columns represent the same business entity and can be joined:

Source: ${sourceTable}.${candidate.sourceColumn}
Sample values: [${sourceSampleStr}]

Target: ${targetTable}.${candidate.targetColumn}  
Sample values: [${targetSampleStr}]

Detection scores:
- Name similarity: ${Math.round(factors.nameScore * 100)}%
- Value overlap: ${Math.round(factors.overlapScore * 100)}%
- Target uniqueness: ${Math.round(factors.uniquenessScore * 100)}%
- Data type match: ${Math.round(factors.dataTypeScore * 100)}%
- Combined confidence: ${Math.round(confidence * 100)}%

Are these columns likely the same business entity? Respond with JSON only:
{"validated": true/false, "reasoning": "brief explanation", "adjustedConfidence": 0.0-1.0}`;
}

// Parse AI validation response
function parseValidationResponse(
    response: string,
    candidate: RelationshipCandidate
): AIValidationResult {
    try {
        // Extract JSON from response
        const jsonMatch = response.match(/\{[\s\S]*?\}/);
        if (jsonMatch) {
            const parsed = JSON.parse(jsonMatch[0]);
            return {
                validated: parsed.validated ?? true,
                reasoning: parsed.reasoning || 'AI validation completed',
                adjustedConfidence: parsed.adjustedConfidence,
            };
        }
    } catch (e) {
        console.error('[AIValidator] Failed to parse response:', e);
    }

    // Default: accept with original confidence
    return {
        validated: true,
        reasoning: response.substring(0, 200),
    };
}

// Batch validate multiple ambiguous relationships
export async function batchValidateRelationships(
    candidates: RelationshipCandidate[],
    sourceData: Map<string, Map<string, unknown[]>> // tableId -> column -> values
): Promise<Map<string, AIValidationResult>> {
    const results = new Map<string, AIValidationResult>();

    for (const candidate of candidates) {
        const confidence = calculateConfidence(candidate.confidenceFactors);

        if (!needsAIValidation(confidence)) {
            // Skip AI validation for high/low confidence
            results.set(candidate.sourceColumn + '-' + candidate.targetColumn, {
                validated: confidence >= AMBIGUITY_THRESHOLD.max,
                reasoning: confidence >= AMBIGUITY_THRESHOLD.max
                    ? 'High confidence, no AI validation needed'
                    : 'Low confidence, rejected without AI validation',
            });
            continue;
        }

        // Get sample values
        const sourceValues = sourceData.get(candidate.sourceTableId)?.get(candidate.sourceColumn) || [];
        const targetValues = sourceData.get(candidate.targetTableId)?.get(candidate.targetColumn) || [];

        const result = await validateRelationship(candidate, sourceValues, targetValues);
        results.set(candidate.sourceColumn + '-' + candidate.targetColumn, result);
    }

    return results;
}

export { AMBIGUITY_THRESHOLD };

