"use client";

import { useState, useCallback, useEffect } from "react";
import { api, ApiResponse } from "../api/client";

interface UseApiOptions<T> {
  immediate?: boolean;
  onSuccess?: (data: T) => void;
  onError?: (error: string) => void;
}

export function useApi<T>(
  method: "get" | "post" | "put" | "delete",
  endpoint: string,
  options: UseApiOptions<T> = {}
) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(!!options.immediate);

  const execute = useCallback(
    async (body?: any, customEndpoint?: string) => {
      setLoading(true);
      setError(null);

      const targetEndpoint = customEndpoint || endpoint;
      let response: ApiResponse<T>;

      switch (method) {
        case "get":
          response = await api.get<T>(targetEndpoint);
          break;
        case "post":
          response = await api.post<T>(targetEndpoint, body);
          break;
        case "put":
          response = await api.put<T>(targetEndpoint, body);
          break;
        case "delete":
          response = await api.delete<T>(targetEndpoint);
          break;
      }

      if (response.error) {
        setError(response.error);
        options.onError?.(response.error);
      } else if (response.data) {
        setData(response.data);
        options.onSuccess?.(response.data);
      }

      setLoading(false);
      return response;
    },
    [method, endpoint, options]
  );

  useEffect(() => {
    if (options.immediate) {
      execute();
    }
  }, [options.immediate]);

  return { data, error, loading, execute };
}

// Module 5C — Anomaly Detector (Upgraded)
// Deterministic rule engine — runs BEFORE any AI
// Rules: stddev threshold, spike >35%, drop >25%, missing data, distribution skew

import type { AnomalyResult, AnomalySeverity, AnomalyDirection, AnomalyFlag } from './types';

// ─── Configuration ────────────────────────────────────────────────

const RULES = {
    STDDEV_MULTIPLIER: 2,        // delta > 2 * rolling stddev → anomaly
    SPIKE_THRESHOLD: 0.35,       // >35% spike
    DROP_THRESHOLD: -0.25,       // >25% drop
    SKEW_THRESHOLD: 2.0,         // distribution skew > 2.0
    MIN_RECORDS_FOR_ANOMALY: 3,  // need at least 3 records
};

// ─── Core Detection ───────────────────────────────────────────────

/**
 * Run all deterministic anomaly rules against a KPI result.
 * Returns severity classification + individual flags.
 */
export function detectAnomaly(params: {
    currentValue: number;
    previousValue?: number;
    delta?: number;
    deltaPercent?: number;
    dataPoints: Array<{ label: string; value: number }>;
    volatilityIndex?: number;
    distributionSkew?: number;
    recordCount?: number;
}): AnomalyResult {
    const {
        currentValue, previousValue, delta, deltaPercent,
        dataPoints, volatilityIndex, distributionSkew, recordCount,
    } = params;

    const flags: AnomalyFlag[] = [];
    let maxScore = 0;
    let direction: AnomalyDirection = 'none';

    // Rule 1: Low record count — disable anomaly detection
    if ((recordCount ?? dataPoints.length) < RULES.MIN_RECORDS_FOR_ANOMALY) {
        return {
            severity: 'normal',
            score: 0,
            flags: [],
            reason: 'Insufficient data for anomaly detection',
            direction: 'none',
            detectedAt: new Date().toISOString(),
        };
    }

    // Rule 2: Delta > 2 * rolling standard deviation
    if (dataPoints.length >= 3) {
        const values = dataPoints.map(d => d.value);
        const { mean, stdDev } = computeStats(values);
        const deviationFromMean = Math.abs(currentValue - mean);

        if (stdDev > 0 && deviationFromMean > RULES.STDDEV_MULTIPLIER * stdDev) {
            const sigma = deviationFromMean / stdDev;
            const score = Math.min(100, Math.round(sigma * 25));
            maxScore = Math.max(maxScore, score);
            direction = currentValue > mean ? 'spike' : 'drop';

            flags.push({
                rule: 'stddev_breach',
                description: `Value deviates ${sigma.toFixed(1)}σ from rolling mean`,
                threshold: RULES.STDDEV_MULTIPLIER * stdDev,
                actual: deviationFromMean,
            });
        }
    }

    // Rule 3: Sudden spike > 35%
    if (deltaPercent !== undefined && deltaPercent > RULES.SPIKE_THRESHOLD * 100) {
        const score = Math.min(100, Math.round(deltaPercent * 1.2));
        maxScore = Math.max(maxScore, score);
        direction = 'spike';

        flags.push({
            rule: 'spike_threshold',
            description: `Spike of ${deltaPercent.toFixed(1)}% exceeds ${RULES.SPIKE_THRESHOLD * 100}% threshold`,
            threshold: RULES.SPIKE_THRESHOLD * 100,
            actual: deltaPercent,
        });
    }

    // Rule 4: Drop > 25%
    if (deltaPercent !== undefined && deltaPercent < RULES.DROP_THRESHOLD * 100) {
        const score = Math.min(100, Math.round(Math.abs(deltaPercent) * 1.5));
        maxScore = Math.max(maxScore, score);
        direction = 'drop';

        flags.push({
            rule: 'drop_threshold',
            description: `Drop of ${Math.abs(deltaPercent).toFixed(1)}% exceeds ${Math.abs(RULES.DROP_THRESHOLD) * 100}% threshold`,
            threshold: Math.abs(RULES.DROP_THRESHOLD) * 100,
            actual: Math.abs(deltaPercent),
        });
    }

    // Rule 5: Missing data (empty dataset or zero current value with history)
    if (dataPoints.length === 0 || (currentValue === 0 && previousValue && previousValue !== 0)) {
        maxScore = Math.max(maxScore, 80);
        flags.push({
            rule: 'missing_data',
            description: dataPoints.length === 0
                ? 'No data points available'
                : 'Current value dropped to zero from a non-zero previous value',
            threshold: 1,
            actual: dataPoints.length === 0 ? 0 : currentValue,
        });
    }

    // Rule 6: Abnormal distribution skew
    if (distributionSkew !== undefined && Math.abs(distributionSkew) > RULES.SKEW_THRESHOLD) {
        const score = Math.min(100, Math.round(Math.abs(distributionSkew) * 20));
        maxScore = Math.max(maxScore, score);

        flags.push({
            rule: 'distribution_skew',
            description: `Distribution skew of ${distributionSkew.toFixed(2)} exceeds ±${RULES.SKEW_THRESHOLD} threshold`,
            threshold: RULES.SKEW_THRESHOLD,
            actual: Math.abs(distributionSkew),
        });
    }

    // Classify severity
    const severity = classifySeverity(maxScore, flags);

    // Build reason string
    const reason = flags.length === 0
        ? 'No anomalies detected'
        : flags.map(f => f.description).join('; ');

    return {
        severity,
        score: maxScore,
        flags,
        reason,
        direction,
        detectedAt: new Date().toISOString(),
    };
}

// ─── Severity Classification ──────────────────────────────────────

function classifySeverity(score: number, flags: AnomalyFlag[]): AnomalySeverity {
    if (score >= 70 || flags.some(f => f.rule === 'missing_data')) return 'critical';
    if (score >= 40) return 'warning';
    return 'normal';
}

// ─── Statistical Helpers ──────────────────────────────────────────

export function computeStats(values: number[]): { mean: number; stdDev: number } {
    if (values.length === 0) return { mean: 0, stdDev: 0 };

    const mean = values.reduce((sum, v) => sum + v, 0) / values.length;

    const squaredDiffs = values.map(v => (v - mean) ** 2);
    const variance = squaredDiffs.reduce((sum, v) => sum + v, 0) / values.length;
    const stdDev = Math.sqrt(variance);

    return { mean, stdDev };
}

// Module 5C — Insight Generator (Orchestrator)
// Combines anomaly detection + change attribution + explanation rendering + trend analysis
// Produces structured KPIInsight and InsightFeedItem for the dashboard

import db from '../prisma';
import type { KPIInsight, InsightFeedItem, SmartAlert, InsightsResponse, AnomalySeverity } from './types';
import { detectAnomaly } from './anomaly-detector';
import { computeChangeAttribution } from './change-attribution';
import { renderLineageExplanation, renderTrendSummary } from './explanation-renderer';
import { computeTrend, identifyTopContributors } from './trend-analyzer';

// ─── Single KPI Insight ───────────────────────────────────────────

/**
 * Generate a complete KPIInsight for one KPI.
 * Consumes execution result data from Module 5B.
 */
export function generateKPIInsight(params: {
    kpiId: string;
    kpiName: string;
    category: string;
    currentValue: number;
    previousValue?: number;
    delta?: number;
    deltaPercent?: number;
    trend?: 'up' | 'down' | 'flat';
    dataPoints: Array<{ label: string; value: number }>;
    profiling?: {
        volatilityIndex?: number;
        distributionSkew?: number;
        recordCount?: number;
    };
    lineage?: {
        tables: string[];
        joins: Array<{ from: string; to: string; on?: string }>;
        formula: string;
        aggregations: Array<{ function: string; column: string }>;
        filters?: string[];
    };
    aiExplanation?: string | null;
    previousDataPoints?: Array<{ label: string; value: number }>;
}): KPIInsight {
    const {
        kpiId, kpiName, category, currentValue, previousValue,
        delta, deltaPercent, trend, dataPoints, profiling,
        lineage, aiExplanation, previousDataPoints,
    } = params;

    // Step 1: Anomaly detection (deterministic)
    const anomaly = detectAnomaly({
        currentValue,
        previousValue,
        delta,
        deltaPercent,
        dataPoints,
        volatilityIndex: profiling?.volatilityIndex,
        distributionSkew: profiling?.distributionSkew,
        recordCount: profiling?.recordCount,
    });

    // Step 2: Change attribution (multi-dimensional only)
    const attribution = computeChangeAttribution(dataPoints, previousDataPoints, kpiName);

    // Step 3: Lineage explanation (deterministic)
    const lineageExplanation = renderLineageExplanation(kpiName, lineage ?? null);

    // Step 4: Trend summary
    const trendText = renderTrendSummary({
        kpiName,
        currentValue,
        previousValue,
        deltaPercent,
        trend,
    });

    // Step 5: Trend computation
    const trendData = computeTrend(dataPoints);

    return {
        kpiId,
        kpiName,
        category,
        anomaly,
        attribution,
        lineageExplanation,
        trendSummary: trendText,
        trend: trendData,
        aiSummary: aiExplanation ?? null,
        lastUpdated: new Date().toISOString(),
        dataFreshness: dataPoints.length > 0 ? 'fresh' : 'unknown',
    };
}

// ─── Dashboard Insights ───────────────────────────────────────────

/**
 * Generate insights for all KPIs in a dashboard.
 * Ranks top movers, detects anomalies, builds feed.
 */
export function generateDashboardInsights(
    projectId: string,
    kpiInsights: KPIInsight[],
): InsightsResponse {
    const feed: InsightFeedItem[] = [];
    const alerts: SmartAlert[] = [];
    let anomalyCount = 0;
    let trendingUp = 0;
    let trendingDown = 0;

    // Process each KPI insight
    for (const insight of kpiInsights) {
        // Count anomalies
        if (insight.anomaly.severity !== 'normal') {
            anomalyCount++;

            // Add to feed
            feed.push({
                id: `anomaly-${insight.kpiId}`,
                type: 'anomaly',
                kpiId: insight.kpiId,
                kpiName: insight.kpiName,
                title: `${insight.anomaly.severity === 'critical' ? '🔴' : '🟡'} ${insight.kpiName.replace(/_/g, ' ')}`,
                description: insight.anomaly.reason,
                severity: insight.anomaly.severity,
                timestamp: insight.anomaly.detectedAt,
            });

            // Create smart alert
            alerts.push({
                kpiId: insight.kpiId,
                kpiName: insight.kpiName,
                severity: insight.anomaly.severity,
                triggeredAt: insight.anomaly.detectedAt,
                reason: insight.anomaly.reason,
                delta: insight.trend?.currentPeriodValue
                    ? insight.trend.currentPeriodValue - insight.trend.previousPeriodValue
                    : 0,
                deltaPercent: insight.trend?.percentChange ?? 0,
                acknowledged: false,
            });
        }

        // Count trends
        if (insight.trend) {
            if (insight.trend.direction === 'up') trendingUp++;
            if (insight.trend.direction === 'down') trendingDown++;

            // Add movement to feed
            const absDelta = Math.abs(insight.trend.percentChange);
            if (absDelta > 5) { // Only notable movements
                feed.push({
                    id: `movement-${insight.kpiId}`,
                    type: 'movement',
                    kpiId: insight.kpiId,
                    kpiName: insight.kpiName,
                    title: `${insight.trend.direction === 'up' ? '📈' : '📉'} ${insight.kpiName.replace(/_/g, ' ')}`,
                    description: insight.trendSummary,
                    severity: absDelta > 20 ? 'warning' : 'normal',
                    delta: insight.trend.currentPeriodValue - insight.trend.previousPeriodValue,
                    deltaPercent: insight.trend.percentChange,
                    timestamp: insight.lastUpdated,
                });
            }
        }
    }

    // Sort feed by severity then timestamp
    feed.sort((a, b) => {
        const severityOrder: Record<AnomalySeverity, number> = { critical: 0, warning: 1, normal: 2 };
        const diff = severityOrder[a.severity] - severityOrder[b.severity];
        return diff !== 0 ? diff : new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime();
    });

    // Top movers
    const movements = feed.filter(f => f.type === 'movement' && f.deltaPercent !== undefined);
    const strongestUp = movements.filter(m => (m.deltaPercent ?? 0) > 0)
        .sort((a, b) => (b.deltaPercent ?? 0) - (a.deltaPercent ?? 0))[0] ?? null;
    const strongestDown = movements.filter(m => (m.deltaPercent ?? 0) < 0)
        .sort((a, b) => (a.deltaPercent ?? 0) - (b.deltaPercent ?? 0))[0] ?? null;

    return {
        projectId,
        insights: kpiInsights,
        feed: feed.slice(0, 10), // Top 10 feed items
        alerts,
        topMovers: {
            strongest_up: strongestUp,
            strongest_down: strongestDown,
        },
        anomalyCount,
        trendingUp,
        trendingDown,
        computedAt: new Date().toISOString(),
    };
}

