// Module 4.5 — KPI Eligibility Engine
// Pure deterministic logic. No AI, no fuzzy matching, no fallback.
// Reads from the KPI_RULE_REGISTRY and evaluates semantic column presence
// and relationship graph against each rule's requirements.

import type { DomainType, RelationshipEntry } from '@/lib/prisma';
import type { SemanticColumnMap, EligibilityLogEntry, SemanticRole } from './semantic-types';
import { type KPIRule, getRulesForDomain } from './kpi-rule-registry';

// ─── Eligibility Result ────────────────────────────────────────────────────────

export interface EligibilityResult {
    domain: DomainType;
    unlockedKPIs: KPIRule[];
    skippedKPIs: { rule: KPIRule; reason: string; missingRoles: string[] }[];
    log: EligibilityLogEntry[];
}

// ─── Core Engine ───────────────────────────────────────────────────────────────

/**
 * Determines which KPIs are eligible for a given dataset.
 *
 * Rules:
 * 1. Every requiredSemanticRole must exist in semanticColumns.
 * 2. If requiresJoin=true, the relationship graph must have a valid
 *    RelationshipEntry connecting sources that supply joinedSemanticRoles.
 * 3. No fuzzy matching. No inference. No AI. Binary pass/fail.
 */
export function evaluateEligibility(
    domain: DomainType,
    semanticColumns: SemanticColumnMap,
    relationships: RelationshipEntry[]
): EligibilityResult {
    const prefix = `[Module4.5][${domain}]`;
    console.log(`${prefix} ========================================`);
    console.log(`${prefix} Evaluating KPI eligibility`);
    console.log(`${prefix} Available semantic roles: ${Object.keys(semanticColumns).join(', ')}`);
    console.log(`${prefix} Available relationships: ${relationships.length}`);
    console.log(`${prefix} ========================================`);

    const rules = getRulesForDomain(domain);
    const unlockedKPIs: KPIRule[] = [];
    const skippedKPIs: EligibilityResult['skippedKPIs'] = [];
    const log: EligibilityLogEntry[] = [];

    for (const rule of rules) {
        const result = evaluateRule(rule, semanticColumns, relationships, prefix);

        if (result.eligible) {
            unlockedKPIs.push(rule);
            log.push({ ruleId: rule.id, ruleName: rule.name, status: 'UNLOCKED' });
            console.log(`${prefix} ✅ UNLOCKED: ${rule.name} (${rule.id})`);
        } else {
            skippedKPIs.push({
                rule,
                reason: result.reason,
                missingRoles: result.missingRoles,
            });
            log.push({
                ruleId: rule.id,
                ruleName: rule.name,
                status: 'SKIPPED',
                reason: result.reason,
                missingRoles: result.missingRoles,
            });
            console.log(`${prefix} ❌ SKIPPED: ${rule.name} (${rule.id}) — ${result.reason}`);
        }
    }

    console.log(`${prefix} ========================================`);
    console.log(`${prefix} Unlocked: ${unlockedKPIs.length} / Total: ${rules.length}`);
    console.log(`${prefix} Skipped:  ${skippedKPIs.length}`);
    console.log(`${prefix} ========================================`);

    return { domain, unlockedKPIs, skippedKPIs, log };
}

// ─── Rule Evaluator (private) ──────────────────────────────────────────────────

interface RuleEvalResult {
    eligible: boolean;
    reason: string;
    missingRoles: SemanticRole[];
}

function evaluateRule(
    rule: KPIRule,
    semanticColumns: SemanticColumnMap,
    relationships: RelationshipEntry[],
    prefix: string
): RuleEvalResult {
    // Step 1: Check required semantic roles
    const missingRoles = rule.requiredSemanticRoles.filter(
        role => !(role in semanticColumns) || !semanticColumns[role]
    );

    if (missingRoles.length > 0) {
        return {
            eligible: false,
            reason: `Missing required semantic roles: [${missingRoles.join(', ')}]`,
            missingRoles,
        };
    }

    // Step 2: Check join requirements
    if (rule.requiresJoin) {
        const joinedRoles = rule.joinedSemanticRoles ?? [];

        // All joined roles must also be in semanticColumns
        const missingJoinRoles = joinedRoles.filter(
            role => !(role in semanticColumns) || !semanticColumns[role]
        );
        if (missingJoinRoles.length > 0) {
            return {
                eligible: false,
                reason: `Missing joined semantic roles (required for cross-table KPI): [${missingJoinRoles.join(', ')}]`,
                missingRoles: missingJoinRoles,
            };
        }

        // There must be at least one valid relationship in the graph
        if (relationships.length === 0) {
            return {
                eligible: false,
                reason: 'KPI requires cross-table join but no relationships exist in the relationship graph',
                missingRoles: [],
            };
        }

        // At minimum one relationship must be present — KPI is relationship-gated
        const hasValidRelationship = relationships.some(rel =>
            rel.confidence > 0.5  // only trust relationships above 50% confidence
        );

        if (!hasValidRelationship) {
            return {
                eligible: false,
                reason: 'KPI requires cross-table join but no high-confidence relationship found (confidence > 0.5 required)',
                missingRoles: [],
            };
        }
    }

    // All checks passed
    return { eligible: true, reason: 'All required semantic roles present', missingRoles: [] };
}

// ─── Summary Helper ────────────────────────────────────────────────────────────

export function summarizeEligibility(result: EligibilityResult): void {
    console.log(`\n[Module4.5] === ELIGIBILITY SUMMARY for ${result.domain} ===`);
    console.log(`  Unlocked KPIs (${result.unlockedKPIs.length}):`);
    result.unlockedKPIs.forEach(k => console.log(`    ✅ [${k.id}] ${k.name}`));
    console.log(`  Skipped KPIs (${result.skippedKPIs.length}):`);
    result.skippedKPIs.forEach(s => console.log(`    ❌ [${s.rule.id}] ${s.rule.name} — ${s.reason}`));
    console.log(`[Module4.5] ===============================================\n`);
}

// Module 6C — Correlation Evidence Packet Builder
// Assembles the immutable CorrelationEvidencePacket from all computed components.
// Validates all required fields are present.
// Freezes the resulting packet before returning.

import { randomUUID } from 'crypto';
import type {
    CorrelationEvidencePacket,
    CorrelationConfidenceLevel,
    LagResult,
} from './types';
import { CORRELATION_THRESHOLDS } from './types';

export class CorrelationPacketError extends Error {
    constructor(message: string) {
        super(`[CorrelationPacket] ${message}`);
        this.name = 'CorrelationPacketError';
    }
}

// ─── Confidence Classification ────────────────────────────────────────────────

/**
 * Classify confidence level from n, significance, and r magnitude.
 */
function classifyConfidence(
    n: number,
    significant: boolean,
    pearsonR: number | null
): CorrelationConfidenceLevel {
    if (n < CORRELATION_THRESHOLDS.MIN_OBSERVATIONS) return 'insufficient';
    if (!significant || pearsonR === null) return 'insufficient';

    const absR = Math.abs(pearsonR);

    // HIGH: n >= 20 and strong correlation (|r| >= 0.7)
    if (n >= 20 && absR >= 0.7) return 'high';

    // MODERATE: n >= 10 and moderate correlation (|r| >= 0.5)
    if (n >= 10 && absR >= 0.5) return 'moderate';

    // LOW: significant but weak or small n
    return 'low';
}

// ─── Traceable Fields Builder ─────────────────────────────────────────────────

/**
 * Build list of non-null numeric field names.
 * Only these may be cited by the LLM.
 */
function buildTraceableFields(packet: Omit<CorrelationEvidencePacket, 'traceable_fields' | 'insight_id'>): string[] {
    const fields: string[] = [];
    if (packet.pearson_r !== null) fields.push('pearson_r');
    if (packet.p_value !== null) fields.push('p_value');
    if (packet.n_observations > 0) fields.push('n_observations');
    if (packet.bonferroni_alpha > 0) fields.push('bonferroni_alpha');
    if (packet.null_ratio_a > 0) fields.push('null_ratio_a');
    if (packet.null_ratio_b > 0) fields.push('null_ratio_b');
    return fields;
}

// ─── Build Arguments Contract ─────────────────────────────────────────────────

export interface CorrelationPacketArgs {
    kpiAId: string;
    kpiBId: string;
    kpiAName: string;
    kpiBName: string;
    unitA: string;
    unitB: string;
    grain: string;
    timeWindowStart: string;
    timeWindowEnd: string;
    nObservations: number;
    pearsonR: number | null;
    pValue: number | null;
    statSig: boolean;
    lagApplied: number;
    lagsTested: number[];
    bonferroniAlphaVal: number;
    nullRatioA: number;
    nullRatioB: number;
    firstDifferencingApplied: boolean;
    trendConfounderDetected: boolean;
}

// ─── Main Builder ─────────────────────────────────────────────────────────────

/**
 * Build an immutable CorrelationEvidencePacket from all computed components.
 *
 * correlation_reportable is set to true ONLY when:
 *  - statistically_significant === true
 *  - confidence_level !== 'insufficient'
 *  - pearson_r !== null
 *
 * Returns Object.freeze(packet).
 */
export function buildCorrelationPacket(args: CorrelationPacketArgs): CorrelationEvidencePacket {
    if (!args.kpiAId) throw new CorrelationPacketError('kpiAId is required');
    if (!args.kpiBId) throw new CorrelationPacketError('kpiBId is required');
    if (!args.kpiAName) throw new CorrelationPacketError('kpiAName is required');
    if (!args.kpiBName) throw new CorrelationPacketError('kpiBName is required');

    const confidenceLevel = classifyConfidence(args.nObservations, args.statSig, args.pearsonR);

    const correlationReportable =
        args.statSig &&
        args.pearsonR !== null &&
        confidenceLevel !== 'insufficient';

    const partial: Omit<CorrelationEvidencePacket, 'traceable_fields' | 'insight_id'> = {
        kpi_a_id: args.kpiAId,
        kpi_b_id: args.kpiBId,
        kpi_a_name: args.kpiAName,
        kpi_b_name: args.kpiBName,
        unit_a: args.unitA,
        unit_b: args.unitB,
        grain: args.grain,
        time_window_start: args.timeWindowStart,
        time_window_end: args.timeWindowEnd,
        n_observations: args.nObservations,
        pearson_r: args.pearsonR,
        p_value: args.pValue,
        statistically_significant: args.statSig,
        lag_applied: args.lagApplied,
        lags_tested: [...args.lagsTested],
        bonferroni_alpha: args.bonferroniAlphaVal,
        null_ratio_a: args.nullRatioA,
        null_ratio_b: args.nullRatioB,
        first_differencing_applied: args.firstDifferencingApplied,
        trend_confounder_detected: args.trendConfounderDetected,
        confidence_level: confidenceLevel,
        correlation_reportable: correlationReportable,
    };

    const traceable_fields = buildTraceableFields(partial);

    const packet: CorrelationEvidencePacket = {
        insight_id: randomUUID(),
        ...partial,
        traceable_fields,
    };

    return Object.freeze(packet);
}

// Module 6C — Entry Point
// handleCorrelationQuery() orchestrates the full correlation pipeline.
//
// Pipeline:
//   1. Load Module 5.5 snapshot
//   2. Validate KPI pair (eligibility gate)
//   3. Align time periods (null ratio / effectiveN gates)
//   4. Detect shared trend confounders → apply first-differencing if needed
//   5. Compute correlation metrics (with optional lags + Bonferroni correction)
//   6. Build frozen CorrelationEvidencePacket
//   7. Short-circuit if not reportable
//   8. Call LLM with evidence packet
//   9. Validate numeric claims
//  10. Return structured CorrelationResult
//
// Module 6C does NOT: modify dashboard state, compute new KPIs, import sql-compiler.

import { runDashboardIntelligence } from '@/lib/dashboard-state/module-5-5';
import { validateKPIPair } from './kpi-pair-validator';
import { alignCorrelationSeries } from './period-aligner';
import { detectSharedTrend, applyFirstDifferencing } from './trend-confounder';
import { computeCorrelationMetrics } from './statistics-gate';
import { computeWithLags } from './lag-engine';
import { buildCorrelationPacket, CorrelationPacketError } from './correlation-packet';
import { callCorrelationLLM, LLMCorrelationCallError } from './llm-correlation-client';
import { validateNumericClaims } from '../shared/numeric-guard';
import type { CorrelationResult, CorrelationEvidencePacket } from './types';

// ─── Main Entry Point ─────────────────────────────────────────────────────────

/**
 * Full Module 6C pipeline.
 *
 * @param projectId  The project whose dashboard intelligence snapshot to use
 * @param kpiAId     First KPI ID to correlate
 * @param kpiBId     Second KPI ID to correlate
 * @param grain      Time granularity ('monthly' | 'quarterly') — required for lag
 * @param lags       Lag offsets to test (subset of [-2,-1,0,+1,+2]). Defaults to [0]
 * @param userQuery  Natural language question — forwarded to LLM
 */
export async function handleCorrelationQuery(
    projectId: string,
    kpiAId: string,
    kpiBId: string,
    grain: string = 'monthly',
    lags: number[] = [0],
    userQuery: string = 'What is the correlation between these two KPIs?'
): Promise<CorrelationResult> {

    // ── Step 1: Load Module 5.5 snapshot ──
    let dashboardResult: Awaited<ReturnType<typeof runDashboardIntelligence>>;
    try {
        dashboardResult = await runDashboardIntelligence(projectId, {
            skipCache: false,
            skipAnomalyDetection: false,
            skipSummaryGeneration: false,
        });
    } catch (err: any) {
        return {
            status: 'rejected',
            message: `Could not load dashboard intelligence: ${err.message ?? 'unknown error'}`,
        };
    }

    const results = dashboardResult.kpis ?? [];
    if (results.length === 0) {
        return {
            status: 'insufficient',
            message: 'No KPI results available. Ensure the dashboard has been computed.',
        };
    }

    // ── Step 2: Validate KPI pair ──
    const pairValidation = validateKPIPair(kpiAId, kpiBId, grain, results);
    if (!pairValidation.valid) {
        return {
            status: 'rejected',
            message: pairValidation.reason ?? 'KPI pair validation failed.',
        };
    }

    const { kpiA, kpiB, unitA, unitB } = pairValidation;

    // ── Step 3: Align periods ──
    const alignment = alignCorrelationSeries(kpiA!, kpiB!);
    if (!alignment.valid) {
        return {
            status: 'rejected',
            message: alignment.reason,
        };
    }

    let seriesA = alignment.valuesA;
    let seriesB = alignment.valuesB;

    // ── Step 4: Trend confounder detection ──
    const confounderResult = detectSharedTrend(seriesA, seriesB);
    let firstDifferencingApplied = false;

    if (confounderResult.sharedTrendDetected) {
        const diffed = applyFirstDifferencing(seriesA, seriesB);
        if (diffed.effectiveN < 5) {
            return {
                status: 'insufficient',
                message: 'After applying first-differencing to remove trend confounders, insufficient observations remain.',
            };
        }
        seriesA = diffed.valuesA;
        seriesB = diffed.valuesB;
        firstDifferencingApplied = true;
    }

    // ── Step 5: Compute correlation with lags + Bonferroni ──
    const lagResult = computeWithLags(seriesA, seriesB, lags);

    // Use dominant lag result for the evidence packet
    const dominantLagResult = lagResult.results.find(r => r.lag === lagResult.dominantLag);
    const finalR = lagResult.dominantR;
    const finalPValue = dominantLagResult?.pValue ?? null;
    const finalN = dominantLagResult?.effectiveN ?? alignment.effectiveN;
    const statSig = lagResult.results.some(r => r.significant);

    // ── Step 6: Build evidence packet ──
    let packet: CorrelationEvidencePacket;
    try {
        packet = buildCorrelationPacket({
            kpiAId,
            kpiBId,
            kpiAName: kpiA!.kpiName,
            kpiBName: kpiB!.kpiName,
            unitA: unitA ?? 'unknown',
            unitB: unitB ?? 'unknown',
            grain,
            timeWindowStart: alignment.timeWindowStart,
            timeWindowEnd: alignment.timeWindowEnd,
            nObservations: finalN,
            pearsonR: finalR,
            pValue: finalPValue,
            statSig,
            lagApplied: lagResult.dominantLag,
            lagsTested: lagResult.results.map(r => r.lag),
            bonferroniAlphaVal: lagResult.bonferroniAlpha,
            nullRatioA: alignment.nullRatioA,
            nullRatioB: alignment.nullRatioB,
            firstDifferencingApplied,
            trendConfounderDetected: confounderResult.sharedTrendDetected,
        });
    } catch (err: unknown) {
        const msg = err instanceof CorrelationPacketError ? err.message : 'Evidence packet construction failed';
        return { status: 'rejected', message: msg };
    }

    // ── Step 7: Short-circuit if not reportable ──
    if (!packet.correlation_reportable) {
        return {
            status: 'insufficient',
            message: 'The available data does not support a statistically valid correlation between these KPIs.',
            evidence: packet,
        };
    }

    // ── Step 8: Call LLM ──
    let llmRaw: string;
    try {
        llmRaw = await callCorrelationLLM(userQuery, packet);
    } catch (err: unknown) {
        const msg = err instanceof LLMCorrelationCallError ? err.message : 'LLM call failed';
        return { status: 'rejected', message: msg, evidence: packet };
    }

    // ── Step 9: Validate numeric claims ──
    const guardResult = validateNumericClaims(llmRaw, packet);
    if (guardResult.status === 'suppressed') {
        return {
            status: 'suppressed',
            message: guardResult.message!,
            evidence: packet,
        };
    }

    // ── Step 10: Return success ──
    return {
        status: 'success',
        explanation: guardResult.explanation,
        evidence: packet,
    };
}

// Module 6C — Lag Engine
// Computes correlation at bounded lag offsets [-2, -1, 0, +1, +2].
// Only allowed for monthly or quarterly grain.
// Applies Bonferroni correction when multiple lags are tested.
// Never reports best r without applying the correction.

import { bonferroniAlpha } from '@/lib/execution/statistics-core';
import { computeCorrelationMetrics } from './statistics-gate';
import { ALLOWED_LAGS, CORRELATION_THRESHOLDS } from './types';
import type { LagResult, AllowedLag } from './types';

// ─── Array Shift ──────────────────────────────────────────────────────────────

/**
 * Shift seriesB by `lag` positions relative to seriesA.
 * lag > 0: B is shifted forward (B leads A by lag periods)
 * lag < 0: B is shifted backward (A leads B by |lag| periods)
 * Positions shifted off the end are filled with null.
 *
 * Both output arrays are trimmed to the overlapping window.
 */
function shiftSeries(
    valuesA: (number | null)[],
    valuesB: (number | null)[],
    lag: number
): { shiftedA: (number | null)[]; shiftedB: (number | null)[] } {
    const n = valuesA.length;
    if (lag === 0) return { shiftedA: valuesA, shiftedB: valuesB };

    const absLag = Math.abs(lag);

    if (absLag >= n) {
        // No overlap after shift — return empty arrays
        return { shiftedA: [], shiftedB: [] };
    }

    if (lag > 0) {
        // B leads A: A[0..n-lag-1] aligns with B[lag..n-1]
        return {
            shiftedA: valuesA.slice(0, n - absLag),
            shiftedB: valuesB.slice(absLag),
        };
    } else {
        // A leads B: A[|lag|..n-1] aligns with B[0..n-|lag|-1]
        return {
            shiftedA: valuesA.slice(absLag),
            shiftedB: valuesB.slice(0, n - absLag),
        };
    }
}

// ─── Single Lag Computation ───────────────────────────────────────────────────

function computeAtLag(
    valuesA: (number | null)[],
    valuesB: (number | null)[],
    lag: number,
    correctedAlpha: number
): LagResult {
    const { shiftedA, shiftedB } = shiftSeries(valuesA, valuesB, lag);

    if (shiftedA.length === 0) {
        return { lag, pearsonR: null, tStat: null, pValue: null, effectiveN: 0, significant: false };
    }

    const metrics = computeCorrelationMetrics(shiftedA, shiftedB);

    // Significance is evaluated against the Bonferroni-corrected alpha
    // (not the raw isSignificant() which uses fixed 0.05)
    const significant =
        metrics.pearsonR !== null &&
        metrics.pValue !== null &&
        metrics.pValue < correctedAlpha;

    return {
        lag,
        pearsonR: metrics.pearsonR,
        tStat: metrics.tStat,
        pValue: metrics.pValue,
        effectiveN: metrics.effectiveN,
        significant,
    };
}

// ─── Main Engine ──────────────────────────────────────────────────────────────

export interface LagEngineResult {
    results: LagResult[];
    dominantLag: number;
    dominantR: number | null;
    bonferroniAlpha: number;
    lagsTestedCount: number;
}

/**
 * Compute Pearson correlation at multiple lag offsets with Bonferroni correction.
 *
 * Rules:
 *  - Lags are restricted to ALLOWED_LAGS = [-2, -1, 0, +1, +2]
 *  - Any lags not in ALLOWED_LAGS are silently ignored
 *  - Bonferroni: correctedAlpha = 0.05 / numLags
 *  - Dominant lag = highest |r| that is significant under corrected alpha
 *  - If no lag is significant: dominantLag = 0, dominantR = null
 *
 * @param requestedLags - Subset of ALLOWED_LAGS to test. Pass [0] for no-lag.
 */
export function computeWithLags(
    valuesA: (number | null)[],
    valuesB: (number | null)[],
    requestedLags: number[] = [0]
): LagEngineResult {
    // Validate and filter lags to only allowed values
    const allowedSet = new Set(ALLOWED_LAGS as readonly number[]);
    const lags = [...new Set(requestedLags)].filter(l => allowedSet.has(l)).sort((a, b) => a - b);

    if (lags.length === 0) {
        // Fallback: test lag 0 only
        lags.push(0);
    }

    const numLags = lags.length;
    const correctedAlpha = bonferroniAlpha(CORRELATION_THRESHOLDS.SIGNIFICANCE_ALPHA, numLags);

    // Compute all lags
    const results: LagResult[] = lags.map(lag =>
        computeAtLag(valuesA, valuesB, lag, correctedAlpha)
    );

    // Select dominant lag: highest |r| among significant results
    const significantResults = results.filter(r => r.significant && r.pearsonR !== null);
    const dominant = significantResults.sort(
        (a, b) => Math.abs(b.pearsonR!) - Math.abs(a.pearsonR!)
    )[0];

    return {
        results,
        dominantLag: dominant?.lag ?? 0,
        dominantR: dominant?.pearsonR ?? null,
        bonferroniAlpha: correctedAlpha,
        lagsTestedCount: numLags,
    };
}

// Module 6C — Trend Confounder Detector
// Detects when two series both exhibit a statistically significant trend
// in the same direction, which would produce spurious Pearson correlation.
// If detected, applies first-differencing to both series before correlation.
//
// Method: OLS linear regression slope + t-test for slope significance.
// Pure computation — no DB, no LLM, no external calls.

import { firstDifference, computeMean } from '@/lib/execution/statistics-core';
import { CORRELATION_THRESHOLDS } from './types';

// ─── OLS Slope Computation ────────────────────────────────────────────────────

interface SlopeResult {
    slope: number;
    tStat: number;
    significant: boolean;
    direction: 'up' | 'down' | 'flat';
}

/**
 * Compute OLS linear regression slope for a numeric series.
 * Uses only non-null values. Returns the t-statistic for the slope.
 *
 * t = slope / SE_slope
 * SE_slope = sqrt(MSE / SS_xx)
 * MSE = sum of squared residuals / (n - 2)
 */
function computeOLSSlope(values: (number | null)[]): SlopeResult {
    const nonNull = values
        .map((v, i) => (v !== null ? { x: i, y: v } : null))
        .filter(Boolean) as { x: number; y: number }[];

    const n = nonNull.length;

    if (n < 3) {
        return { slope: 0, tStat: 0, significant: false, direction: 'flat' };
    }

    const meanX = nonNull.reduce((s, p) => s + p.x, 0) / n;
    const meanY = nonNull.reduce((s, p) => s + p.y, 0) / n;

    let ssXX = 0;
    let ssXY = 0;

    for (const { x, y } of nonNull) {
        ssXX += (x - meanX) ** 2;
        ssXY += (x - meanX) * (y - meanY);
    }

    if (ssXX === 0) {
        return { slope: 0, tStat: 0, significant: false, direction: 'flat' };
    }

    const slope = ssXY / ssXX;

    // Compute residuals → MSE → SE_slope
    let sse = 0;
    for (const { x, y } of nonNull) {
        const predicted = meanY + slope * (x - meanX);
        sse += (y - predicted) ** 2;
    }

    const df = n - 2;
    if (df < 1) {
        return { slope, tStat: 0, significant: false, direction: slope > 0 ? 'up' : slope < 0 ? 'down' : 'flat' };
    }

    const mse = sse / df;
    const seSlopeSquared = mse / ssXX;

    // When all residuals are zero (perfect linear trend), t → ∞ → always significant
    if (seSlopeSquared <= 0) {
        const direction = slope > 0 ? 'up' : slope < 0 ? 'down' : 'flat';
        return { slope, tStat: Infinity, significant: slope !== 0, direction };
    }

    const tStat = slope / Math.sqrt(seSlopeSquared);

    // Critical t-value at TREND_SLOPE_ALPHA (two-tailed, approx for df >= 3)
    // Conservative: use df=10 critical value for small samples (t ≈ 1.812 at df=10, alpha=0.10)
    const tCritical = df >= 20 ? 1.645 : df >= 10 ? 1.812 : 2.353; // alpha=0.10

    const significant = Math.abs(tStat) > tCritical;
    const direction = slope > 0 ? 'up' : slope < 0 ? 'down' : 'flat';

    return { slope, tStat, significant, direction };
}

// ─── Shared Trend Detection ───────────────────────────────────────────────────

export interface TrendConfounderResult {
    sharedTrendDetected: boolean;
    trendA: SlopeResult;
    trendB: SlopeResult;
}

/**
 * Detect whether both series exhibit a statistically significant trend
 * in the same direction (both UP or both DOWN).
 *
 * This is the classic spurious correlation confounder: two unrelated metrics
 * both trending upward over time will show high r purely due to shared time trend.
 */
export function detectSharedTrend(
    valuesA: (number | null)[],
    valuesB: (number | null)[]
): TrendConfounderResult {
    const trendA = computeOLSSlope(valuesA);
    const trendB = computeOLSSlope(valuesB);

    const sharedTrendDetected =
        trendA.significant &&
        trendB.significant &&
        trendA.direction === trendB.direction &&
        trendA.direction !== 'flat';

    return { sharedTrendDetected, trendA, trendB };
}

// ─── First Differencing Application ──────────────────────────────────────────

export interface DifferencedSeries {
    valuesA: (number | null)[];
    valuesB: (number | null)[];
    /** Effective n after stripping leading null from both series */
    effectiveN: number;
}

/**
 * Apply first-differencing to both series and strip the leading null.
 * firstDifference() always returns null at index 0 — so we remove index 0
 * from both series to maintain alignment (arrays remain equal-length).
 *
 * The leading null is stripped to prevent it from inflating the null ratio.
 */
export function applyFirstDifferencing(
    valuesA: (number | null)[],
    valuesB: (number | null)[]
): DifferencedSeries {
    const diffA = firstDifference(valuesA);
    const diffB = firstDifference(valuesB);

    // Remove leading null (index 0) from both
    const trimmedA = diffA.slice(1);
    const trimmedB = diffB.slice(1);

    const effectiveN = trimmedA.filter((v, i) => v !== null && trimmedB[i] !== null).length;

    return {
        valuesA: trimmedA,
        valuesB: trimmedB,
        effectiveN,
    };
}

// Module 6A — Execution Bridge
// Maps a validated Module6Command to state-engine / Module 5.5 calls.
// NEVER mutates dashboard cards directly. NEVER imports sql-compiler or pool.
// All errors are wrapped in { success: false, error: {...} }.

import {
    upsertCard,
    removeCard,
    persistDashboardState,
    hydrateDashboard,
} from '@/lib/dashboard-state/state-engine';
import { runDashboardIntelligence } from '@/lib/dashboard-state/module-5-5';
import { MODULE6_ERROR_CODES } from './types';
import type { Module6Command, Module6Action, ExecutionResult, Module6ErrorPayload } from './types';

// ─── Constants ────────────────────────────────────────────────────────────────

/** Maximum number of AI-generated cards per dashboard session. */
const AI_CARD_LIMIT = 8;


// ─── Helper: wrap error ───────────────────────────────────────────────────────

function wrapError(
    code: string,
    message: string,
    recoverable: boolean
): ExecutionResult {
    return {
        success: false,
        action: 'CREATE_CARD' as Module6Action, // placeholder — error response has no meaningful action
        error: { code, message, recoverable },
    };
}

// ─── Action Handlers ──────────────────────────────────────────────────────────

async function handleCreateCard(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    if (!command.kpi_id) {
        return wrapError(MODULE6_ERROR_CODES.SCHEMA_VIOLATION, 'CREATE_CARD requires kpi_id', false);
    }

    const state = await hydrateDashboard(projectId);
    if (!state) {
        return wrapError(MODULE6_ERROR_CODES.SESSION_NOT_FOUND, `No dashboard state for project "${projectId}"`, false);
    }

    // ── AI Card Cap — max 8 AI-generated cards per dashboard ──────────────────
    // User-created cards (isAIGenerated === false) do NOT count toward this limit.
    // AI cannot delete user cards to make room — the user must manually remove an AI card.
    const aiCards = state.cards.filter(c => c.isAIGenerated === true);
    if (aiCards.length >= AI_CARD_LIMIT) {
        return wrapError(
            'AI_CARD_LIMIT_REACHED',
            `AI-generated card limit (${AI_CARD_LIMIT}) reached. Please remove an AI card before creating a new one.`,
            true   // recoverable — user can remove an AI card and retry
        );
    }

    const position = state.cards.length; // append to end
    const chartType = command.chart_type || 'bar';
    const kpiName = command.natural_language_intent?.slice(0, 100) || command.kpi_id;

    const card = await upsertCard(state.id, {
        kpiId: command.kpi_id,
        kpiName,
        chartType,
        layout: { position, colSpan: 1, rowSpan: 1, cardSize: 'md' },
        groupBy: command.group_by || null,
        filterOverrides: [],
        isAIGenerated: true,
        isDrillDown: false,
        parentCardId: null,
    });

    return {
        success: true,
        action: 'CREATE_CARD',
        data: { card_id: card.id, kpi_id: card.kpiId, position },
    };
}


async function handleUpdateCard(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    if (!command.kpi_id) {
        return wrapError(MODULE6_ERROR_CODES.SCHEMA_VIOLATION, 'UPDATE_CARD requires kpi_id', false);
    }

    const state = await hydrateDashboard(projectId);
    if (!state) {
        return wrapError(MODULE6_ERROR_CODES.SESSION_NOT_FOUND, `No dashboard state for project "${projectId}"`, false);
    }

    // Find existing card — by target card_id if given, else by kpi_id
    const existing = command.target
        ? state.cards.find(c => c.id === command.target)
        : state.cards.find(c => c.kpiId === command.kpi_id);

    if (!existing) {
        return wrapError(MODULE6_ERROR_CODES.UNKNOWN_KPI, `Card not found for kpi_id "${command.kpi_id}"`, false);
    }

    const updated = await upsertCard(state.id, {
        kpiId: existing.kpiId,
        kpiName: existing.kpiName,
        chartType: command.chart_type || existing.chartType,
        layout: existing.layout,
        groupBy: command.group_by || existing.groupBy,
        filterOverrides: existing.filterOverrides,
        isAIGenerated: true,
    });

    return {
        success: true,
        action: 'UPDATE_CARD',
        data: { card_id: updated.id, chart_type: updated.chartType, group_by: updated.groupBy },
    };
}

async function handleDeleteCard(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    if (!command.kpi_id && !command.target) {
        return wrapError(MODULE6_ERROR_CODES.SCHEMA_VIOLATION, 'DELETE_CARD requires kpi_id or target', false);
    }

    const state = await hydrateDashboard(projectId);
    if (!state) {
        return wrapError(MODULE6_ERROR_CODES.SESSION_NOT_FOUND, `No dashboard state for project "${projectId}"`, false);
    }

    const kpiId = command.kpi_id ||
        state.cards.find(c => c.id === command.target)?.kpiId;

    if (!kpiId) {
        return wrapError(MODULE6_ERROR_CODES.UNKNOWN_KPI, `Could not resolve kpi_id from target "${command.target}"`, false);
    }

    await removeCard(state.id, kpiId);

    return {
        success: true,
        action: 'DELETE_CARD',
        data: { deleted_kpi_id: kpiId },
    };
}

async function handleApplyFilter(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    // Convert command.filters → businessFilters array strings
    // Filters are applied to session globalFilters only — no card mutation
    const filterExpressions: string[] = [];
    if (command.filters) {
        for (const [key, value] of Object.entries(command.filters)) {
            const values = Array.isArray(value) ? value : [value];
            filterExpressions.push(`${key}=${values.join(',')}`);
        }
    }

    // Use Module 5.5 with business filters — re-executes dashboard, updates state
    const result = await runDashboardIntelligence(projectId, {
        businessFilters: filterExpressions,
        skipCache: true,
    });

    return {
        success: true,
        action: 'APPLY_FILTER',
        data: {
            filtersApplied: filterExpressions,
            computedKPIs: result.metadata.computedKPIs,
            stateVersion: result.stateVersion,
        },
    };
}

async function handleCompare(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    if (!command.comparison) {
        return wrapError(MODULE6_ERROR_CODES.SCHEMA_VIOLATION, 'COMPARE requires comparison field', false);
    }

    const { kpi_id_a, kpi_id_b, period } = command.comparison;
    const granularity = period === 'quarterly' ? 'quarterly' : 'monthly';

    // Read-only execution of both KPIs — no state mutation
    const result = await runDashboardIntelligence(projectId, {
        cardIds: undefined, // all cards
        granularity,
        skipCache: true,
        skipSummaryGeneration: false,
        skipAnomalyDetection: false,
    });

    const kpiA = result.kpis.find(k => k.kpiId === kpi_id_a);
    const kpiB = result.kpis.find(k => k.kpiId === kpi_id_b);

    return {
        success: true,
        action: 'COMPARE',
        data: {
            kpi_id_a,
            kpi_id_b,
            period: granularity,
            kpi_a_value: kpiA?.primaryValue ?? null,
            kpi_b_value: kpiB?.primaryValue ?? null,
            kpi_a_name: kpiA?.kpiName ?? null,
            kpi_b_name: kpiB?.kpiName ?? null,
        },
    };
}

async function handleDrillDown(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    if (!command.kpi_id || !command.drill_config) {
        return wrapError(MODULE6_ERROR_CODES.SCHEMA_VIOLATION, 'DRILL_DOWN requires kpi_id and drill_config', false);
    }

    const state = await hydrateDashboard(projectId);
    if (!state) {
        return wrapError(MODULE6_ERROR_CODES.SESSION_NOT_FOUND, `No dashboard state for project "${projectId}"`, false);
    }

    // Find parent card
    const parentCard = state.cards.find(c => c.kpiId === command.kpi_id);

    // Create a drill-down card suggestion (temporary, AI-generated, drill-down flagged)
    const position = state.cards.length;
    const card = await upsertCard(state.id, {
        kpiId: command.kpi_id,
        kpiName: `Drill-down: ${command.drill_config.dimension}`,
        chartType: command.chart_type || 'bar',
        layout: { position, colSpan: 2, rowSpan: 1, cardSize: 'lg' },
        groupBy: command.drill_config.dimension,
        filterOverrides: [],
        isAIGenerated: true,
        isDrillDown: true,
        parentCardId: parentCard?.id ?? null,
    });

    return {
        success: true,
        action: 'DRILL_DOWN',
        data: {
            drill_card_id: card.id,
            parent_kpi_id: command.kpi_id,
            dimension: command.drill_config.dimension,
            filter_value: command.drill_config.value,
        },
    };
}

// ─── Main Bridge ──────────────────────────────────────────────────────────────

/**
 * Execute a validated Module6Command by delegating to the appropriate
 * state-engine / Module-5.5 API.
 *
 * NEVER imports sql-compiler, pool, or prisma directly.
 * All failures return { success: false, error: {...} } — never throws raw.
 */
export async function executeCommand(
    projectId: string,
    command: Module6Command
): Promise<ExecutionResult> {
    try {
        switch (command.action) {
            case 'CREATE_CARD': return await handleCreateCard(projectId, command);
            case 'UPDATE_CARD': return await handleUpdateCard(projectId, command);
            case 'DELETE_CARD': return await handleDeleteCard(projectId, command);
            case 'APPLY_FILTER': return await handleApplyFilter(projectId, command);
            case 'COMPARE': return await handleCompare(projectId, command);
            case 'DRILL_DOWN': return await handleDrillDown(projectId, command);

            default: {
                const exhaustive: never = command.action;
                return wrapError(
                    MODULE6_ERROR_CODES.UNSUPPORTED_ACTION,
                    `Unsupported action: ${exhaustive}`,
                    false
                );
            }
        }
    } catch (err: any) {
        // Wrap raw exceptions — never expose to caller
        const message = err instanceof Error ? err.message : 'Unknown execution error';
        return wrapError(MODULE6_ERROR_CODES.EXECUTION_FAILED, message, false);
    }
}

// Module 6A — Main Entry Point
// handleAskAI() orchestrates the full NL → Validated JSON Command → Execution pipeline.
// This is the ONLY function that should be called from the API route.

import { hydrateDashboard } from '@/lib/dashboard-state/state-engine';
import type { DashboardCardState } from '@/lib/dashboard-state/types';
import db from '@/lib/prisma';
import { buildContext, computeDatasetVersionId, contextToPromptString } from './context-builder';
import { callLLM, LLMCallError } from './llm-client';
import { runValidationPipeline } from './validation-pipeline';
import { generateIntentId, checkDuplicate } from './idempotency';
import { executeCommand } from './execution-bridge';
import { writeAuditRecord } from './audit-log';
import { MODULE6_ERROR_CODES } from './types';
import type { Module6Response, AuditRecord, Module6ErrorPayload } from './types';

// ─── Query Normalization ──────────────────────────────────────────────────────

/**
 * Normalize user query for deterministic hashing.
 * Lowercase, trim, collapse whitespace, strip leading punctuation.
 */
function normalizeQuery(raw: string): string {
    return raw
        .toLowerCase()
        .trim()
        .replace(/\s+/g, ' ')
        .replace(/^[^a-z0-9]+/, '');
}

// ─── Session + KPI Context Loader ─────────────────────────────────────────────

interface SessionContext {
    stateId: string;
    stateVersion: number;
    datasetVersionId: string;
    domain: string;
    eligibleKPIs: Array<{ id: string; name: string; category: string; unit: string | null }>;
    dimensions: string[];
    availableFilters: string[];
}

async function loadSessionContext(projectId: string): Promise<SessionContext | null> {
    const state = await hydrateDashboard(projectId);
    if (!state) return null;

    // Load ApprovedKPIs for this project's blueprint
    const blueprint = await (db as any).kPIBlueprint.findUnique({
        where: { projectId },
        include: {
            kpis: {
                select: { id: true, name: true, category: true, unit: true },
            },
        },
    });

    const eligibleKPIs = (blueprint?.kpis ?? []) as Array<{ id: string; name: string; category: string; unit: string | null }>;

    // Load dimensions from domain context or column schema
    // Dimensions = all group-by candidate columns (from schema or domain detection)
    const domainContext = await (db as any).domainContext?.findUnique?.({ where: { projectId } })
        ?? null;

    const dimensions: string[] = (domainContext?.dimensions as string[] ?? []) ?? state.cards.map((c: DashboardCardState) => c.groupBy).filter((g): g is string => !!g) ?? [];
    const availableFilters: string[] = (domainContext?.availableFilters as string[] ?? []) ?? [];

    const kpiIds = eligibleKPIs.map(k => k.id);
    const datasetVersionId = computeDatasetVersionId(projectId, state.version, kpiIds);

    return {
        stateId: state.id,
        stateVersion: state.version,
        datasetVersionId,
        domain: state.domain,
        eligibleKPIs,
        dimensions,
        availableFilters,
    };
}

// ─── Main Entry Point ─────────────────────────────────────────────────────────

/**
 * Full Module 6A pipeline:
 *
 * 1. Load session + validate it exists
 * 2. Normalize query
 * 3. Generate pre-LLM intent_id
 * 4. Idempotency check — return early if already successful
 * 5. Build immutable context snapshot
 * 6. Call LLM (1 attempt, no retries)
 * 7. Run 5-stage validation pipeline
 * 8. Execute via bridge
 * 9. Write audit log (always)
 * 10. Return Module6Response
 */
export async function handleAskAI(
    projectId: string,
    sessionId: string,
    rawUserQuery: string,
    userId?: string
): Promise<Module6Response> {
    const normalizedQuery = normalizeQuery(rawUserQuery);

    // Step 1: Load session
    let sessionCtx: SessionContext | null;
    try {
        sessionCtx = await loadSessionContext(projectId);
    } catch (err: unknown) {
        const msg = err instanceof Error ? err.message : String(err);
        return {
            status: 'rejected',
            message: 'Failed to load dashboard session.',
            intent_id: 'unknown',
            error: {
                code: MODULE6_ERROR_CODES.SESSION_NOT_FOUND,
                message: msg,
                recoverable: false,
            },
        };
    }

    if (!sessionCtx) {
        return {
            status: 'rejected',
            message: 'No dashboard state found for this project. Run Module 5A first.',
            intent_id: 'unknown',
            error: {
                code: MODULE6_ERROR_CODES.SESSION_NOT_FOUND,
                message: `No dashboard state for project "${projectId}"`,
                recoverable: false,
            },
        };
    }

    // Step 2-3: Generate intent ID (pre-LLM)
    const intentId = generateIntentId(
        normalizedQuery,
        sessionCtx.datasetVersionId,
        sessionId
    );

    // Step 4: Idempotency check
    const dupCheck = await checkDuplicate(intentId);
    if (dupCheck.isDuplicate) {
        return {
            status: 'already_processed',
            message: 'This request was already processed successfully.',
            intent_id: intentId,
        };
    }

    // Step 5: Build context
    const context = buildContext({
        projectId,
        state: await hydrateDashboard(projectId) as Awaited<ReturnType<typeof hydrateDashboard>> & {},
        intentId,
        eligibleKPIs: sessionCtx.eligibleKPIs,
        dimensions: sessionCtx.dimensions,
        availableFilters: sessionCtx.availableFilters,
    });

    // Step 6: Call LLM
    let llmRawOutput: string | undefined;
    try {
        llmRawOutput = await callLLM(rawUserQuery, contextToPromptString(context));
    } catch (err: unknown) {
        const code = err instanceof LLMCallError ? err.code : MODULE6_ERROR_CODES.LLM_CALL_FAILED;
        const message = err instanceof Error ? err.message : 'LLM call failed';

        const auditRecord: AuditRecord = {
            sessionId, userId, intentId,
            rawUserQuery, normalizedUserQuery: normalizedQuery,
            llmRawOutput: undefined,
            validationStagesPassed: 0,
            validationFailedAt: undefined,
            structuredCommand: undefined,
            executionStatus: 'rejected',
            errorCode: code,
        };
        await writeAuditRecord(auditRecord);

        return {
            status: 'rejected',
            message: 'The AI service is temporarily unavailable.',
            intent_id: intentId,
            error: { code, message, recoverable: true },
        };
    }

    // Step 7: 5-stage validation pipeline
    const pipeline = runValidationPipeline(llmRawOutput, context, intentId);

    if (!pipeline.success) {
        const auditRecord: AuditRecord = {
            sessionId, userId, intentId,
            rawUserQuery, normalizedUserQuery: normalizedQuery,
            llmRawOutput,
            validationStagesPassed: pipeline.stagesPassed,
            validationFailedAt: pipeline.failedAt,
            structuredCommand: undefined,
            executionStatus: 'rejected',
            errorCode: pipeline.errorCode,
        };
        await writeAuditRecord(auditRecord);

        return {
            status: 'rejected',
            message: `Command rejected at ${pipeline.failedAt}: ${pipeline.errorMessage}`,
            intent_id: intentId,
            error: {
                code: pipeline.errorCode ?? MODULE6_ERROR_CODES.SCHEMA_VIOLATION,
                message: pipeline.errorMessage ?? 'Validation failed',
                recoverable: false,
                stage: pipeline.failedAt,
            },
        };
    }

    // Step 8: Execute via bridge
    const execution = await executeCommand(projectId, pipeline.command!);

    const executionStatus = execution.success ? 'success' : 'execution_failed';

    // Step 9: Write audit log (unconditional)
    const auditRecord: AuditRecord = {
        sessionId, userId, intentId,
        rawUserQuery, normalizedUserQuery: normalizedQuery,
        llmRawOutput,
        validationStagesPassed: pipeline.stagesPassed,
        validationFailedAt: undefined,
        structuredCommand: pipeline.command,
        executionStatus,
        errorCode: execution.error?.code,
    };
    await writeAuditRecord(auditRecord);

    // Step 10: Return response
    if (!execution.success) {
        return {
            status: 'execution_failed',
            message: execution.error?.message ?? 'Execution failed',
            intent_id: intentId,
            error: execution.error,
        };
    }

    return {
        status: 'success',
        message: `Done — ${pipeline.command!.action} completed successfully.`,
        intent_id: intentId,
        data: execution.data,
    };
}

// Module 6D — Audit Logger
// Extends the Module 6A audit infrastructure with model metadata.
// Uses writeAuditRecord() from module-6/audit-log.ts as the underlying writer.
// Model metadata is stored in the structuredCommand JSON field (no schema migration needed).
// Never throws — audit failure is non-fatal.

import { writeAuditRecord } from '@/lib/module-6/audit-log';
import type { AuditRecord } from '@/lib/module-6/types';
import type { ModelAuditMetadata, ReasoningTaskType, EvidenceInput } from './types';

// ─── Audit Payload ────────────────────────────────────────────────────────────

interface ReasoningAuditPayload {
    projectId: string;
    taskType: ReasoningTaskType;
    userQuery: string;
    sanitizedQuery: string;
    modelMetadata: ModelAuditMetadata;
    narrationStatus: string;
    errorCode?: string;
}

// ─── Writer ───────────────────────────────────────────────────────────────────

/**
 * Write a reasoning audit record with full model metadata.
 *
 * Stores ModelAuditMetadata as JSON in the `structuredCommand` field,
 * which accepts any plain object — no schema migration required.
 *
 * Never throws. Audit failure is logged but does not affect the user response.
 */
export async function writeReasoningAuditRecord(payload: ReasoningAuditPayload): Promise<void> {
    const record: AuditRecord = {
        sessionId: payload.projectId,
        intentId: `6d-${payload.taskType}-${Date.now()}`,
        rawUserQuery: payload.userQuery.slice(0, 2000),
        normalizedUserQuery: payload.sanitizedQuery.slice(0, 2000),
        llmRawOutput: undefined,
        validationStagesPassed: payload.modelMetadata.status === 'success' ? 1 : 0,
        validationFailedAt: undefined,
        structuredCommand: {
            // Overload structuredCommand to carry model metadata
            action: 'REASONING' as any,
            intent_id: `6d-${payload.taskType}-${Date.now()}`,
            ai_generated: true,
            dataset_version_id: 'N/A',
            natural_language_intent: `[6D] ${payload.taskType} | model: ${payload.modelMetadata.modelId} | tier: ${payload.modelMetadata.modelTier} | latency: ${payload.modelMetadata.latencyMs}ms`,
            // Attach full metadata for reconstruction
            ...(payload.modelMetadata as unknown as Record<string, unknown>),
        },
        executionStatus: payload.narrationStatus === 'success' ? 'success' : 'execution_failed',
        errorCode: payload.errorCode,
    };

    try {
        await writeAuditRecord(record);
    } catch (err: any) {
        // Audit failure is non-fatal — log but never propagate to caller
        console.error('[Module6D/audit] Failed to write reasoning audit record:', err.message ?? err);
    }
}

// Module 6D — Entry Point
// handleReasoningQuery() — 8-step tiered reasoning pipeline.
//
// Steps:
//   1. Classify task type (deterministic, no LLM)
//   2. Reject UNSUPPORTED → UNSUPPORTED_REASONING_SCOPE
//   3. Route to adapter (LOCAL / CLOUD) via model-router
//   4. Check feature flag (cloud tasks require ENABLE_CLOUD_ROUTING=true)
//   5. Build evidence-only, sanitized prompt
//   6. Call adapter (single attempt, no retry)
//   7. Validate numeric integrity (model-agnostic)
//   8. Write audit record (unconditional, non-fatal)
//   9. Return ReasoningResult
//
// Invariants preserved:
//   - No dashboard state mutation
//   - No raw SQL in prompts
//   - No free-form AI behavior
//   - Numeric claims validated against evidence packet, regardless of model

import { classifyReasoningTask, getUnsupportedReasoningMessage } from './task-classifier';
import { routeTask, isRoutingDecision } from './model-router';
import { buildReasoningPrompt } from './prompt-builder';
import { callLocalModel } from './local-adapter';
import { callCloudModel } from './cloud-adapter';
import { validateNumericClaims } from '../shared/numeric-guard';
import { writeReasoningAuditRecord } from './audit-logger';
import type {
    EvidenceInput,
    ModelAuditMetadata,
    ReasoningResult,
    ClassificationContext,
    ReasoningTaskType,
    AdapterResponse,
} from './types';
import { ModelCallError } from './types';

// ─── Main Entry Point ─────────────────────────────────────────────────────────

/**
 * Full Module 6D reasoning pipeline.
 *
 * @param projectId    Project identifier — used for audit trail
 * @param rawTaskType  Reasoning task type string (classified deterministically)
 * @param evidence     Frozen EventEvidencePacket or CorrelationEvidencePacket
 * @param userQuery    Raw user question — will be sanitized before prompt injection
 * @param context      Optional classification context (e.g. hasMultipleKPIs)
 */
export async function handleReasoningQuery(
    projectId: string,
    rawTaskType: string,
    evidence: EvidenceInput,
    userQuery: string,
    context?: ClassificationContext
): Promise<ReasoningResult> {

    // ── Step 1: Classify task ─────────────────────────────────────────────────
    const taskType: ReasoningTaskType = classifyReasoningTask(rawTaskType, context);

    // ── Step 2: Reject UNSUPPORTED ────────────────────────────────────────────
    if (taskType === 'UNSUPPORTED') {
        return {
            status: 'rejected',
            message: getUnsupportedReasoningMessage(rawTaskType),
        };
    }

    // ── Step 3 + 4: Route to adapter (includes feature flag check) ───────────
    const routing = routeTask(taskType);

    if (!isRoutingDecision(routing)) {
        // Structured rejection — e.g. MODEL_UNAVAILABLE when cloud disabled
        return {
            status: 'rejected',
            message: routing.message,
        };
    }

    // ── Step 5: Build evidence-only, sanitized prompt ─────────────────────────
    const { systemPrompt, userMessage, sanitizedQuery } = buildReasoningPrompt(
        taskType,
        evidence,
        userQuery
    );

    // ── Step 6: Call adapter (single attempt, no retry) ──────────────────────
    const startMs = Date.now();
    let adapterResponse: AdapterResponse;

    try {
        if (routing.tier === 'LOCAL') {
            adapterResponse = await callLocalModel(systemPrompt, userMessage, routing.temperature, routing.modelId);
        } else {
            adapterResponse = await callCloudModel(systemPrompt, userMessage, routing.temperature, routing.modelId);
        }
    } catch (err: unknown) {
        const e = err as any;
        const isModelError = e?.name === 'ModelCallError' || typeof e?.code === 'string';
        const code = isModelError ? (e.code as string) : 'ADAPTER_FAILED';
        const msg = isModelError ? (e.message as string) : 'Model adapter call failed with an unexpected error';
        const isTimeout = code === 'LOCAL_TIMEOUT' || code === 'CLOUD_TIMEOUT';

        // Write audit record for failed call
        const failedMetadata: ModelAuditMetadata = {
            taskType,
            modelTier: routing.tier,
            modelId: routing.modelId,
            temperature: routing.temperature,
            latencyMs: Date.now() - startMs,
            status: isTimeout ? 'timeout' : 'error',
        };
        await writeReasoningAuditRecord({
            projectId, taskType, userQuery, sanitizedQuery,
            modelMetadata: failedMetadata,
            narrationStatus: 'failed',
            errorCode: code,
        });

        return {
            status: isTimeout ? 'timeout' : 'rejected',
            message: msg,
            modelMetadata: failedMetadata,
        };
    }

    // ── Step 7: Validate numeric integrity ────────────────────────────────────
    const guardResult = validateNumericClaims(adapterResponse.text, evidence);

    const finalStatus = guardResult.status === 'valid' ? 'success' : 'suppressed';

    // ── Step 8: Write audit record (unconditional) ────────────────────────────
    const modelMetadata: ModelAuditMetadata = {
        taskType,
        modelTier: routing.tier,
        modelId: adapterResponse.modelId,
        temperature: routing.temperature,
        inputTokens: adapterResponse.inputTokens,
        outputTokens: adapterResponse.outputTokens,
        latencyMs: adapterResponse.latencyMs,
        status: finalStatus,
    };

    await writeReasoningAuditRecord({
        projectId, taskType, userQuery, sanitizedQuery,
        modelMetadata,
        narrationStatus: finalStatus,
    });

    // ── Step 9: Return result ─────────────────────────────────────────────────
    if (guardResult.status === 'suppressed') {
        return {
            status: 'suppressed',
            message: guardResult.message!,
            evidence,
            modelMetadata,
        };
    }

    return {
        status: 'success',
        explanation: guardResult.explanation,
        evidence,
        modelMetadata,
    };
}

// Module 6D — Local Model Adapter (Ollama + Cloud Routing)
// Communicates with Ollama HTTP API (Local or Cloud).
// Attempts cloud first (if configured), falls back to local on failure.
// Throws ModelCallError on timeout or API failure.

import { ModelCallError, LOCAL_TIMEOUT_MS, MAX_TOKENS, LOCAL_MODEL_ID } from './types';
import type { AdapterResponse } from './types';

// ─── Config ───────────────────────────────────────────────────────────────────

function getLocalOllamaBaseUrl(): string {
    return (process.env.OLLAMA_URL ?? 'http://localhost:11434').replace(/\/$/, '');
}

function getCloudConfig() {
    const url = (process.env.CLOUD_AI_BASE_URL || process.env.OLLAMA_CLOUD_URL)?.replace(/\/$/, '');
    const key = process.env.CLOUD_AI_API_KEY || process.env.OLLAMA_CLOUD_API_KEY;
    const model = process.env.CLOUD_AI_MODEL || process.env.OLLAMA_CLOUD_MODEL || 'qwen3.5:397b';

    return {
        url,
        key,
        model,
    };
}

// ─── Request Shape ────────────────────────────────────────────────────────────

interface OllamaGenerateRequest {
    model: string;
    prompt: string;
    system?: string;
    stream: false;
    options?: {
        temperature?: number;
        num_predict?: number;
        stop?: string[];
    };
}

interface OllamaGenerateResponse {
    response: string;
    prompt_eval_count?: number;
    eval_count?: number;
    done: boolean;
}

// ─── Adapter ──────────────────────────────────────────────────────────────────

/**
 * Smart Router: Cloud First, Local Fallback
 */
export async function callLocalModel(
    systemPrompt: string,
    userMessage: string,
    temperature: number,
    localModelId: string = process.env.OLLAMA_MODEL || LOCAL_MODEL_ID
): Promise<AdapterResponse> {
    const cloud = getCloudConfig();

    if (cloud.url && cloud.key) {
        console.log(`[AI Router] Attempting Cloud Model: ${cloud.model} at ${cloud.url}`);
        try {
            return await _doCallOllama(systemPrompt, userMessage, temperature, cloud.model, cloud.url, cloud.key, 120000);
        } catch (cloudErr: any) {
            console.warn(`[AI Router] Cloud model failed (${cloudErr.message}). Falling back to local...`);
            // Fall through to local
        }
    }

    console.log(`[AI Router] Using Local Model: ${localModelId}`);
    return await _doCallOllama(systemPrompt, userMessage, temperature, localModelId, getLocalOllamaBaseUrl(), undefined, 120000);
}

async function _doCallOllama(
    systemPrompt: string,
    userMessage: string,
    temperature: number,
    modelId: string,
    baseUrl: string,
    apiKey?: string,
    timeoutMs: number = 120000
): Promise<AdapterResponse> {
    const url = `${baseUrl}/api/generate`;

    const body = {
        model: modelId,
        system: systemPrompt,
        prompt: userMessage,
        stream: false,
        options: {
            temperature,
            num_predict: MAX_TOKENS,
            stop: ['\n\n\n'],   // Prevent runaway generation
        }
    };

    const headers: Record<string, string> = {
        'Content-Type': 'application/json'
    };

    if (apiKey) {
        headers['Authorization'] = `Bearer ${apiKey}`;
    }

    const controller = new AbortController();
    const timeoutHandle = setTimeout(() => controller.abort(), timeoutMs);
    const startMs = Date.now();

    let res: Response;
    try {
        res = await fetch(url, {
            method: 'POST',
            headers,
            body: JSON.stringify(body),
            signal: controller.signal,
        });
    } catch (err: any) {
        clearTimeout(timeoutHandle);
        if (err.name === 'AbortError') {
            throw new ModelCallError(
                'LOCAL_TIMEOUT',
                `Model ${modelId} timed out after ${timeoutMs}ms`,
                true
            );
        }
        throw new ModelCallError(
            'LOCAL_CALL_FAILED',
            `API call failed for ${modelId}: ${err.message ?? 'unknown error'}`,
            false
        );
    } finally {
        clearTimeout(timeoutHandle);
    }

    const latencyMs = Date.now() - startMs;

    if (!res.ok) {
        const errorText = await res.text();
        throw new ModelCallError(
            'LOCAL_CALL_FAILED',
            `API returned HTTP ${res.status} for ${modelId}: ${errorText}`,
            false
        );
    }

    let data: OllamaGenerateResponse;
    try {
        data = await res.json() as OllamaGenerateResponse;
    } catch {
        throw new ModelCallError('LOCAL_CALL_FAILED', `Response was not valid JSON for ${modelId}`, false);
    }

    const text = data.response?.trim();
    if (!text) {
        throw new ModelCallError('LOCAL_CALL_FAILED', `Returned empty response for ${modelId}`, false);
    }

    return {
        text,
        modelId,
        inputTokens: data.prompt_eval_count,
        outputTokens: data.eval_count,
        latencyMs,
    };
}

// src/lib/module-6f/orchestrator.ts

export type IntentRoute = 'metric_retrieval' | 'trend_analysis' | 'comparison' | 'contextual_explanation' | 'correlation_analysis' | 'synthesis' | 'command' | 'goal_generation' | 'unsupported';

export interface ConversationMemory {
    sessionId: string;
    lastKpiId?: string;
    lastKpiName?: string;
    lastTimeRange?: string;
    lastIntent?: IntentRoute;
    clarificationPending?: boolean;
    clarificationOptions?: Array<{ id: string; name: string }>;
    updatedAt: number;
}

// In-memory cache for conversational state. 
// Rules strictly mandate this is session-only and holds max 5 turns of semantic metadata (not raw data).
// Note: In a true scale-out production environment, this would be Redis. We use an in-memory Map here per requirements.
const memoryStore = new Map<string, ConversationMemory>();

// Cleanup interval: Remove sessions older than 30 minutes
setInterval(() => {
    const now = Date.now();
    for (const [key, mem] of Array.from(memoryStore.entries())) {
        if (now - mem.updatedAt > 30 * 60 * 1000) {
            memoryStore.delete(key);
        }
    }
}, 5 * 60 * 1000);

export function getSessionMemory(sessionId: string): ConversationMemory {
    if (!memoryStore.has(sessionId)) {
        memoryStore.set(sessionId, {
            sessionId,
            updatedAt: Date.now()
        });
    }
    return memoryStore.get(sessionId)!;
}

export function updateSessionMemory(sessionId: string, updates: Partial<ConversationMemory>) {
    const mem = getSessionMemory(sessionId);
    memoryStore.set(sessionId, {
        ...mem,
        ...updates,
        updatedAt: Date.now()
    });
}

export function clearSessionMemory(sessionId: string) {
    memoryStore.delete(sessionId);
}

/**
 * Pronoun Resolution Step.
 * If the user says "it", "that", "this", "them" or "those", we try to swap it
 * with the last known KPI name from memory. Note this is a safe string replacement
 * before regex intent matching happens.
 */
export function resolvePronouns(message: string, memory: ConversationMemory): string {
    if (!memory.lastKpiName) return message;

    const msgLower = message.toLowerCase();

    // Check for common pronouns that need resolution in isolated word boundaries
    const pronounRegex = /\b(it|that|this|them|those)\b/gi;

    if (pronounRegex.test(message)) {
        // We replace it. Example: "Why did it increase?" -> "Why did Revenue increase?"
        return message.replace(pronounRegex, memory.lastKpiName);
    }

    return message;
}

/**
 * Context Injection Step.
 * If the user query does not name any specific KPI but asks an intent
 * that requires one (e.g. "What is the trend?"), and we have one in memory,
 * we safely append the context to the end so extractors find it.
 */
export function injectContext(message: string, memory: ConversationMemory): string {
    if (!memory.lastKpiName) return message;

    // A very loose heuristic: if the message is extremely short and has no existing KPI-like noun,
    // we append the context to aid extraction.
    // E.g. "compare with Q2" -> "compare with Q2 Revenue"
    return `${message} ${memory.lastKpiName}`;
}

/**
 * Suggestions Generator.
 * Predicts the next logical 2-3 questions based on the last interaction.
 */
export function getFollowUpSuggestions(memory: ConversationMemory): string[] {
    const suggestions: string[] = [];
    const kpi = memory.lastKpiName || 'this KPI';

    switch (memory.lastIntent) {
        case 'metric_retrieval':
            suggestions.push(`Show trend of ${kpi}`);
            suggestions.push(`Why did ${kpi} change?`);
            suggestions.push(`Compare ${kpi} with Profit`);
            break;
        case 'trend_analysis':
            suggestions.push(`Calculate volatility of ${kpi}`);
            suggestions.push(`What events affected ${kpi}?`);
            suggestions.push(`See current ${kpi} value`);
            break;
        case 'correlation_analysis':
            suggestions.push(`Show trend of both KPIs`);
            suggestions.push(`Calculate lag optimization`);
            suggestions.push(`Synthesize overall risk`);
            break;
        case 'contextual_explanation':
            suggestions.push(`Compare with similar period`);
            suggestions.push(`Show related correlations`);
            suggestions.push(`Add ${kpi} to dashboard`);
            break;
        default:
            suggestions.push("What is total revenue?");
            suggestions.push("Show me customer trends");
            suggestions.push("Analyze correlation between Revenue and Profit");
    }

    return suggestions.slice(0, 3);
}

// Module 6E — Entry Point
// handleSynthesisQuery() — 11-step multi-evidence synthesis pipeline.
//
// Invariants:
//   - Never recomputes statistics
//   - Never calls statistics-core
//   - Never accesses database
//   - Never mutates dashboard state
//   - Never bypasses numeric guard
//   - Never allows non-significant correlations into synthesis
//   - Never fabricates forward projections

import { governPackets } from './packet-governance';
import { detectConflicts } from './conflict-detector';
import { classifySynthesisTask, getUnsupportedScopeMessage } from './synthesis-classifier';
import { buildSynthesisPrompt } from './synthesis-prompt-builder';
import { checkCausation } from './causation-guard';
import { validateNumericClaims } from '../shared/numeric-guard';
import { writeSynthesisAuditRecord } from './synthesis-audit-logger';
import { callLocalModel } from '@/lib/module-6/infrastructure/local-adapter';
import { callCloudModel } from '@/lib/module-6/infrastructure/cloud-adapter';
import { isCloudRoutingEnabled } from '@/lib/module-6/infrastructure/model-router';
import {
    SYNTHESIS_TIER_MAP,
    SYNTHESIS_TEMPERATURE,
} from './types';
import type {
    EventEvidencePacket,
    CorrelationEvidencePacket,
    SynthesisResult,
    SynthesisTaskType,
    SynthesisAuditMetadata,
    ConflictDescriptor,
} from './types';
import { LOCAL_MODEL_ID, CLOUD_MODEL_ID, type AdapterResponse } from '@/lib/module-6/infrastructure/types';

// ─── Main Pipeline ────────────────────────────────────────────────────────────

export async function handleSynthesisQuery(
    projectId: string,
    events: EventEvidencePacket[],
    correlations: CorrelationEvidencePacket[],
    userQuery: string
): Promise<SynthesisResult> {
    const now = new Date().toISOString();

    // ── Step 1: Govern packets ────────────────────────────────────────────────
    const governed = governPackets(events, correlations);

    if (governed.reason) {
        return {
            status: 'rejected',
            message: governed.reason,
            supportingPacketIds: [],
            conflictSummary: [],
            generatedAt: now,
        };
    }

    // ── Step 2: Detect conflicts ──────────────────────────────────────────────
    const conflicts = detectConflicts(governed.events, governed.correlations);

    // ── Step 3: Classify synthesis tier ────────────────────────────────────────
    const taskType = classifySynthesisTask(
        governed.events.length,
        governed.correlations.length,
        userQuery
    );

    // ── Step 4: Reject UNSUPPORTED_SCOPE ──────────────────────────────────────
    if (taskType === 'UNSUPPORTED_SCOPE') {
        return {
            status: 'rejected',
            message: getUnsupportedScopeMessage(userQuery),
            supportingPacketIds: [],
            conflictSummary: [],
            generatedAt: now,
        };
    }

    // ── Step 5: Route to model ────────────────────────────────────────────────
    const tier = SYNTHESIS_TIER_MAP[taskType];
    const modelId = tier === 'LOCAL' ? LOCAL_MODEL_ID : CLOUD_MODEL_ID;

    if (tier === 'CLOUD' && !isCloudRoutingEnabled()) {
        return {
            status: 'rejected',
            message: 'Cloud reasoning is not enabled. Strategic and risk analysis require ENABLE_CLOUD_ROUTING=true.',
            supportingPacketIds: [],
            conflictSummary: conflicts,
            generatedAt: now,
        };
    }

    // ── Step 6: Build synthesis prompt ─────────────────────────────────────────
    const { systemPrompt, userMessage, sanitizedQuery } = buildSynthesisPrompt(
        taskType,
        governed.events,
        governed.correlations,
        conflicts,
        userQuery
    );

    // Collect packet IDs
    const packetIds = [
        ...governed.events.map(e => e.event_id),
        ...governed.correlations.map(c => c.insight_id),
    ];

    // ── Step 7: Call adapter ──────────────────────────────────────────────────
    const startMs = Date.now();
    let adapterResponse: AdapterResponse;

    try {
        if (tier === 'LOCAL') {
            adapterResponse = await callLocalModel(systemPrompt, userMessage, SYNTHESIS_TEMPERATURE, modelId);
        } else {
            adapterResponse = await callCloudModel(systemPrompt, userMessage, SYNTHESIS_TEMPERATURE, modelId);
        }
    } catch (err: any) {
        const code = err?.code ?? 'ADAPTER_FAILED';
        const isTimeout = code === 'LOCAL_TIMEOUT' || code === 'CLOUD_TIMEOUT';

        const auditMeta: SynthesisAuditMetadata = {
            reasoningTier: taskType, packetIds, modelTier: tier, modelId,
            latencyMs: Date.now() - startMs, suppressionFlag: false,
            conflictCount: conflicts.length, cloudRoutingEnabled: isCloudRoutingEnabled(),
            status: isTimeout ? 'timeout' : 'error',
        };
        await writeSynthesisAuditRecord({
            projectId, userQuery, sanitizedQuery,
            metadata: auditMeta, narrationStatus: 'failed', errorCode: code,
        });

        return {
            status: isTimeout ? 'timeout' : 'rejected',
            message: err?.message ?? 'Model adapter call failed.',
            supportingPacketIds: packetIds,
            conflictSummary: conflicts,
            generatedAt: now,
        };
    }

    // ── Step 8: Causation guard ───────────────────────────────────────────────
    const causationResult = checkCausation(adapterResponse.text);
    if (!causationResult.passed) {
        const auditMeta: SynthesisAuditMetadata = {
            reasoningTier: taskType, packetIds, modelTier: tier, modelId: adapterResponse.modelId,
            latencyMs: adapterResponse.latencyMs, suppressionFlag: true,
            conflictCount: conflicts.length, cloudRoutingEnabled: isCloudRoutingEnabled(),
            status: 'causation_violation',
        };
        await writeSynthesisAuditRecord({
            projectId, userQuery, sanitizedQuery,
            metadata: auditMeta, narrationStatus: 'causation_violation',
            errorCode: 'CAUSATION_VIOLATION',
        });

        return {
            status: 'causation_violation',
            message: `Response suppressed: model used causal language ("${causationResult.violatingPhrase}"). VistaraBI only states correlation, not causation.`,
            supportingPacketIds: packetIds,
            conflictSummary: conflicts,
            generatedAt: now,
        };
    }

    // ── Step 9: Cross-packet numeric guard ────────────────────────────────────
    const guardResult = validateNumericClaims(
        adapterResponse.text,
        [...governed.events, ...governed.correlations],
        'This synthesized insight could not be validated against the available statistical evidence and was suppressed.'
    );

    const isSuppressed = guardResult.status === 'suppressed';
    const finalStatus = isSuppressed ? 'suppressed' : 'success';

    // ── Step 10: Write audit record (unconditional) ───────────────────────────
    const auditMeta: SynthesisAuditMetadata = {
        reasoningTier: taskType, packetIds, modelTier: tier,
        modelId: adapterResponse.modelId,
        latencyMs: adapterResponse.latencyMs,
        suppressionFlag: isSuppressed,
        conflictCount: conflicts.length,
        cloudRoutingEnabled: isCloudRoutingEnabled(),
        status: finalStatus,
    };
    await writeSynthesisAuditRecord({
        projectId, userQuery, sanitizedQuery,
        metadata: auditMeta, narrationStatus: finalStatus,
    });

    // ── Step 11: Return result ────────────────────────────────────────────────
    return {
        status: finalStatus,
        reasoningTier: taskType,
        narrative: isSuppressed ? undefined : guardResult.explanation,
        message: isSuppressed ? guardResult.message : undefined,
        supportingPacketIds: packetIds,
        conflictSummary: conflicts,
        modelMetadata: {
            tier,
            routing: tier === 'LOCAL' ? 'local' : 'cloud',
            latencyMs: adapterResponse.latencyMs,
            suppression: isSuppressed,
        },
        generatedAt: now,
    };
}

