// Module 6A — Validation Pipeline
// 5-stage sequential pipeline. Any stage failure stops the pipeline immediately.
// No stage silently corrects input. All errors are structured and named.

import { parseCommandSchema } from './command-schema';
import { verifyIntentId } from './idempotency';
import { MODULE6_ERROR_CODES } from './types';
import type {
    Module6Command,
    Module6Context,
    PipelineResult,
    ValidationStage,
} from './types';

// ─── Security Patterns ────────────────────────────────────────────────────────
// Reject any output containing these patterns regardless of structure.

const SECURITY_PATTERNS: RegExp[] = [
    /\bSELECT\b/i,
    /\bFROM\b/i,
    /\bWHERE\b/i,
    /\bJOIN\b/i,
    /;/,               // SQL statement terminator
    /\.\.\//,          // Path traversal
    /\$\{/,            // Template literal injection
    /\bDROP\b/i,
    /\bINSERT\b/i,
    /\bUPDATE\b/i,
    /\bDELETE\b/i,
    /\bEXEC\b/i,
    /\bEXECUTE\b/i,
];

// ─── Stage 1: Parse Guard ─────────────────────────────────────────────────────

function stage1Parse(rawOutput: string): {
    ok: true;
    parsed: unknown;
} | { ok: false; code: string; message: string } {
    let cleaned = rawOutput.trim();

    // Strip ```json ... ``` fences if present
    if (cleaned.startsWith('```')) {
        cleaned = cleaned
            .replace(/^```(?:json)?\s*/i, '')
            .replace(/\s*```$/, '')
            .trim();
    }

    if (!cleaned.startsWith('{')) {
        return {
            ok: false,
            code: MODULE6_ERROR_CODES.INVALID_JSON,
            message: 'LLM output does not start with a JSON object',
        };
    }

    try {
        const parsed = JSON.parse(cleaned);
        if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.NOT_AN_OBJECT,
                message: 'Parsed JSON is not a plain object',
            };
        }
        return { ok: true, parsed };
    } catch {
        return {
            ok: false,
            code: MODULE6_ERROR_CODES.INVALID_JSON,
            message: 'LLM output is not valid JSON',
        };
    }
}

// ─── Stage 2: Schema Validation ──────────────────────────────────────────────

function stage2Schema(parsed: unknown): {
    ok: true;
    command: Module6Command;
} | { ok: false; code: string; message: string } {
    const result = parseCommandSchema(parsed);

    if (!result.success) {
        const first = result.errors[0];
        return {
            ok: false,
            code: MODULE6_ERROR_CODES.SCHEMA_VIOLATION,
            message: `Schema violation at "${first.field}": ${first.message}`,
        };
    }

    // Double-check ai_generated (Zod already enforces this, but belt-and-suspenders)
    if (result.command.ai_generated !== true) {
        return {
            ok: false,
            code: MODULE6_ERROR_CODES.AI_GENERATED_FALSE,
            message: 'ai_generated must be boolean true',
        };
    }

    return { ok: true, command: result.command as Module6Command };
}

// ─── Stage 3: DCO Validation ─────────────────────────────────────────────────

function stage3DCO(
    command: Module6Command,
    context: Module6Context
): { ok: true } | { ok: false; code: string; message: string } {
    // dataset_version_id must match the signed snapshot
    if (command.dataset_version_id !== context.dataset_version_id) {
        return {
            ok: false,
            code: MODULE6_ERROR_CODES.STALE_DATASET_VERSION,
            message: `dataset_version_id mismatch: command has "${command.dataset_version_id}", expected "${context.dataset_version_id}"`,
        };
    }

    // kpi_id must exist in eligible KPIs
    if (command.kpi_id) {
        const eligibleIds = new Set(context.eligible_kpis.map(k => k.id));
        if (!eligibleIds.has(command.kpi_id)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.UNKNOWN_KPI,
                message: `kpi_id "${command.kpi_id}" is not in eligible_kpis`,
            };
        }
    }

    // group_by must be in dimensions
    if (command.group_by) {
        const dimSet = new Set(context.dimensions);
        if (!dimSet.has(command.group_by)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.UNKNOWN_DIMENSION,
                message: `group_by "${command.group_by}" is not in available dimensions`,
            };
        }
    }

    // filter keys must all be in available_filters
    if (command.filters) {
        const filterSet = new Set(context.available_filters);
        for (const key of Object.keys(command.filters)) {
            if (!filterSet.has(key)) {
                return {
                    ok: false,
                    code: MODULE6_ERROR_CODES.UNKNOWN_FILTER,
                    message: `Filter key "${key}" is not in available_filters`,
                };
            }
        }
    }

    // Validate COMPARE kpi_ids
    if (command.comparison) {
        const eligibleIds = new Set(context.eligible_kpis.map(k => k.id));
        if (!eligibleIds.has(command.comparison.kpi_id_a)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.UNKNOWN_KPI,
                message: `comparison.kpi_id_a "${command.comparison.kpi_id_a}" is not in eligible_kpis`,
            };
        }
        if (!eligibleIds.has(command.comparison.kpi_id_b)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.UNKNOWN_KPI,
                message: `comparison.kpi_id_b "${command.comparison.kpi_id_b}" is not in eligible_kpis`,
            };
        }
    }

    return { ok: true };
}

// ─── Stage 4: Security Scan ──────────────────────────────────────────────────

function stage4Security(
    command: Module6Command
): { ok: true } | { ok: false; code: string; message: string } {
    const serialized = JSON.stringify(command);

    for (const pattern of SECURITY_PATTERNS) {
        if (pattern.test(serialized)) {
            return {
                ok: false,
                code: MODULE6_ERROR_CODES.SECURITY_VIOLATION,
                message: `Security pattern "${pattern.source}" matched in command payload`,
            };
        }
    }

    return { ok: true };
}

// ─── Stage 5: Idempotency Gate ───────────────────────────────────────────────

function stage5Idempotency(
    command: Module6Command,
    expectedIntentId: string
): { ok: true } | { ok: false; code: string; message: string } {
    const tamperingCode = verifyIntentId(command.intent_id, expectedIntentId);
    if (tamperingCode) {
        return {
            ok: false,
            code: tamperingCode,
            message: `intent_id mismatch: LLM altered the hash. Expected "${expectedIntentId}", got "${command.intent_id}"`,
        };
    }

    return { ok: true };
}

// ─── Main Pipeline ────────────────────────────────────────────────────────────

const STAGE_ORDER: ValidationStage[] = [
    'STAGE_1_PARSE',
    'STAGE_2_SCHEMA',
    'STAGE_3_DCO',
    'STAGE_4_SECURITY',
    'STAGE_5_IDEMPOTENCY',
];

/**
 * Run all 5 validation stages in sequence.
 * Returns PipelineResult — never throws.
 */
export function runValidationPipeline(
    rawLLMOutput: string,
    context: Module6Context,
    expectedIntentId: string
): PipelineResult {
    let stagesPassed = 0;
    let command: Module6Command | undefined;
    let parsed: unknown;

    // Stage 1: Parse
    const s1 = stage1Parse(rawLLMOutput);
    if (!s1.ok) {
        return { success: false, stagesPassed: 0, failedAt: 'STAGE_1_PARSE', errorCode: s1.code, errorMessage: s1.message };
    }
    parsed = s1.parsed;
    stagesPassed = 1;

    // Stage 2: Schema
    const s2 = stage2Schema(parsed);
    if (!s2.ok) {
        return { success: false, stagesPassed: 1, failedAt: 'STAGE_2_SCHEMA', errorCode: s2.code, errorMessage: s2.message };
    }
    command = s2.command;
    stagesPassed = 2;

    // Stage 3: DCO
    const s3 = stage3DCO(command, context);
    if (!s3.ok) {
        return { success: false, stagesPassed: 2, failedAt: 'STAGE_3_DCO', errorCode: s3.code, errorMessage: s3.message };
    }
    stagesPassed = 3;

    // Stage 4: Security
    const s4 = stage4Security(command);
    if (!s4.ok) {
        return { success: false, stagesPassed: 3, failedAt: 'STAGE_4_SECURITY', errorCode: s4.code, errorMessage: s4.message };
    }
    stagesPassed = 4;

    // Stage 5: Idempotency
    const s5 = stage5Idempotency(command, expectedIntentId);
    if (!s5.ok) {
        return { success: false, stagesPassed: 4, failedAt: 'STAGE_5_IDEMPOTENCY', errorCode: s5.code, errorMessage: s5.message };
    }
    stagesPassed = 5;

    return { success: true, command, stagesPassed };
}

// Module 7: Goal Decomposer
// Breaks down a primary goal into contributing sub-KPIs based on domain logic

import { ParsedGoal } from './goal-parser';

export interface DecomposedFactor {
    metric: string;
    requiredChange: string;
    requiredChangePercent?: number;
    description: string;
    weight: number; // 0–1, how much this factor contributes to the primary KPI
}

export interface DecomposedGoal {
    primaryMetric: string;
    targetValue: string;
    changeDirection: 'increase' | 'decrease' | 'maintain';
    factors: DecomposedFactor[];
    formula: string;
}

/**
 * Deterministic decomposition of a goal into its driving sub-KPIs.
 * Based on domain KPI formulas from the Module 4 blueprint.
 */
export function decomposeGoal(goal: ParsedGoal, domain: string): DecomposedGoal {
    const factors: DecomposedFactor[] = [];
    const changePercent = goal.changePercent;
    const target = goal.targetValue;
    const dir = goal.changeDirection;

    const changeLabel = dir === 'decrease'
        ? `↓ ${target}`
        : `↑ ${target}`;

    let formula = '';

    // ── E-Commerce / Retail: Revenue ───────────────────────────────────────────
    if (goal.kpiId === 'ec-001' || goal.targetMetric === 'revenue' ||
        goal.kpiId === 'rt-001' || goal.targetMetric === 'store sales') {
        formula = 'Revenue = Orders × AOV × (1 − Discount Rate)';
        factors.push(
            {
                metric: 'Order Count',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.5 : undefined,
                description: 'Increase the total number of orders placed by attracting more customers or improving repeat purchase rate.',
                weight: 0.5,
            },
            {
                metric: 'Average Order Value',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.3 : undefined,
                description: 'Increase the average spend per order through upselling, bundling, or minimum-spend promotions.',
                weight: 0.3,
            },
            {
                metric: 'Discount Rate',
                requiredChange: '↓ Reduce discounts',
                description: 'Reduce excessive discounting to protect margins while maintaining volume.',
                weight: 0.2,
            }
        );
    }

    // ── E-Commerce: Conversion Rate ─────────────────────────────────────────────
    else if (goal.kpiId === 'ec-004' || goal.targetMetric === 'conversion rate') {
        formula = 'Conversion Rate = (Orders / Sessions) × 100';
        factors.push(
            {
                metric: 'Session Quality',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.4 : undefined,
                description: 'Improve traffic quality by focusing paid ads on high-intent audiences.',
                weight: 0.4,
            },
            {
                metric: 'Checkout Completion',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.4 : undefined,
                description: 'Reduce cart abandonment with streamlined checkout and trust signals.',
                weight: 0.4,
            },
            {
                metric: 'Product Page Engagement',
                requiredChange: changeLabel,
                description: 'Improve product images, reviews, and CTAs to drive add-to-cart.',
                weight: 0.2,
            }
        );
    }

    // ── SaaS: MRR ───────────────────────────────────────────────────────────────
    else if (goal.kpiId === 'saas-001' || goal.targetMetric === 'mrr') {
        formula = 'MRR = Seat Count × ARPU';
        factors.push(
            {
                metric: 'Seat Count / Active Subscribers',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.6 : undefined,
                description: 'Grow the number of paying subscribers through top-of-funnel acquisition and trial conversion.',
                weight: 0.6,
            },
            {
                metric: 'Average Revenue Per User (ARPU)',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.4 : undefined,
                description: 'Increase ARPU by upselling to higher-tier plans or adding paid add-ons.',
                weight: 0.4,
            }
        );
    }

    // ── SaaS: Churn ─────────────────────────────────────────────────────────────
    else if (goal.kpiId === 'saas-003' || goal.targetMetric === 'churn') {
        formula = 'Churn Rate = Churned Customers / Total Customers';
        factors.push(
            {
                metric: 'Customer Retention',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.5 : undefined,
                description: 'Improve the percentage of users staying on the platform through proactive customer success.',
                weight: 0.5,
            },
            {
                metric: 'Renewal Rate',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent ? changePercent * 0.3 : undefined,
                description: 'Increase the success rate of subscription renewals with automated renewal campaigns.',
                weight: 0.3,
            },
            {
                metric: 'Product Engagement',
                requiredChange: '↑ Increase engagement',
                description: 'Improve feature adoption so users experience consistent value before renewal.',
                weight: 0.2,
            }
        );
    }

    // ── SaaS: NRR ───────────────────────────────────────────────────────────────
    else if (goal.kpiId === 'saas-005' || goal.targetMetric === 'nrr') {
        formula = 'NRR = (Starting MRR + Expansion − Contraction − Churned) / Starting MRR';
        factors.push(
            {
                metric: 'Expansion Revenue',
                requiredChange: changeLabel,
                description: 'Increase upsell and cross-sell revenue from existing customers.',
                weight: 0.5,
            },
            {
                metric: 'Churn and Contraction',
                requiredChange: '↓ Reduce churned MRR',
                description: 'Reduce revenue lost to cancellations and downgrades.',
                weight: 0.5,
            }
        );
    }

    // ── Retail: Footfall ─────────────────────────────────────────────────────────
    else if (goal.kpiId === 'rt-002' || goal.targetMetric === 'footfall') {
        formula = 'Revenue = Footfall × Conversion Rate × AOV';
        factors.push(
            {
                metric: 'Store Visitor Count',
                requiredChange: changeLabel,
                requiredChangePercent: changePercent,
                description: 'Drive more in-store visits through local marketing, events, and promotions.',
                weight: 0.6,
            },
            {
                metric: 'In-Store Conversion Rate',
                requiredChange: '↑ Improve',
                description: 'Train staff to convert more visitors into buyers through product demos and personalised recommendations.',
                weight: 0.4,
            }
        );
    }

    // ── Generic Fallback ─────────────────────────────────────────────────────────
    else {
        formula = `${goal.targetMetric} = Direct improvement`;
        factors.push({
            metric: goal.targetMetric,
            requiredChange: changeLabel,
            requiredChangePercent: changePercent,
            description: `Drive direct improvement in ${goal.targetMetric} through focused operational effort.`,
            weight: 1.0,
        });
    }

    return {
        primaryMetric: goal.targetMetric,
        targetValue: goal.targetValue,
        changeDirection: goal.changeDirection,
        factors,
        formula,
    };
}

// Module 7: Goal Strategy Engine — Central Orchestrator
// Runs the 7-stage pipeline and produces the final Strategy Canvas

import { parseGoal, ParsedGoal } from './goal-parser';
import { decomposeGoal, DecomposedGoal } from './goal-decomposer';
import { generateActions, GeneratedAction } from './action-generator';
import { rankActions, RankedAction } from './action-ranker';
import { buildScenarios, ActionWithScenarios } from './scenario-builder';
import { splitByLocation, LocationPlan } from './location-splitter';

export interface StrategyCanvas {
    goal: ParsedGoal;
    decomposed: DecomposedGoal;
    topActions: RankedAction[];
    scenarios: ActionWithScenarios[];
    locationSplits: LocationPlan[];
    generatedAt: Date;
    pipelineMs: number; // Total processing time
}

export type PipelineStage =
    | 'PARSING'
    | 'MAPPING'
    | 'DECOMPOSING'
    | 'GENERATING'
    | 'RANKING'
    | 'BUILDING_SCENARIOS'
    | 'LOCATION_SPLIT'
    | 'COMPLETE';

export type StageCallback = (stage: PipelineStage) => void;

/**
 * Main orchestrator for the Module 7 pipeline.
 * Converts a natural language query into a full Strategy Canvas.
 *
 * @param rawQuery       - The user's natural language goal
 * @param domain         - Domain string from Module 3 (e.g. 'ECOMMERCE', 'SAAS')
 * @param locations      - Optional list of location names for Stage 7
 * @param onStageChange  - Optional callback fired at each pipeline stage transition
 */
export async function executeGoalPipeline(
    rawQuery: string,
    domain: string,
    locations: string[] = [],
    onStageChange?: StageCallback
): Promise<StrategyCanvas> {
    const start = Date.now();

    // Stage 1 & 2: Parse natural language + map to KPI
    onStageChange?.('PARSING');
    const goal = await parseGoal(rawQuery);

    onStageChange?.('MAPPING');
    // KPI mapping is embedded in parseGoal (kpiId is already set)

    // Stage 3: Decompose goal into sub-KPI factors
    onStageChange?.('DECOMPOSING');
    const decomposed = decomposeGoal(goal, domain);

    // Stage 4: Generate creative actions using AI
    onStageChange?.('GENERATING');
    const actions = await generateActions(decomposed, domain);

    // Stage 5: Rank and select top 3 actions
    onStageChange?.('RANKING');
    const topActions = rankActions(actions, 3);

    // Stage 6: Build 3-tier scenarios per top action
    onStageChange?.('BUILDING_SCENARIOS');
    const scenarios = await buildScenarios(topActions);

    // Stage 7: Split strategy by location (if applicable)
    onStageChange?.('LOCATION_SPLIT');
    const locationSplits = splitByLocation(goal.targetValue, scenarios, locations);

    onStageChange?.('COMPLETE');

    return {
        goal,
        decomposed,
        topActions,
        scenarios,
        locationSplits,
        generatedAt: new Date(),
        pipelineMs: Date.now() - start,
    };
}

// Module 7: Scenario Builder
// Generates Lean / Balanced / Premium execution plans for each ranked action

import { RankedAction } from './action-ranker';
import { generateCompletion } from '../ai/ollama-client';

export type ScenarioLevel = 'LEAN' | 'BALANCED' | 'PREMIUM';

export interface BudgetScenario {
    level: ScenarioLevel;
    label: string;         // Human-friendly: "Lean", "Balanced", "Premium"
    estimatedCost: string;
    executionPlan: string[];
    timeline: string;
    expectedKpiLift: string;
    monitoringMetrics: string[];
}

export interface ActionWithScenarios extends RankedAction {
    scenarios: BudgetScenario[];
}

// Robust JSON extraction from AI response
function extractJsonArray(text: string): BudgetScenario[] | null {
    try {
        const trimmed = text.trim();
        if (trimmed.startsWith('[')) return JSON.parse(trimmed);
        const fenced = trimmed.match(/```(?:json)?\s*([\s\S]*?)```/);
        if (fenced) return JSON.parse(fenced[1].trim());
        const arrayMatch = trimmed.match(/\[[\s\S]*\]/);
        if (arrayMatch) return JSON.parse(arrayMatch[0]);
    } catch { /* fall through */ }
    return null;
}

const LEVEL_META: Record<ScenarioLevel, { label: string; cost: string; timeline: string }> = {
    LEAN: { label: 'Lean', cost: '< $500', timeline: '2-4 weeks' },
    BALANCED: { label: 'Balanced', cost: '$500 – $5k', timeline: '1-2 months' },
    PREMIUM: { label: 'Premium', cost: '> $5k', timeline: '1-3 months' },
};

function buildFallbackScenarios(actionName: string): BudgetScenario[] {
    return [
        {
            level: 'LEAN',
            label: 'Lean',
            estimatedCost: '< $500',
            executionPlan: [
                `Research best practices for "${actionName}" using free resources.`,
                'Implement manually using existing team bandwidth.',
                'Track progress weekly with a simple spreadsheet or free analytics tool.',
            ],
            timeline: '2-4 weeks',
            expectedKpiLift: '3–7%',
            monitoringMetrics: ['Weekly metric delta', 'Manual conversion tracking'],
        },
        {
