// XML Parser using xml2js

import { parseStringPromise } from 'xml2js';
import { ParseResult } from './csv';

// Flatten XML object to tabular format
function flattenXMLObject(obj: unknown, prefix = ''): Record<string, unknown> {
    const result: Record<string, unknown> = {};

    if (obj === null || obj === undefined) {
        return result;
    }

    if (typeof obj !== 'object') {
        if (prefix) {
            result[prefix] = obj;
        }
        return result;
    }

    if (Array.isArray(obj)) {
        if (obj.length === 1) {
            // Single element arrays are common in xml2js output
            return flattenXMLObject(obj[0], prefix);
        }
        if (prefix) {
            result[prefix] = JSON.stringify(obj);
        }
        return result;
    }

    for (const [key, value] of Object.entries(obj as Record<string, unknown>)) {
        // Skip $ (attributes) and _ (text content) special keys for simplicity
        if (key === '$' || key === '_') continue;

        const newKey = prefix ? `${prefix}.${key}` : key;

        if (Array.isArray(value) && value.length === 1 && typeof value[0] !== 'object') {
            result[newKey] = value[0];
        } else if (typeof value === 'object') {
            Object.assign(result, flattenXMLObject(value, newKey));
        } else {
            result[newKey] = value;
        }
    }

    return result;
}

export async function parseXML(content: string): Promise<ParseResult> {
    try {
        const parsed = await parseStringPromise(content);

        // Find the root element and its children
        const rootKey = Object.keys(parsed)[0];
        const root = parsed[rootKey];

        // Find repeated elements (likely the data rows)
        let dataArray: unknown[] = [];

        for (const [key, value] of Object.entries(root)) {
            if (Array.isArray(value) && value.length > 1) {
                dataArray = value;
                break;
            }
        }

        // If no repeated elements found, try to use all children
        if (dataArray.length === 0) {
            const firstArrayProp = Object.values(root).find(v => Array.isArray(v));
            if (firstArrayProp && Array.isArray(firstArrayProp)) {
                dataArray = firstArrayProp;
            } else {
                dataArray = [root];
            }
        }

        // Flatten each element
        const flattenedData = dataArray.map(item => flattenXMLObject(item));

        // Collect all columns
        const columnSet = new Set<string>();
        for (const row of flattenedData) {
            Object.keys(row).forEach(key => columnSet.add(key));
        }
        const columns = Array.from(columnSet);

        // Normalize data
        const normalizedData = flattenedData.map(row => {
            const normalized: Record<string, unknown> = {};
            for (const col of columns) {
                normalized[col] = row[col] ?? '';
            }
            return normalized;
        });

        return {
            columns,
            data: normalizedData,
            rowCount: normalizedData.length,
            colCount: columns.length,
        };
    } catch (error) {
        throw new Error(`XML parsing failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
}

// Null value handler - fills missing values using statistical strategies

import { ColumnMeta, DataType } from '@/lib/prisma';

export interface NullHandlerResult {
    cleanedData: Record<string, unknown>[];
    nullsFilled: number;
}

export function handleNulls(
    data: Record<string, unknown>[],
    columnMeta: ColumnMeta[]
): NullHandlerResult {
    if (data.length === 0) {
        return { cleanedData: data, nullsFilled: 0 };
    }

    let nullsFilled = 0;
    const cleanedData = data.map(row => ({ ...row }));

    for (const col of columnMeta) {
        const columnName = col.originalName;
        const dataType = col.dataType;

        // Extract non-null values for this column
        const nonNullValues = cleanedData
            .map(row => row[columnName])
            .filter(v => v !== null && v !== undefined && v !== '');

        if (nonNullValues.length === 0) continue;

        // Determine fill strategy based on data type
        let fillValue: unknown;

        switch (dataType) {
            case 'NUMBER':
                fillValue = calculateMean(nonNullValues as number[]);
                break;
            case 'DATE':
                fillValue = calculateMedianDate(nonNullValues);
                break;
            case 'BOOLEAN':
                fillValue = calculateMode(nonNullValues);
                break;
            case 'TEXT':
            default:
                fillValue = calculateMode(nonNullValues);
                break;
        }

        // Fill nulls in cleaned data
        for (const row of cleanedData) {
            if (row[columnName] === null || row[columnName] === undefined || row[columnName] === '') {
                row[columnName] = fillValue;
                nullsFilled++;
            }
        }
    }

    return { cleanedData, nullsFilled };
}

// Calculate mean for numeric columns
function calculateMean(values: number[]): number {
    if (values.length === 0) return 0;
    const sum = values.reduce((acc, v) => acc + Number(v), 0);
    return Math.round((sum / values.length) * 100) / 100; // Round to 2 decimal places
}

// Calculate median date
function calculateMedianDate(values: unknown[]): string {
    if (values.length === 0) return new Date().toISOString().split('T')[0];

    const dates = values
        .map(v => new Date(String(v)).getTime())
        .filter(t => !isNaN(t))
        .sort((a, b) => a - b);

    if (dates.length === 0) return new Date().toISOString().split('T')[0];

    const mid = Math.floor(dates.length / 2);
    const medianTime = dates.length % 2 === 0
        ? (dates[mid - 1] + dates[mid]) / 2
        : dates[mid];

    return new Date(medianTime).toISOString().split('T')[0];
}

// Calculate mode (most frequent value)
function calculateMode(values: unknown[]): unknown {
    if (values.length === 0) return '';

    const frequency = new Map<string, number>();
    for (const value of values) {
        const key = String(value);
        frequency.set(key, (frequency.get(key) || 0) + 1);
    }

    let maxFreq = 0;
    let mode = values[0];

    for (const [value, freq] of frequency.entries()) {
        if (freq > maxFreq) {
            maxFreq = freq;
            mode = value;
        }
    }

    return mode;
}

// Module 5B — Filter Engine
// Applies filters, drill-down, and cross-filtering to dataset rows

import type {
    DataRow,
    Filter,
    FilterState,
    DateRangeFilter,
    CategoryFilter,
    ValueFilter,
    DrillDownPath,
    CrossFilterEvent,
    ProjectDataMap,
} from './types';

// ─── Core Filter Application ─────────────────────────────────────

/**
 * Apply all filters to a set of rows.
 * Filters are AND-combined (all must match).
 */
export function applyFilters(rows: DataRow[], filters: Filter[]): DataRow[] {
    if (filters.length === 0) return rows;

    let result = rows;

    for (const filter of filters) {
        switch (filter.type) {
            case 'date_range':
                result = applyDateRangeFilter(result, filter);
                break;
            case 'category':
                result = applyCategoryFilter(result, filter);
                break;
            case 'value':
                result = applyValueFilter(result, filter);
                break;
        }
    }

    return result;
}

// ─── Individual Filter Types ──────────────────────────────────────

/**
 * Filter rows by date range.
 */
function applyDateRangeFilter(rows: DataRow[], filter: DateRangeFilter): DataRow[] {
    const col = filter.column.toLowerCase();
    const fromDate = filter.from ? new Date(filter.from) : null;
    const toDate = filter.to ? new Date(filter.to) : null;

    return rows.filter(row => {
        const rawValue = row[col];
        if (rawValue === null || rawValue === undefined) return false;

        const date = new Date(rawValue as string | number);
        if (isNaN(date.getTime())) return false;

        if (fromDate && date < fromDate) return false;
        if (toDate && date > toDate) return false;

        return true;
    });
}

/**
 * Filter rows by categorical values (inclusion list).
 */
function applyCategoryFilter(rows: DataRow[], filter: CategoryFilter): DataRow[] {
    const col = filter.column.toLowerCase();
    const allowedValues = new Set(filter.values.map(v => String(v).toLowerCase()));

    return rows.filter(row => {
        const value = row[col];
        if (value === null || value === undefined) return false;
        return allowedValues.has(String(value).toLowerCase());
    });
}

/**
 * Filter rows by value comparison.
 */
function applyValueFilter(rows: DataRow[], filter: ValueFilter): DataRow[] {
    const col = filter.column.toLowerCase();

    return rows.filter(row => {
        const rawValue = row[col];
        if (rawValue === null || rawValue === undefined) return false;

        const numValue = typeof rawValue === 'number' ? rawValue : parseFloat(String(rawValue));
        const filterValue = typeof filter.value === 'number' ? filter.value : parseFloat(String(filter.value));

        if (isNaN(numValue) || isNaN(filterValue)) {
            // Fall back to string comparison
            const strValue = String(rawValue).toLowerCase();
            const strFilter = String(filter.value).toLowerCase();

            switch (filter.operator) {
                case 'eq': return strValue === strFilter;
                case 'neq': return strValue !== strFilter;
                default: return false;
            }
        }

        switch (filter.operator) {
            case 'eq': return numValue === filterValue;
            case 'neq': return numValue !== filterValue;
            case 'gt': return numValue > filterValue;
            case 'gte': return numValue >= filterValue;
            case 'lt': return numValue < filterValue;
            case 'lte': return numValue <= filterValue;
            default: return true;
        }
    });
}

// ─── Drill-Down ───────────────────────────────────────────────────

/**
 * Apply drill-down path to progressively narrow the dataset.
 * Each step in the path adds a filter on column=value.
 */
export function applyDrillDown(rows: DataRow[], drillPath: DrillDownPath): DataRow[] {
    let result = rows;

    for (const step of drillPath.steps) {
        const col = step.column.toLowerCase();
        result = result.filter(row => {
            const value = row[col];
            return String(value ?? '').toLowerCase() === step.value.toLowerCase();
        });
    }

    return result;
}

// ─── Cross-Filtering ──────────────────────────────────────────────

/**
 * Generate filter criteria from a cross-filter event.
 * When a user clicks a value in chart A, this produces filters
 * that are applied to the datasets of related charts B, C, etc.
 */
export function buildCrossFilters(event: CrossFilterEvent): Filter[] {
    return [{
        type: 'category',
        column: event.selectedColumn,
        values: [String(event.selectedValue)],
    }];
}

/**
 * Apply cross-filter to a data map, returning filtered rows per source.
 */
export function applyCrossFilter(
    dataMap: ProjectDataMap,
    event: CrossFilterEvent
): Map<string, DataRow[]> {
    const filters = buildCrossFilters(event);
    const result = new Map<string, DataRow[]>();

    for (const [sourceId, source] of dataMap.sources) {
        // Only filter if the source has the selected column
        const col = event.selectedColumn.toLowerCase();
        if (source.columns.includes(col)) {
            result.set(sourceId, applyFilters(source.rows, filters));
        } else {
            result.set(sourceId, source.rows);
        }
    }

    return result;
}

// ─── Filter Option Discovery ──────────────────────────────────────

/**
 * Discover available filter options for a column.
 * Returns unique values sorted alphabetically.
 */
export function getFilterOptions(
    dataMap: ProjectDataMap,
    sourceId: string,
    column: string
): { value: string; count: number }[] {
    const source = dataMap.sources.get(sourceId);
    if (!source) return [];

    const col = column.toLowerCase();
    const counts = new Map<string, number>();

    for (const row of source.rows) {
        const value = row[col];
        if (value === null || value === undefined) continue;
        const key = String(value);
        counts.set(key, (counts.get(key) || 0) + 1);
    }

    return Array.from(counts.entries())
        .map(([value, count]) => ({ value, count }))
        .sort((a, b) => a.value.localeCompare(b.value));
}

/**
 * Discover date range for a date column.
 */
export function getDateRange(
    dataMap: ProjectDataMap,
    sourceId: string,
    column: string
): { min: string; max: string } | null {
    const source = dataMap.sources.get(sourceId);
    if (!source) return null;

    const col = column.toLowerCase();
    let minDate: Date | null = null;
    let maxDate: Date | null = null;

    for (const row of source.rows) {
        const rawValue = row[col];
        if (!rawValue) continue;

        const date = new Date(rawValue as string | number);
        if (isNaN(date.getTime())) continue;

        if (!minDate || date < minDate) minDate = date;
        if (!maxDate || date > maxDate) maxDate = date;
    }

    if (!minDate || !maxDate) return null;

    return {
        min: minDate.toISOString().split('T')[0],
        max: maxDate.toISOString().split('T')[0],
    };
}

/**
 * Find available drill-down columns for a KPI.
 * Returns non-numeric, non-date categorical columns.
 */
export function findDrillDownColumns(
    dataMap: ProjectDataMap,
    sourceId: string
): string[] {
    const source = dataMap.sources.get(sourceId);
    if (!source || source.rows.length === 0) return [];

    const sample = source.rows[0];
    const drillCols: string[] = [];

    for (const [key, value] of Object.entries(sample)) {
        // Skip numeric columns and common ID columns
        if (key.endsWith('id') || key === 'id') continue;
        if (typeof value === 'number') continue;

        // Check it's categorical (reasonable number of unique values)
        const uniqueCount = new Set(source.rows.map(r => r[key])).size;
        if (uniqueCount > 1 && uniqueCount <= Math.min(50, source.rows.length * 0.5)) {
            drillCols.push(key);
        }
    }

    return drillCols;
}

// Module 5B — Visualization & Interaction Engine
// Main orchestrator: computes dashboard data from lineage metadata + warehouse data

import db from '../prisma';
import type { KPILineageEntry, KPIJoinPath, KPIAggregation } from '../prisma';
import type {
    DashboardDataPayload,
    ChartDataPayload,
    FilterState,
    DrillDownPath,
    CrossFilterEvent,
    KPIDataResult,
    TimeGranularity,
    ProjectDataMap,
} from './types';
import { loadProjectData, findSourceForColumn } from './data-loader';
import { computeKPI, computeTimeSeries, computeGroupedKPI } from './kpi-computer';
import { applyFilters, applyDrillDown, applyCrossFilter, findDrillDownColumns, getFilterOptions } from './filter-engine';
import type { DashboardConfigSchema, DashboardSection, DashboardKPICard } from '../dashboard/types';
import { loadBlueprintWithKPIs, type ApprovedKPIWithRelations } from '../kpi/blueprint-loader';

// ─── Main Dashboard Data Computation ──────────────────────────────

/**
 * Compute all dashboard data for a project.
 * This is the main entry point for Module 5B.
 *
 * Pipeline:
 * 1. Load dashboard config (Module 5A)
 * 2. Load KPI lineage registry (Module 4D-B)
 * 3. Load project data into memory
 * 4. For each KPI in the dashboard, compute its value
 * 5. Apply any active filters
 * 6. Return complete DashboardDataPayload
 */
export async function computeDashboardData(
    projectId: string,
    filterState?: FilterState,
    drillDownPaths?: DrillDownPath[]
): Promise<DashboardDataPayload> {
    const startTime = Date.now();
    console.log('[Visualization] Computing dashboard data for:', projectId);

    // 1. Load dashboard config from Module 5A
    const dashboardConfig = await loadDashboardConfig(projectId);
    if (!dashboardConfig) {
        throw new Error(`No dashboard config found for project: ${projectId}. Run Module 5A first.`);
    }

    // 2. Load KPI lineage registry from Module 4D-B
    const lineageEntries = await loadLineageRegistry(projectId);

    // 3. Load project data
    const dataMap = await loadProjectData(projectId);

    // 4. Apply global filters to data if present
    let filteredDataMap = dataMap;
    if (filterState && filterState.filters.length > 0) {
        filteredDataMap = applyGlobalFilters(dataMap, filterState);
    }

    // 5. Compute each KPI
    const charts: ChartDataPayload[] = [];
    let computedCount = 0;
    let skippedCount = 0;
    const granularity = filterState?.granularity || 'monthly';

    for (const section of dashboardConfig.sections) {
        for (const card of section.cards) {
            const lineage = lineageEntries.find(e => e.kpiId === card.kpiId || e.id === card.kpiId);

            if (!lineage) {
                console.log(`[Visualization] No lineage found for KPI: ${card.kpiName}, skipping`);
                skippedCount++;
                continue;
            }

            try {
                // Check for drill-down
                const drillDown = drillDownPaths?.find(dp => dp.kpiId === card.kpiId);

                let data: KPIDataResult;
                if (drillDown?.groupByColumn) {
                    data = computeGroupedKPI(lineage, filteredDataMap, drillDown.groupByColumn);
                } else if (card.chartSelection?.chartType === 'line' || card.chartSelection?.chartType === 'bar') {
                    data = computeTimeSeries(lineage, filteredDataMap, granularity);
                } else {
                    data = computeKPI(lineage, filteredDataMap);
                }

                // Find available drill-down columns
                const primarySource = lineage.sources[0];
                const drillDownCols = primarySource
                    ? findDrillDownColumns(filteredDataMap, primarySource.sourceId)
                    : [];

                // Find available group-by columns  
                const groupByCols = drillDownCols.filter(c =>
                    !c.toLowerCase().includes('date') && !c.toLowerCase().includes('time')
                );

                charts.push({
                    kpiId: card.kpiId,
                    kpiName: card.kpiName,
                    chartType: card.chartSelection?.chartType || 'bar',
                    cardSize: card.cardSize,
                    sectionId: section.id,
                    data,
                    availableDrillDowns: drillDownCols,
                    availableGroupBys: groupByCols,
                });

                computedCount++;
            } catch (error) {
                console.error(`[Visualization] Error computing KPI ${card.kpiName}:`, error);
                skippedCount++;
            }
        }
    }

    const executionTimeMs = Date.now() - startTime;
    console.log(`[Visualization] Computed ${computedCount} KPIs in ${executionTimeMs}ms (${skippedCount} skipped)`);

    return {
        projectId,
        charts,
        appliedFilters: filterState || { filters: [], granularity: 'monthly' },
        drillDownPaths: drillDownPaths || [],
        computedAt: new Date().toISOString(),
        metadata: {
            totalKPIs: computedCount + skippedCount,
            computedKPIs: computedCount,
            skippedKPIs: skippedCount,
            executionTimeMs,
        },
    };
}

// ─── Single KPI Computation ───────────────────────────────────────

/**
 * Compute data for a single KPI (used by the per-KPI API endpoint).
 */
export async function computeSingleKPI(
    projectId: string,
    kpiId: string,
    options?: {
        granularity?: TimeGranularity;
        groupBy?: string;
        filters?: FilterState;
    }
): Promise<KPIDataResult | null> {
    const lineageEntries = await loadLineageRegistry(projectId);
    const lineage = lineageEntries.find(e => e.kpiId === kpiId || e.id === kpiId);

    if (!lineage) return null;

    const dataMap = await loadProjectData(projectId);
    let filteredDataMap = dataMap;

    if (options?.filters && options.filters.filters.length > 0) {
        filteredDataMap = applyGlobalFilters(dataMap, options.filters);
    }

    if (options?.groupBy) {
        return computeGroupedKPI(lineage, filteredDataMap, options.groupBy);
    }

    if (options?.granularity) {
        return computeTimeSeries(lineage, filteredDataMap, options.granularity);
    }

    return computeKPI(lineage, filteredDataMap);
}

// ─── Cross-Filter Computation ─────────────────────────────────────

/**
 * Apply cross-filter and recompute affected KPIs.
 */
export async function applyCrossFilterAndRecompute(
    projectId: string,
    event: CrossFilterEvent,
    granularity: TimeGranularity = 'monthly'
): Promise<ChartDataPayload[]> {
    const lineageEntries = await loadLineageRegistry(projectId);
    const dataMap = { projectId, sources: new Map() } as ProjectDataMap;

    // Apply cross-filter to data
    const filteredRows = applyCrossFilter(dataMap, event);

    // Create filtered data map
    const filteredDataMap: ProjectDataMap = {
        projectId,
        sources: new Map(),
    };
    for (const [sourceId, rows] of filteredRows) {
        const original = dataMap.sources.get(sourceId);
        if (original) {
            filteredDataMap.sources.set(sourceId, {
                ...original,
                rows,
            });
        }
    }

    // Recompute affected KPIs
    const results: ChartDataPayload[] = [];
    for (const kpiId of event.affectedKpiIds) {
        const lineage = lineageEntries.find(e => e.kpiId === kpiId || e.id === kpiId);
        if (!lineage) continue;

        const data = computeTimeSeries(lineage, filteredDataMap, granularity);
        const primarySource = lineage.sources[0];
        const drillDownCols = primarySource
            ? findDrillDownColumns(filteredDataMap, primarySource.sourceId)
            : [];

        results.push({
            kpiId,
            kpiName: lineage.kpiName,
            chartType: 'bar', // Will be overridden by frontend
            cardSize: 'md',
            sectionId: '',
            data,
            availableDrillDowns: drillDownCols,
            availableGroupBys: drillDownCols.filter(c =>
                !c.toLowerCase().includes('date')
            ),
        });
    }

    return results;
}

// ─── Internal Helpers ─────────────────────────────────────────────

/**
 * Load dashboard config from Module 5A.
 */
async function loadDashboardConfig(projectId: string): Promise<DashboardConfigSchema | null> {
    const record = await db.dashboardConfig.findUnique({
        where: { projectId },
    });

    if (!record) return null;

    return {
        projectId: record.projectId,
        sections: record.sections as unknown as DashboardSection[],
        sidebarConfig: record.sidebarConfig as unknown as DashboardConfigSchema['sidebarConfig'],
        metadata: record.metadata as unknown as DashboardConfigSchema['metadata'],
        version: record.version,
    };
}

/**
 * Load KPI lineage entries from the Relational Blueprint.
 */
async function loadLineageRegistry(projectId: string): Promise<KPILineageEntry[]> {
    const blueprint = await loadBlueprintWithKPIs(projectId);
    if (!blueprint || blueprint.kpis.length === 0) return [];

    return blueprint.kpis.map((kpi: ApprovedKPIWithRelations) => ({
        id: kpi.id,
        projectId,
        kpiId: kpi.kpiLibraryId || kpi.id,
        kpiName: kpi.name,
        domain: blueprint.domain || 'General',
        formula: kpi.lineage?.formula || '',
        category: kpi.category,
        sources: [{
            sourceId: kpi.sourceTable,
            sourceName: kpi.sourceTable,
            columns: kpi.aggregations.map(a => a.column),
            role: 'PRIMARY'
        }],
        joinPaths: (kpi.lineage?.joins as unknown as KPIJoinPath[]) || [],
        aggregations: kpi.aggregations.map(a => ({
            function: a.function as KPIAggregation['function'],
            column: a.column,
            sourceId: kpi.sourceTable,
        })),
        technicalExplanation: 'Generated from relational BI Definition Layer',
        businessExplanation: 'Domain-defined structured metric',
        aiEnhanced: false,
        confidence: 100,
        tracedAt: kpi.updatedAt,
    } as KPILineageEntry));
}

/**
 * Apply filters to all sources in a data map.
 */
function applyGlobalFilters(
    dataMap: ProjectDataMap,
    filterState: FilterState
): ProjectDataMap {
    const filtered: ProjectDataMap = {
        projectId: dataMap.projectId,
        sources: new Map(),
    };

    for (const [sourceId, source] of dataMap.sources) {
        // Only apply filters whose columns exist in this source
        const applicableFilters = filterState.filters.filter(f =>
            source.columns.includes(f.column.toLowerCase())
        );

        filtered.sources.set(sourceId, {
            ...source,
            rows: applicableFilters.length > 0
                ? applyFilters(source.rows, applicableFilters)
                : source.rows,
        });
    }

    return filtered;
}

// Re-export for API convenience
export { getFilterOptions } from './filter-engine';
export { getDateRange, findDrillDownColumns } from './filter-engine';
export type { DashboardDataPayload, ChartDataPayload, FilterState, DrillDownPath, CrossFilterEvent } from './types';

// Module 5B — KPI Computer
// Core computation engine: reads lineage metadata and computes KPI values
// from in-memory data using joins and aggregations

import type { KPILineageEntry, KPIJoinPath, KPIAggregation } from '../prisma';
import type {
    DataRow,
    ProjectDataMap,
    KPIDataResult,
    KPIDataPoint,
    TimeGranularity,
} from './types';

// ─── Core KPI Computation ─────────────────────────────────────────

/**
 * Compute a single KPI value from lineage metadata and in-memory data.
 * This is the heart of Module 5B.
 */
export function computeKPI(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap
): KPIDataResult {
    const startTime = Date.now();

    // Step 1: Gather rows from all contributing sources
    let rows = gatherSourceRows(lineage, dataMap);

    // Step 2: Perform joins if multiple sources
    if (lineage.joinPaths.length > 0 && lineage.sources.length > 1) {
        rows = performMultiSourceJoin(lineage, dataMap);
    }

    // Step 3: Apply aggregations from lineage
    const currentValue = computeAggregatedValue(rows, lineage.aggregations, lineage.formula);

    // Step 4: Build data points (top-level aggregation as single point)
    const dataPoints: KPIDataPoint[] = [{
        label: 'Current',
        value: currentValue,
    }];

    console.log(`[KPIComputer] ${lineage.kpiName} = ${currentValue} (${Date.now() - startTime}ms)`);

    return {
        kpiId: lineage.kpiId,
        kpiName: lineage.kpiName,
        formula: lineage.formula,
        category: lineage.category,
        currentValue,
        trend: 'flat',
        dataPoints,
        computedAt: new Date().toISOString(),
    };
}

// ─── Time-Series Computation ──────────────────────────────────────

/**
 * Compute KPI values grouped by time granularity.
 * Produces data points suitable for line/bar charts.
 */
export function computeTimeSeries(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap,
    granularity: TimeGranularity,
    dateColumn?: string
): KPIDataResult {
    let rows = gatherSourceRows(lineage, dataMap);

    if (lineage.joinPaths.length > 0 && lineage.sources.length > 1) {
        rows = performMultiSourceJoin(lineage, dataMap);
    }

    // Find the date column
    const dateCols = findDateColumns(rows);
    const dateCol = dateColumn || dateCols[0];

    if (!dateCol) {
        // No date column found — fall back to simple computation
        return computeKPI(lineage, dataMap);
    }

    // Group rows by time bucket
    const groups = groupByTimeBucket(rows, dateCol, granularity);

    // Compute aggregation per bucket
    const dataPoints: KPIDataPoint[] = [];
    let latestValue = 0;

    const sortedBuckets = Array.from(groups.entries()).sort(([a], [b]) => a.localeCompare(b));

    for (const [bucket, bucketRows] of sortedBuckets) {
        const value = computeAggregatedValue(bucketRows, lineage.aggregations, lineage.formula);
        dataPoints.push({ label: bucket, value });
        latestValue = value;
    }

    // Compute trend from last two data points
    const trend = computeTrend(dataPoints);

    return {
        kpiId: lineage.kpiId,
        kpiName: lineage.kpiName,
        formula: lineage.formula,
        category: lineage.category,
        currentValue: latestValue,
        previousValue: dataPoints.length >= 2 ? dataPoints[dataPoints.length - 2].value : undefined,
        trend: trend.direction,
        trendPercent: trend.percent,
        dataPoints,
        computedAt: new Date().toISOString(),
    };
}

// ─── Grouped KPI (Drill-Down) ─────────────────────────────────────

/**
 * Compute KPI values grouped by a categorical column.
 * Used for drill-down: e.g., Revenue by Category → by Region.
 */
export function computeGroupedKPI(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap,
    groupByColumn: string
): KPIDataResult {
    let rows = gatherSourceRows(lineage, dataMap);

    if (lineage.joinPaths.length > 0 && lineage.sources.length > 1) {
        rows = performMultiSourceJoin(lineage, dataMap);
    }

    const col = groupByColumn.toLowerCase();

    // Group rows by categorical value
    const groups = new Map<string, DataRow[]>();
    for (const row of rows) {
        const key = String(row[col] ?? 'Unknown');
        if (!groups.has(key)) groups.set(key, []);
        groups.get(key)!.push(row);
    }

    // Compute aggregation per group
    const dataPoints: KPIDataPoint[] = [];
    for (const [key, groupRows] of groups) {
        const value = computeAggregatedValue(groupRows, lineage.aggregations, lineage.formula);
        dataPoints.push({ label: key, value });
    }

    // Sort by value descending
    dataPoints.sort((a, b) => b.value - a.value);

    const totalValue = dataPoints.reduce((sum, dp) => sum + dp.value, 0);

    return {
        kpiId: lineage.kpiId,
        kpiName: lineage.kpiName,
        formula: lineage.formula,
        category: lineage.category,
        currentValue: totalValue,
        dataPoints,
        computedAt: new Date().toISOString(),
    };
}

// ─── Internal Helpers ─────────────────────────────────────────────

/**
 * Gather rows from the primary source for a KPI.
 */
function gatherSourceRows(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap
): DataRow[] {
    if (lineage.sources.length === 0) return [];

    const primarySource = lineage.sources.find(s => s.role === 'PRIMARY') || lineage.sources[0];
    const sourceData = dataMap.sources.get(primarySource.sourceId);

    return sourceData?.rows ?? [];
}

/**
 * Perform multi-source join using lineage join paths.
 * Implements INNER, LEFT, RIGHT, FULL joins.
 */
function performMultiSourceJoin(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap
): DataRow[] {
    if (lineage.sources.length < 2) {
        return gatherSourceRows(lineage, dataMap);
    }

    // Start with primary source
    const primarySource = lineage.sources.find(s => s.role === 'PRIMARY') || lineage.sources[0];
    let result = dataMap.sources.get(primarySource.sourceId)?.rows ?? [];

    // For each join path, join with the target
    for (const joinPath of lineage.joinPaths) {
        const targetSourceId = findSourceIdByTableName(
            lineage, dataMap, joinPath.targetTable
        );
        if (!targetSourceId) continue;

        const rightRows = dataMap.sources.get(targetSourceId)?.rows ?? [];
        result = performJoin(result, rightRows, joinPath);
    }

    return result;
}

/**
 * Perform a join between two datasets.
 */
function performJoin(
    leftRows: DataRow[],
    rightRows: DataRow[],
    joinPath: KPIJoinPath
): DataRow[] {
    const leftCol = joinPath.sourceColumn.toLowerCase();
    const rightCol = joinPath.targetColumn.toLowerCase();

    // Build a lookup index on the right side for performance
    const rightIndex = new Map<string, DataRow[]>();
    for (const row of rightRows) {
        const key = String(row[rightCol] ?? '');
        if (!rightIndex.has(key)) rightIndex.set(key, []);
        rightIndex.get(key)!.push(row);
    }

    const joined: DataRow[] = [];
    const matchedRight = new Set<number>();

    for (const leftRow of leftRows) {
        const key = String(leftRow[leftCol] ?? '');
        const matches = rightIndex.get(key) || [];

        if (matches.length > 0) {
            for (const rightRow of matches) {
                // Merge rows, prefixing conflicting keys
                joined.push({ ...rightRow, ...leftRow });
            }
        } else if (joinPath.joinType === 'LEFT' || joinPath.joinType === 'FULL') {
            joined.push({ ...leftRow });
        }
    }

    // For FULL joins, add unmatched right rows
    if (joinPath.joinType === 'FULL') {
        for (let i = 0; i < rightRows.length; i++) {
            const key = String(rightRows[i][rightCol] ?? '');
            const hasLeftMatch = leftRows.some(lr => String(lr[leftCol] ?? '') === key);
            if (!hasLeftMatch) {
                joined.push({ ...rightRows[i] });
            }
        }
    }

    return joined;
}

/**
 * Compute an aggregated value from rows using lineage aggregation definitions.
 * Supports SUM, AVG, COUNT, COUNT_DISTINCT, MIN, MAX.
 */
function computeAggregatedValue(
    rows: DataRow[],
    aggregations: KPIAggregation[],
    formula: string
): number {
    if (rows.length === 0) return 0;

    // If no aggregations defined, try to parse formula directly
    if (aggregations.length === 0) {
        return parseAndComputeFormula(rows, formula);
    }

    // For single aggregation, compute directly
    if (aggregations.length === 1) {
        return applyAggregation(rows, aggregations[0]);
    }

    // For complex formulas (e.g., SUM(a) / SUM(b)), compute each part
    // and combine using the formula pattern
    const values = new Map<string, number>();
    for (const agg of aggregations) {
        const key = `${agg.function}(${agg.column})`;
        values.set(key, applyAggregation(rows, agg));
    }

    return evaluateFormulaWithValues(formula, values);
}

/**
 * Apply a single aggregation function to rows.
 */
export function applyAggregation(rows: DataRow[], aggregation: KPIAggregation): number {
    const col = aggregation.column.toLowerCase();

    // Handle COUNT/COUNT_DISTINCT first — they don't need numeric values
    if (aggregation.function === 'COUNT') {
        return rows.length;
    }
    if (aggregation.function === 'COUNT_DISTINCT') {
        const uniqueValues = new Set(rows.map(r => r[col]).filter(v => v !== null && v !== undefined));
        return uniqueValues.size;
    }

    // Extract numeric values for math aggregations
    const values = rows
        .map(r => r[col])
        .filter(v => v !== null && v !== undefined)
        .map(v => typeof v === 'number' ? v : parseFloat(String(v)))
        .filter(v => !isNaN(v));

    if (values.length === 0) return 0;

    switch (aggregation.function) {
        case 'SUM':
            return values.reduce((sum, v) => sum + v, 0);
        case 'AVG':
            return values.reduce((sum, v) => sum + v, 0) / values.length;
        case 'MIN':
            return Math.min(...values);
        case 'MAX':
            return Math.max(...values);
        default:
            return 0;
    }
}

/**
 * Parse a formula string and compute its value from rows.
 * Handles common patterns: SUM(col), COUNT(col), AVG(col), etc.
 */
function parseAndComputeFormula(rows: DataRow[], formula: string): number {
    const upper = formula.toUpperCase().trim();

    // Match common patterns
    const sumMatch = upper.match(/SUM\((\w+)\)/);
    if (sumMatch) {
        const col = sumMatch[1].toLowerCase();
        return rows
            .map(r => typeof r[col] === 'number' ? r[col] as number : parseFloat(String(r[col] ?? '0')))
            .filter(v => !isNaN(v))
            .reduce((sum, v) => sum + v, 0);
    }

    const countMatch = upper.match(/COUNT\((\w+)\)/);
    if (countMatch) {
        return rows.length;
    }

    const avgMatch = upper.match(/AVG\((\w+)\)/);
    if (avgMatch) {
        const col = avgMatch[1].toLowerCase();
        const values = rows
            .map(r => typeof r[col] === 'number' ? r[col] as number : parseFloat(String(r[col] ?? '0')))
            .filter(v => !isNaN(v));
        return values.length > 0 ? values.reduce((s, v) => s + v, 0) / values.length : 0;
    }

    return 0;
}

/**
 * Evaluate a formula like "SUM(revenue) / SUM(orders)" given pre-computed values.
 */
function evaluateFormulaWithValues(formula: string, values: Map<string, number>): number {
    let expression = formula.toUpperCase();

    // Replace all aggregation expressions with their computed values
    for (const [key, val] of values) {
        expression = expression.replace(key.toUpperCase(), String(val));
    }

    // Simple arithmetic eval for patterns like "X / Y", "X - Y", "X * Y"
    try {
        // Only allow numbers and basic operators for safety
        const sanitized = expression.replace(/[^0-9.+\-*/() ]/g, '');
        if (sanitized.trim() === '') return 0;
        // Use Function constructor for safe math evaluation
        const result = new Function(`return (${sanitized})`)();
        return typeof result === 'number' && isFinite(result) ? result : 0;
    } catch {
        return 0;
    }
}

// ─── Time Bucketing ───────────────────────────────────────────────

/**
 * Find columns that look like dates in a dataset.
 */
function findDateColumns(rows: DataRow[]): string[] {
    if (rows.length === 0) return [];

    const sample = rows[0];
    const dateCols: string[] = [];

    for (const [key, value] of Object.entries(sample)) {
        if (isDateLikeColumn(key) || isDateLikeValue(value)) {
            dateCols.push(key);
        }
    }

    return dateCols;
}

function isDateLikeColumn(name: string): boolean {
    const dateKeywords = ['date', 'time', 'created', 'updated', 'timestamp', 'day', 'month', 'year', 'order_date', 'orderdate'];
    return dateKeywords.some(kw => name.toLowerCase().includes(kw));
}

function isDateLikeValue(value: unknown): boolean {
    if (typeof value !== 'string') return false;
    // ISO date pattern or common date patterns
    return /^\d{4}-\d{2}-\d{2}/.test(value) || /^\d{2}\/\d{2}\/\d{4}/.test(value);
}

/**
 * Group rows by time bucket (daily, weekly, monthly, quarterly).
 */
function groupByTimeBucket(
    rows: DataRow[],
    dateColumn: string,
    granularity: TimeGranularity
): Map<string, DataRow[]> {
    const groups = new Map<string, DataRow[]>();
    const col = dateColumn.toLowerCase();

    for (const row of rows) {
        const rawDate = row[col];
        if (!rawDate) continue;

        const date = parseDate(rawDate);
        if (!date) continue;

        const bucket = formatBucket(date, granularity);
        if (!groups.has(bucket)) groups.set(bucket, []);
        groups.get(bucket)!.push(row);
    }

    return groups;
}

function parseDate(value: unknown): Date | null {
    if (value instanceof Date) return value;
    if (typeof value === 'string' || typeof value === 'number') {
        const d = new Date(value);
        return isNaN(d.getTime()) ? null : d;
    }
    return null;
}

function formatBucket(date: Date, granularity: TimeGranularity): string {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');

    switch (granularity) {
        case 'daily':
            return `${y}-${m}-${d}`;
        case 'weekly': {
            // ISO week start (Monday)
            const day = date.getDay();
            const weekStart = new Date(date);
            weekStart.setDate(date.getDate() - (day === 0 ? 6 : day - 1));
            const wy = weekStart.getFullYear();
            const wm = String(weekStart.getMonth() + 1).padStart(2, '0');
            const wd = String(weekStart.getDate()).padStart(2, '0');
            return `${wy}-W${wm}${wd}`;
        }
        case 'monthly':
            return `${y}-${m}`;
        case 'quarterly': {
            const q = Math.ceil((date.getMonth() + 1) / 3);
            return `${y}-Q${q}`;
        }
    }
}

// ─── Trend Computation ───────────────────────────────────────────

function computeTrend(dataPoints: KPIDataPoint[]): { direction: 'up' | 'down' | 'flat'; percent: number } {
    if (dataPoints.length < 2) {
        return { direction: 'flat', percent: 0 };
    }

    const current = dataPoints[dataPoints.length - 1].value;
    const previous = dataPoints[dataPoints.length - 2].value;

    if (previous === 0) {
        return { direction: current > 0 ? 'up' : 'flat', percent: 0 };
    }

    const percent = ((current - previous) / Math.abs(previous)) * 100;
    const direction = percent > 1 ? 'up' : percent < -1 ? 'down' : 'flat';

    return { direction, percent: Math.round(percent * 100) / 100 };
}

// ─── Utility ──────────────────────────────────────────────────────

/**
 * Find sourceId by looking up table names in the lineage sources.
 */
function findSourceIdByTableName(
    lineage: KPILineageEntry,
    dataMap: ProjectDataMap,
    tableName: string
): string | null {
    const lower = tableName.toLowerCase();

    // Check lineage sources first
    const lineageSource = lineage.sources.find(
        s => s.sourceName.toLowerCase().replace(/\.[^.]+$/, '') === lower
    );
    if (lineageSource) return lineageSource.sourceId;

    // Check data map
    for (const source of dataMap.sources.values()) {
        if (source.sourceName.toLowerCase().replace(/\.[^.]+$/, '') === lower) {
            return source.sourceId;
        }
    }

    return null;
}

