            const results: string[] = [];
            const list = fs.readdirSync(dir);
            list.forEach(file => {
                file = path.resolve(dir, file);
                const stat = fs.statSync(file);
                if (stat && stat.isDirectory()) {
                    results.push(...getFilesRecursive(file));
                } else if (file.toLowerCase().endsWith('.csv')) {
                    results.push(file);
                }
            });
            return results;
