            const readSize = Math.min(stats.size, 1024 * 1024);
            const buffer = Buffer.alloc(readSize);
            const fd = fs.openSync(fullPath, 'r');
            fs.readSync(fd, buffer, 0, readSize, 0);
            fs.closeSync(fd);
            
            const previewContent = buffer.toString('utf8');
